insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('수원 화성 순교성지', '순교성지', '수원', '경기', '경기도 수원시 팔달구 정조로 780', NULL, '조선시대 천주교 신자들이 순교한 역사적 장소로 신앙의 증거지입니다.', NULL, NULL, NULL, '수원 화성, 행궁, 화성 행궁, 방화수류정, 화성어차', '수원 교구 피정센터, 화성 관광호텔, 팔달구 모텔촌'),
  ('절두산 순교성지', '순교성지', '서울', '서울', '서울시 마포구 토정로6 (합정동)', '양화진 나루터 위 잠두봉. 이곳은 원래 한강의 빼어난 경관으로 유명했지만, 1866년 병인박해 때 수많은 천주교인이 이곳에서 참수되면서 ''절두산(切頭山)''이라는 비극적인 이름을 얻었다. 28위 성인의 유해를 모신 성해실, 순교 관련 유물을 전시하는 박물관, 한강을 내려다보는 야외 전시장이 있다. 합정역에서 도보 5분, 한강 자전거길과도 연결되어 접근성이 뛰어나다. 특히 해질녘 한강 너머로 지는 노을과 순교자 동상의 실루엣이 어우러지는 풍경은 사진작가들의 단골 촬영 포인트다.', '1866년 병인박해 때 다수의 천주교인이 참수된 곳. 28위 성인의 유해 안치. ''서울 순례길'' 3코스(일치의 길) 구간.', '절두산 순교성지 - 잘린 머리의 산, 한강의 신앙 언덕', '서울 마포 절두산 순교성지, 병인박해 순교지이자 28위 성인 유해 안치. 한강 노을과 어우러지는 촬영 명소, 서울 순례길 3코스.', NULL, '한강공원 자전거길, 합정역 일대', '마포 피정의 집, 합정동 비즈니스 호텔, 홍대 인근 게스트하우스'),
  ('해미순교성지', '순교성지', '대전', '충남', '충남 서산시 해미면 성지1로 13', '서산 해미읍성에서 서쪽으로 1km. 논밭 사이로 고요하게 자리한 이 땅 아래에는 이름조차 남기지 못한 천 명 넘는 순교자가 잠들어 있다. 1866년 병인박해가 시작되자 충청도 곳곳에서 붙잡힌 신자들이 해미읍성으로 끌려왔다. 옥에 갇히고, 고문당하고, 끝내 이곳 해미천변에서 생매장당했다. 죽음을 앞둔 이들이 부르짖은 예수 마리아는 마을 사람들의 귀에 여수 머리로 들렸고, 이곳은 여숫골이라 불리게 되었다. 2014년 프란치스코 교황이 이곳을 찾아 무명 순교자들을 기렸다. 700석 규모의 대성당, 순교자 유해를 모신 묘역, 처형이 이뤄진 진둠벙까지 — 성지를 한 바퀴 도는 것만으로 조선 후기 박해의 참혹함과 믿음의 장엄함이 동시에 전해진다.', '병인박해(1866) 최대 규모 순교지. 이름이 밝혀진 순교자 179명 포함 무명 순교자 1,000명 이상 추정. 2014년 프란치스코 교황 방문지(아시아청년대회 폐막미사).', '해미순교성지 - 여숫골, 천 명의 이름 없는 믿음', '충남 서산 해미순교성지, 병인박해 최대 순교지이자 2014년 프란치스코 교황 방문지. 여숫골 생매장터와 해미읍성을 함께 둘러보는 순례 코스.', '치유', '해미읍성(사적 제116호, 도보 15분) — 순교자 머리채를 묶었던 회화나무, 옥터', NULL),
  ('솔뫼성지', '순례길', '대전', '충남', '충남 당진시 우강면 솔뫼로 132', '당진 우강면, 내포 평야 한가운데 소나무 숲이 우거진 낮은 동산. 솔뫼라는 이름 그대로다. 이 소나무 아래에서 1821년 한국 최초의 사제 김대건 안드레아가 태어났다. 증조부 김진후, 작은할아버지 김종한, 아버지 김제준까지 4대에 걸쳐 순교자를 배출한 집안이다. 열다섯 소년이었던 김대건은 이곳을 떠나 마카오로 건너갔고, 한국인 첫 사제가 되어 돌아왔으나 스물다섯의 나이에 새남터에서 순교했다. 복원된 생가 앞마당에는 2014년 이곳을 찾은 프란치스코 교황의 기도하는 모습을 형상화한 조각이 서 있다.', '한국 최초의 사제 김대건 안드레아 신부 탄생지. 4대에 걸친 순교자 배출 가문(증조부·작은할아버지·부친·당고모). 국가 사적 제529호, 연평균 방문객 40만 명 이상.', '솔뫼성지 - 한국 최초 사제 김대건 신부 탄생지', '충남 당진 솔뫼성지, 김대건 안드레아 신부가 태어난 소나무 숲. 4대 순교자 가문의 이야기와 국가 사적 제529호 순례지.', '새출발', '버그내순례길(13.3km)로 합덕성당·신리성지와 연결', NULL),
  ('여사울성지', '순례길', '대전', '충남', '충남 예산군 신암면 신종리', '내포의 사도 이존창 루도비코의 생가터. 이존창은 1784년 한국 최초의 세례자 이승훈에게 세례를 받은 뒤 내포 지방에 천주교를 전파한 인물이다. 1801년 신유박해 때 공주 감영에서 순교했다. 그의 전교 활동으로 내포 지방은 한국 천주교의 요람이 되었다.', '내포의 사도 이존창 루도비코 생가터. 내포 지방 천주교 전파의 출발점, 1801년 신유박해 순교.', '여사울성지 - 내포의 사도 이존창의 생가터', '충남 예산 여사울성지, 내포 지방에 천주교를 전파한 이존창 루도비코의 생가터.', '위로', NULL, NULL),
  ('갈매못 순교성지', '순교성지', '대전', '충남', '충남 보령시 오천면 오천해안로 610', '보령 오천 해안가, 서해 바다가 내려다보이는 언덕 위에 조개껍데기 모양의 지붕을 얹은 성당이 서 있다. 승리의 성모성당. 이 작고도 아름다운 성당 아래 모래사장에서 1866년 3월 30일, 다섯 명이 군문효수형을 받았다. 제5대 조선교구장 다블뤼 주교, 오매트르 신부, 위앵 신부, 회장 황석두 루카와 신학당의 장주기 요셉. 성당 문을 열면 제대 뒤 스테인드글라스가 시선을 사로잡는다. 미닫이로 된 이 유리문을 열면 그날 성인들이 마지막으로 바라보았을 서해가 펼쳐진다.', '1866년 병인박해, 다블뤼 주교 등 5위 모두 성인으로 시성. 한양에서 먼 이곳까지 끌려와 처형된 특수한 배경(고종비 간택 예정으로 서울 근처 처형 회피).', '갈매못 순교성지 - 다섯 성인의 마지막 기도', '충남 보령 갈매못 순교성지, 다블뤼 주교 등 5위 성인이 순교한 서해안 성지. 조개 지붕 승리의 성모성당과 십자가의 길 14처.', '평온', '서해안 드라이브 코스와 연계', NULL),
  ('성거산성지', '순례길', '대전', '충남', '충남 천안시 서북구 입장면 위례산길 394', '해발 500m 성거산 정상 부근, 1860~1920년대 7개 교우촌이 산재했던 곳. 병인박해 때 주변 6개 교우촌에서 23명이 순교했다. 소학골 교우촌 터에는 초가 3채가 복원되어 옛 교우촌 풍경을 재현하고 있다. 봄·가을이면 야생화와 단풍이 어우러지는 산간 성지로, 한 번 순례를 온 이들은 꼭 다시 오고 싶어 하는 곳이라 불린다.', '해발 500m 산간 교우촌 터, 7개 교우촌 중 6곳에서 23명 순교. 한국 두 번째 사제 최양업 신부 가문과 연관(백부가 서덕골 교우촌 거주).', '성거산성지 - 산 위의 교우촌, 야생화 순례길', '충남 천안 성거산성지, 해발 500m 산간에 자리한 7개 교우촌 터. 야생화와 단풍이 아름다운 산간 순례 성지.', '평온', NULL, NULL),
  ('황새바위 순교성지', '순교성지', '대전', '충남', '충남 공주시 왕릉로 118', '공주 시내에서 금강을 건너기 직전, 공산성을 마주한 언덕 위에 높이 13.8미터의 순교탑이 우뚝 서 있다. 1791년부터 약 100년간, 충청도 전역에서 체포된 천주교 신자들이 공주 감영으로 끌려와 이 언덕에서 처형당했다. 이름이 밝혀진 순교자만 248위. 그중 손자선 토마스 성인은 관장이 살을 물어뜯어 신앙을 증거하라고 명하자 주저 없이 제 살을 물어뜯었다. 순교탑 아래 돌무덤 경당에는 248위의 이름이 새겨져 있고, 광장의 12개 빛돌은 이름 없는 순교자들의 묘비이자 12사도의 상징이다.', '1791~1890년대 약 100년간 이어진 충남 최대 규모 순교지. 신원 확인된 순교자만 248위, 충청·전라·경기 등 전국 각지 출신 포함.', '황새바위 순교성지 - 100년, 248개의 이름', '충남 공주 황새바위 순교성지, 100년간 248위가 순교한 충남 최대 규모 순교지. 공산성과 함께 도는 반나절 코스.', '치유', '공산성(유네스코 세계문화유산)과 도보 연계', NULL),
  ('공세리성지성당', '주교좌성당', '대전', '충남', '충남 아산시 인주면 공세리성당길 10', '아산만 방조제를 건너 야트막한 언덕을 오르면 350년 된 고목 세 그루가 먼저 반긴다. 그 너머로 붉은 벽돌의 고딕 첨탑이 솟아 있다. 조선시대 40개 마을의 조세를 보관하던 창고 터에 세워진 이 성당은 1922년 완공된 근대 건축의 보석이다. 봄이면 진입로 벚나무에 구름이 내려앉고, 언덕 위 꽃잔디가 분홍빛 바다를 이룬다. 6·25전쟁 때 8대 주임 뷜토 오 신부는 양떼를 두고 목자가 떠날 수 없다며 피난을 마다했다.', '2005년 한국관광공사 선정 대한민국에서 가장 아름다운 성당. 1922년 완공 고딕 성당, 병인박해 순교자 3인 안장, 6·25전쟁 때 뷜토 오 신부 납북·순교.', '공세리성지성당 - 대한민국에서 가장 아름다운 성당', '충남 아산 공세리성지성당, 2005년 한국관광공사 선정 가장 아름다운 성당. 1922년 고딕 건축과 봄철 벚꽃길, 성지박물관.', '감사', '아산만 방조제 드라이브 코스', NULL),
  ('신리성지', '순례길', '대전', '충남', '충남 당진시 합덕읍 신리', '제5대 조선교구장 다블뤼 주교가 은거하며 사목 활동을 하던 곳. 초가집으로 복원된 주교관이 남아 있으며, 병인박해 때 다블뤼 주교가 이곳에서 체포되어 보령 갈매못에서 순교했다. 조선의 카타콤바라 불리는 이 성지는 2024년 대대적 리뉴얼을 거쳐 담장을 낮추고 힐링 공간으로 거듭났다.', '다블뤼 주교 은거지이자 체포지, 조선의 카타콤바로 불림. 버그내순례길 출발점, 매년 5월·10월 대전교구 주최 도보성지순례 개최.', '신리성지 - 조선의 카타콤바', '충남 당진 신리성지, 다블뤼 주교의 은거지이자 체포지. 초가 주교관과 한옥 수녀원, 순례객을 위한 힐링 공간.', '평온', '버그내순례길(13.3km)로 합덕성당·솔뫼성지 연결', NULL),
  ('천주교 대흥동 교회 (대흥동 성당)', '주교좌성당', '대전', '충남', '대전광역시 중구 대흥동', '두 손을 모아 하늘을 향한 형상. 1962년 완공 당시 대전 시내에서 가장 높은 건물은 성당이었다. 지금도 49.8m 종탑은 원도심 한복판에 서서, 도시가 그 주위로 자라나는 동안 자기 자리를 지켜왔다. 정면 캐노피에 가려 쉽게 지나치지만, 고개를 들면 열두 사도 부조상이 성당을 지키고 있고, 그 위 스테인드글라스는 오스트리아에서 정통 기법을 배운 이남규 화백의 작품이다. 정문을 지나 소나무 아래에는 아들을 안은 어머니, 피에타상이 조용히 서 있다.', '1962년 완공, 국가등록문화재 제43호(2014년 등록). 대전 원도심을 대표하는 근대 건축 유산, 완공 당시 대전 시내 최고층 건물.', '대흥동성당 - 대전 원도심의 근대 건축 유산', '대전 중구 대흥동성당(천주교 대흥동 교회), 1962년 완공 국가등록문화재 제43호. 12사도 부조상과 이남규 화백의 스테인드글라스.', '감사', NULL, NULL),
  ('서소문 밖 네거리 순교성지', '순교성지', '서울', '서울', '서울시 중구 칠패로 5 (중림동)', '서울역에서 도보로 10분, 충정로역에서 5분. 수많은 직장인이 오가는 서울 도심 한복판에 조용하고도 깊은 이야기를 품은 공간이 있다. 서소문 밖 네거리. 조선 시대 이곳은 공식 처형장이었고, 1801년 신유박해부터 1866년 병인박해에 이르기까지 44위의 성인과 27위의 복자, 수많은 무명 순교자가 이곳에서 신앙을 증거했다. 2019년 개관한 서소문성지 역사박물관은 지하로 내려가는 구조 자체가 하나의 순례 여정이다. 전시실을 지나 하늘광장에 도달하면, 지하에서 올려다보는 하늘이 마치 순교자들이 마지막으로 바라보았을 그 하늘처럼 아득히 높다.', '1801년 신유박해~1866년 병인박해까지 44위 성인·27위 복자가 순교한 단일 장소 기준 한국 천주교 최대 순교지. 2018년 교황청 공인 서울 순례길 핵심 구간.', '서소문성지 역사박물관 - 도심 한복판 최대 순교지', '서울 중구 서소문성지, 44위 성인·27위 복자가 순교한 한국 최대 단일 순교지. 2019년 개관한 지하 역사박물관과 하늘광장.', '치유', '중림창고(카페골목, 도보 3분), 약현성당(도보 5분)', NULL),
  ('새남터순교성지', '순교성지', '서울', '서울', '서울시 용산구 이촌로 80-1', '한양성 밖 남쪽 한강변, 노들이라 불리던 이 모래 벌판은 조선 시대 군사 연무장이자 중죄인 처형장이었다. 1801년부터 1866년까지 한국 최초의 사제 김대건 안드레아를 비롯해 11명의 성직자가 이곳에서 순교했다. 평신도의 순교지인 서소문과 대비하여 사제들의 순교지로 불린다. 현재의 새남터순교성지 성당은 1967년 건립된 순교기념 성당으로, 성당 입구의 삶은 순교입니다. 순교는 사랑입니다라는 글귀가 방문자의 마음을 먼저 울린다.', '1801~1866년, 한국 최초 사제 김대건 안드레아 포함 11명의 성직자가 순교한 사제들의 순교지.', '새남터순교성지 - 사제들의 순교지, 한강변의 기도', '서울 용산 새남터순교성지, 김대건 안드레아 신부 등 11명의 성직자가 순교한 한강변 성지.', '치유', NULL, NULL),
  ('당고개순교성지', '순교성지', '서울', '서울', '서울시 용산구 원효로 2가', '1839년 기해박해가 거의 끝나가던 12월, 설날 대목장을 앞둔 서소문 상인들의 요청으로 처형 장소가 이곳 당고개로 옮겨졌다. 10명의 순교자 중 9명이 성인으로 시성된 의미 깊은 곳이다.', '1839년 기해박해 마지막 순교지. 10명 중 9명이 성인으로 시성.', '당고개순교성지 - 기해박해의 마지막 피', '서울 용산 당고개순교성지, 1839년 기해박해 마지막 순교지. 앵베르 주교 등 9위 성인의 순교지.', '위로', NULL, NULL),
  ('명동대성당', '주교좌성당', '서울', '서울', '서울시 중구 명동길 74', '1898년 완공된 한국 최초의 고딕 양식 벽돌 성당. 높이 47m의 종탑은 서울 도심의 상징적 랜드마크이자, 1987년 민주화 운동의 성지이기도 하다. 지하에는 한국 천주교 초대 주교의 유해가 안장된 지하 성당이 있다. 명동 쇼핑거리 한복판에서 골목 하나를 올라가면 갑자기 펼쳐지는 고요한 공간. 회색 벽돌 하나하나에 깃든 120년의 시간을 느끼며 성당 내부에 들어서면, 스테인드글라스를 통해 쏟아지는 빛이 경건함을 선사한다.', '1898년 준공, 한국 최초 고딕 양식 벽돌 성당. 사적 제258호. 1987년 민주화 운동의 성지이기도 함.', '명동대성당 - 한국 천주교의 심장, 120년 고딕의 위엄', '서울 중구 명동대성당, 1898년 완공 사적 제258호. 한국 최초 고딕 벽돌 성당이자 서울 도심의 랜드마크.', '감사', NULL, NULL),
  ('약현성당 (중림동성당)', '주교좌성당', '서울', '서울', '서울시 중구 청파로 447-1 (중림동)', '1892년 준공된 약현성당은 명동성당보다 6년 앞서 세워진 한국 최초의 서양식 벽돌 성당이다. 서소문 순교지가 한눈에 내려다보이는 언덕 위에 자리해, 순교자들에 대한 추모의 의미를 더한다. 붉은 벽돌의 로마네스크 양식이 소박하면서도 아름답다.', '1892년 준공, 명동성당보다 6년 앞선 한국 최초의 서양식 벽돌 성당. 사적 제252호.', '약현성당 - 서소문을 내려보는 최초의 서양식 성당', '서울 중구 약현성당(중림동성당), 1892년 준공 사적 제252호. 명동성당보다 앞선 한국 최초 서양식 벽돌 성당.', '평온', NULL, NULL),
  ('오륜대 한국 순교자 박물관', '역사사적지', '부산', '경남', '부산광역시 금정구 오륜대로 106', '한국 천주교 순교자들의 유물과 역사를 종합적으로 전시하는 박물관. 1983년 한국 천주교 200주년을 기념해 건립되었으며, 순교자들이 남긴 유물과 박해 시대의 문서, 초기 교회 자료를 소장하고 있다. 부산·울산 지역 성지순례의 출발점이 되는 곳이다.', '1983년 한국 천주교 200주년 기념사업으로 건립된 순교자 유물 박물관. 부산교구 대표 순례지.', '오륜대 한국 순교자 박물관 - 부산 순례의 시작점', '부산 금정구 오륜대 한국 순교자 박물관, 1983년 건립된 순교자 유물 전시관. 부산·울산 성지순례 대표 출발지.', '치유', NULL, NULL),
  ('울산 죽림굴(대왕암) 순교지', '순교성지', '부산', '경남', '울산광역시 동구', '병인박해 때 관헌의 눈을 피해 해안 동굴에 숨어 살던 신자들이 끝내 발각되어 순교한 곳. 대왕암 인근 죽림굴은 오늘날에도 당시 신자들의 고단했던 은신 생활을 짐작하게 한다.', '병인박해 때 해안 동굴에 숨어 신앙을 지키다 순교한 신자들의 은신처.', NULL, NULL, NULL, NULL, NULL),
  ('기장 성지', '순례길', '부산', '경남', '부산광역시 기장군', '박해 시대 신자들이 관의 눈을 피해 모여 살던 교우촌 터. 구체적인 순교 기록은 추가 확인이 필요하지만, 부산 지역 천주교 박해사의 흔적을 보여주는 장소다.', '박해시대 교우촌 터, 신자들의 은신처.', NULL, NULL, NULL, NULL, NULL),
  ('울산 장대 순교지', '순교성지', '부산', '경남', '울산광역시', '병인박해가 한창이던 시기, 울산 장대에서 신앙을 지키던 신자 세 명이 처형되었다. 이들은 2014년 프란치스코 교황 방한 시 시복되며 성인 반열에 한 걸음 다가섰다.', '병인박해(1866) 때 울산 장대에서 3위가 순교, 2014년 시복되었다.', NULL, NULL, NULL, NULL, NULL),
  ('통영 김기량 순교지(통제영 옥터)', '순교성지', '마산', '경남', '경남 통영시 문화동 세병로 일대 (통제영 옥터)', '통영 세병관 앞 번화한 세병로 거리, 지금은 사람들의 발길이 오가는 이 자리에 한때 통제영의 옥터가 있었다. 제주 함덕리 출신 상인 김기량 펠릭스 베드로는 무역을 위해 통영을 오가다 천주교 신자임이 드러나 체포되었고, 혹독한 문초 끝에도 신앙을 버리지 않아 1867년 교수형으로 순교했다. 삼도수군통제영의 중심, 조선 해군의 심장부였던 이 거리는 아홉 명의 순교자를 낳은 신앙의 자리이기도 하다. 번잡한 거리를 걷다 잠시 멈춰 서서, 이름 없이 스러진 이들의 신앙을 되새겨본다.', '제주 출신 상인 복자 김기량 펠릭스 베드로(1816~1867)가 통영에서 체포되어 통제영 옥에서 순교한 자리. 통제영에서 모두 9명의 천주교 신자가 순교했으며, 2014년 시복되었다.', '통영 김기량 순교지 - 통제영 옥터의 기억', '경남 통영 세병관 앞 통제영 옥터, 제주 상인 복자 김기량이 순교한 자리. 삼도수군통제영의 중심에 새겨진 아홉 순교자의 신앙.', '치유', NULL, NULL),
  ('거제 윤봉문 요셉 순교성지', '순교성지', '마산', '경남', '경남 거제시 일운면 지세포3길 69-22', '거제 바다가 내려다보이는 지세포, 편백나무와 맹종죽 숲길을 따라 걷다 보면 순교자의 넋을 기리는 추모탑이 나타난다. 1888년 신앙을 전하다 체포되어 진주로 압송, 끝내 배교하지 않고 순교한 복자 윤봉문 요셉의 자리다. 협소한 산중 묘소였던 이곳은 2013년 유해를 이장하며 십자가의 길과 로사리오 기도길, 전망대를 갖춘 순례지로 새롭게 조성되었다. 숲 향기를 맡으며 천천히 오르는 산책로 끝에서, 거제의 사도라 불린 한 평신도의 삶을 만난다.', '1888년 신앙을 지키다 체포되어 진주로 압송, 순교한 복자 윤봉문 요셉(1852~1888)을 기리는 성지. 2013년 유해를 이장하며 십자가의 길, 로사리오 기도길, 전망대를 갖춘 순례지로 조성되었고 2014년 시복되었다.', '거제 윤봉문 요셉 순교성지 - 지세포 숲길의 기도', '경남 거제시 지세포, 편백숲과 맹종죽림 사이 십자가의 길을 걸으며 복자 윤봉문 요셉의 순교를 기리는 자연 친화적 순례지.', '평온', NULL, NULL),
  ('정찬문 안토니오 순교성지', '순교성지', '마산', '경남', '경남 진주시 사봉면 무촌리 (허유고개)', '진주 사봉면, 예로부터 신자들이 넘나들던 허유고개를 오르면 소박한 묘 하나가 나그네를 맞는다. 1866년 병인박해 당시 남강 백사장에서 참수된 복자 정찬문 안토니오, 목 없는 시신만 수습되어 고향 땅에 몰래 묻힌 자리다. 사봉주유소를 지나 산길을 600여 미터 오르는 짧은 걸음이지만, 걸음마다 신앙을 지키기 위해 목숨을 내놓은 한 청년의 결단이 스며 있다. 2014년 시복으로 다시 세상에 알려진 이곳은, 화려하지 않아도 깊은 울림을 주는 조용한 기도처다.', '병인박해(1866) 때 남강 백사장에서 순교한 복자 정찬문 안토니오(1822~1867)의 묘소. 목 없는 시신만 수습되어 무두묘로 불리며, 2014년 프란치스코 교황 방한 시 시복되었다.', '정찬문 안토니오 순교성지 - 허유고개의 무두묘', '경남 진주시 사봉면, 병인박해 순교자 복자 정찬문 안토니오의 묘소. 목 없는 시신이 묻힌 무두묘와 신자들이 넘던 허유고개를 만나는 조용한 순례지.', '위로', NULL, NULL),
  ('진주 문산성당', '주교좌성당', '마산', '경남', '경남 진주시 문산읍 소문길 67번길 9-4', '진주 문산읍, 한옥 기와지붕과 고딕 첨탑이 나란히 마주 선 독특한 풍경이 발길을 멈추게 한다. 1905년 소촌공소로 출발해 서부 경남 최초의 본당으로 자리 잡은 문산성당은, 1923년 지어진 한옥 성당과 1937년 세워진 고딕 양식 성당을 함께 품고 있다. 동서양 건축이 한 마당에 공존하는 모습은 국내에서도 보기 드문 풍경으로, 2002년 국가등록문화재로 지정되었다. 오래된 종탑 아래 서면, 백여 년 전 이 땅에 뿌리내린 신앙 공동체의 시간이 고요히 되살아난다.', '1905년 소촌공소에서 출발해 1913년 서부 경남 최초의 본당으로 승격. 1923년 지어진 한옥 성당과 1937년 세워진 고딕 양식 성당이 나란히 남아있는 국가등록문화재 제35호.', '진주 문산성당 - 한옥과 고딕이 함께 선 성당', '경남 진주시 문산읍, 1905년 설립된 서부 경남 최초의 성당. 한옥 성당과 고딕 성당이 나란히 자리한 국가등록문화재.', '감사', NULL, NULL),
  ('왜관 성 베네딕도 수도원', '순례길', '대구', '경북', '경북 칠곡군 왜관읍 왜관수도원길 67', '낙동강 물줄기가 굽이도는 왜관, 나지막한 담장 너머로 유럽식 수도원 건물이 자리하고 있다. 원래 함경도 원산 덕원에 있던 이 수도원은 한국전쟁 중 북한을 탈출한 독일 베네딕도회 수사들이 1952년 칠곡 땅에 다시 세운 것이다. 이후 한국 베네딕도회의 중심으로 자리 잡아 기도와 노동을 함께하는 수도 공동체의 전통을 이어가고 있으며, 분도출판사를 통해 다양한 신앙 서적을 펴내고 있다. 조용한 회랑을 거닐다 보면, 분단의 아픔을 딛고 지켜낸 신앙 공동체의 시간이 느껴진다.', '북한 덕원자치수도원구의 후계 수도원으로, 한국전쟁 중 탈출한 독일 베네딕도회 수사들이 1952년 칠곡에 재건한 한국 베네딕도회의 중심 수도원.', '왜관 성 베네딕도 수도원 - 낙동강변의 독일 수도원', '경북 칠곡군 왜관읍, 북한 덕원수도원의 후계로 1952년 재건된 한국 베네딕도회의 중심 수도원. 분도출판사를 운영하는 기도와 노동의 공동체.', '평온', NULL, NULL),
  ('계산 주교좌대성당', '주교좌성당', '대구', '경북', '대구광역시 중구 서성로 10 (계산동)', '대구 근대골목 한복판, 붉은 벽돌 첨탑이 하늘을 찌르듯 솟아 있다. 1899년 목조 성당으로 출발해 1902년 로베르 신부의 설계로 완공된 계산성당은 대구 최초의 서양식 건축물이자 경상도 천주교의 상징이다. 1950년 박정희·육영수의 결혼식이, 1951년에는 훗날 추기경이 될 김수환 신부의 서품식이 이곳에서 거행되었다. 계산성당에서 관덕정 순교기념관, 성 유스티노관, 성모당까지 이어지는 약 1.5km의 도보 순례길은 대구 근대역사 골목 투어와 함께 걷기 좋은 반나절 코스다.', '1902년 완공된 대구 최초의 서양식 고딕 벽돌 성당(사적 제290호). 박정희·육영수 결혼식(1950년), 김수환 추기경 사제 서품식(1951년)이 거행된 장소로 경상도 천주교의 상징이다.', '계산 주교좌대성당 - 대구 근대골목의 첫 서양식 성당', '대구광역시 중구, 1902년 완공된 대구 최초의 서양식 고딕 성당(사적 제290호). 김수환 추기경 서품지이자 대구 근대골목 투어의 핵심 명소.', '감사', NULL, NULL),
  ('경상감영 옥터 순교지', '순교성지', '대구', '경북', '대구광역시 중구 대안동 31-11 (경상감영공원·대안성당 일대)', '대구 도심 한복판, 지금은 시민들의 쉼터가 된 경상감영공원 자리에 한때 혹독한 감옥이 있었다. 박해 시대 경상도 각지에서 체포된 천주교 신자들이 이곳 옥에 갇혀 문초를 당했고, 최봉한 프란치스코와 김시우 알렉시오를 비롯한 7명이 끝내 옥사했다. 형이 확정된 이들은 인근 관덕정 형장으로 끌려가 처형당했으니, 경상감영과 관덕정은 한 이야기의 두 장면인 셈이다. 오늘날 대안성당이 자리한 이 일대를 걸으며, 도심 속에 스며 있는 순교의 기억을 찾아본다.', '박해시대 경상도 각지에서 체포된 천주교 신자들이 혹독한 문초를 받고 갇혀 있던 옥터. 최봉한 프란치스코, 김시우 알렉시오, 박경화 바오로, 안군심 리카르도 등 7위가 이곳에서 옥사했다.', '경상감영 옥터 순교지 - 대구 도심 속 순교의 기억', '대구광역시 중구 대안동, 박해시대 경상도 신자들이 갇혀 옥사한 감영 옥터. 관덕정 순교성지와 함께 둘러보는 대구 도심 순례지.', '치유', NULL, NULL),
  ('한티 순교성지', '순교성지', '대구', '경북', '경북 칠곡군 동명면 한티로 1', '팔공산 깊은 산자락, 한티재를 넘어야 닿는 외진 계곡에 순교자들의 이야기가 잠들어 있다. 병인박해가 몰아치던 1866년, 관의 눈을 피해 이 산골로 숨어든 신자들은 옹기를 구우며 숨죽여 신앙을 이어갔지만 끝내 발각되어 11명이 순교했다. 오늘날 한티성지에는 십자가의 길과 피정의 집, 성당이 들어서 대구대교구를 대표하는 피정 장소로 자리 잡았다. 산으로 둘러싸인 고요함 속에서, 박해를 피해 살아간 이들의 절박했던 신앙을 마주하게 된다.', '병인박해(1866) 때 11명의 신자가 순교한 산골 교우촌 터. 박해를 피해 옹기를 구우며 신앙을 지킨 비밀 신앙 공동체의 흔적이 남아 있다.', '한티 순교성지 - 팔공산 산골의 옹기 교우촌', '경북 칠곡군 동명면, 병인박해 때 11명이 순교한 산골 교우촌 터. 십자가의 길과 피정의 집을 갖춘 대구대교구 대표 피정 성지.', '평온', NULL, NULL),
  ('관덕정 순교성지', '순교성지', '대구', '경북', '대구광역시 중구 관덕정길 11 (남산2동)', '대구역에서 걸어서 15분, 회색 빌딩숲 사이로 기와지붕 누각이 불쑥 솟아 있다. 조선시대 무과 시험장이자 처형장이었던 관덕정에서는 1815년부터 1868년까지 영남 천주교인 25명이 목숨을 바쳤다. 문경·상주에서 전교회장으로 활동하다 체포된 이윤일 요한은 1867년 이곳에서 군문효수형으로 순교, 1984년 한국 103위 순교성인 중 한 명으로 시성되었다. 지하 성당의 유해 봉안 제대, 1~3층 전시, 옥상 누각의 단청 아래 알파·오메가 문양까지 — 한국 전통과 신앙이 어우러진 독특한 순례지다.', '1815년 을해박해부터 1868년까지 영남 지역 천주교인 25명이 처형되고 옥사자를 합하면 50명 이상이 순교한 조선시대 형장. 한국 103위 순교성인 중 영남 유일의 성인 이윤일 요한이 1867년 이곳에서 순교, 1986년 유해를 미리내에서 이장해 봉안했다.', '관덕정 순교성지 - 대구 도심 속 영남의 순교터', '대구광역시 중구, 영남 유일 성인 이윤일 요한이 순교한 조선시대 형장. 지하 성당과 순교자 유해, 옥상 누각 전망대를 갖춘 대구 도심 속 성지.', '치유', NULL, NULL),
  ('가실성당', '주교좌성당', '대구', '경북', '경북 칠곡군 왜관읍', '칠곡 왜관 들녘 한가운데, 붉은 벽돌 고딕 성당이 낮은 지붕들 사이로 홀로 우뚝하다. 1923년 독일 베네딕도회 선교사들의 손으로 지어진 가실성당은 경북 내륙에서 보기 드문 서양식 근대 건축으로, 경북 유형문화재로 지정되어 있다. 인근 왜관 수도원과 함께 독일 베네딕도회가 한국 땅에 뿌리내린 흔적을 고스란히 간직한 곳이다. 들판을 배경으로 한 고딕 첨탑의 실루엣은 계절마다 다른 빛을 담아, 사진을 찾는 이들의 발길이 끊이지 않는다.', '1923년 완공된 고딕 양식 성당(경북 유형문화재). 독일 베네딕도회 선교사들이 건축했으며 왜관 수도원 인근에 위치한 경북 내륙의 대표적 근대 건축 성당이다.', '가실성당 - 칠곡 들녘의 고딕 첨탑', '경북 칠곡군 왜관읍, 1923년 독일 베네딕도회가 지은 고딕 양식 성당(경북 유형문화재). 왜관 수도원과 함께 둘러보기 좋은 근대 건축 명소.', '감사', NULL, NULL),
  ('목포 산정동 순교자기념성당', '순교성지', '광주', '전남', '전남 목포시 노송길 35', '목포 개항과 함께 태어난 성당, 노송길 언덕 위에서 목포항을 내려다본다. 1897년 파리외방전교회 주교의 전라도 순방으로 설립이 결정된 산정동성당은 광주대교구의 첫 본당이자 전남 천주교의 뿌리다. 1913년 완공된 성당은 이후 여러 차례 보수를 거쳐 오늘의 모습을 완성했고, 2021년에는 로마 교황청으로부터 국내 최초로 준대성전 지위를 부여받았다. 붉은 벽돌과 우뚝한 첨탑이 목포 근대 개항장 거리와 어우러진 풍경은, 신앙과 항구 도시의 역사가 함께 걸어온 120여 년의 시간을 보여준다.', '1897년 목포 개항과 함께 설립된 광주대교구 첫 본당. 2021년 로마 교황청으로부터 국내 최초로 준대성전(Minor Basilica) 지위를 받았다.', '목포 산정동 순교자기념성당 - 개항과 함께한 전남 첫 본당', '전남 목포시, 1897년 목포 개항과 함께 설립된 광주대교구 첫 본당. 2021년 국내 최초 준대성전으로 지정된 근대 개항장의 랜드마크.', '감사', NULL, NULL),
  ('5·18 기념성당(남동성당)', '주교좌성당', '광주', '전남', '광주광역시 동구 제봉로 67', '광주 도심, 낮은 담장 너머 소박한 벽돌 성당 외벽에는 아직도 총탄 자국이 남아 있다. 1980년 5월, 계엄군의 폭력이 광주를 뒤덮던 그날 밤 김성용 신부를 비롯한 12명의 민주인사가 이 성당에 모여 수습대책위원회를 꾸렸다. 윤공희 대주교는 정부의 담화를 공개적으로 반박하며 계엄군의 만행을 규탄했고, 성당은 두려움에 떨던 시민들의 피난처가 되었다. 2005년 5·18 25주년을 맞아 남동성당은 5·18 기념성당으로 선포되었고, 이후 5월 18일은 광주대교구의 교구기념일로 제정되었다. 벽에 새겨진 총탄 자국을 마주하는 순간, 신앙과 항쟁이 함께했던 그해 오월이 되살아난다.', '1980년 5·18 민주화운동 당시 김성용 신부 등 12명의 민주인사가 수습대책위원회를 열었던 역사적 장소. 윤공희 대주교가 계엄군의 폭력을 공개 비판하며 시민들의 피난처 역할을 했고, 2005년 5·18 25주년에 5·18 기념성당으로 선포되어 매년 5월 18일이 광주대교구 기념일로 제정되었다.', '5·18 기념성당(남동성당) - 총탄 자국이 남은 오월의 성당', '광주광역시 동구, 1980년 5·18 민주화운동 당시 시민들의 피난처였던 성당. 총탄 자국이 남아있으며 매년 5월 18일 광주대교구 기념일의 중심지.', '치유', NULL, NULL),
  ('영광 순교자 기념성당', '순교성지', '광주', '전남', '전남 영광군 영광읍', '전남 영광 읍내, 순교자 기념문을 지나면 소박한 성당 마당에 순교자상이 서 있다. 조선 천주교회 초기, 유항검의 복음 전파로 영광에도 신앙 공동체가 뿌리내렸지만 1801년 신유박해가 몰아치며 이화백과 복산리 오씨가 이곳에서 처형되었다. 함께 신앙을 나누던 이들은 전주에서 순교하거나 황해도로 귀양을 떠나야 했다. 1937년 세워졌다 폐쇄된 성당은 1965년 다시 문을 열었고, 2010년 순교자 기념성당으로 지정되며 기념문과 순교자상, 기념 전시관이 차례로 세워졌다. 조용한 읍내 성당에서, 이백여 년 전 이 땅에 뿌리내렸던 첫 신앙의 흔적을 마주한다.', '1801년 신유박해 때 영광 출신 이화백과 복산리 오씨가 순교한 것을 기려 2010년 순교자 기념성당으로 지정. 유항검의 복음 전파로 형성된 초기 신앙 공동체의 흔적이다.', '영광 순교자 기념성당 - 신유박해의 첫 신앙 흔적', '전남 영광군 영광읍, 신유박해(1801) 순교자 이화백을 기리는 성당. 순교자 기념문과 기념 전시관을 갖춘 조용한 읍내 성지.', '위로', NULL, NULL),
  ('곡성 옥터 성지(곡성성당)', '주교좌성당', '광주', '전남', '전남 곡성군 곡성읍', '전남 곡성 읍내 한켠, 성당 뒤편에 조용히 자리한 옥터전시실이 130여 년 전의 아픔을 증언한다. 을해박해(1815)를 피해 경상도·강원도에서 곡성 산골로 숨어든 신자들은 옹기를 구우며 신분을 감추고 신앙을 이어갔다. 그러나 1827년 정해박해가 시작되며 다시 붙잡혔고, 곡성현 객사를 개조한 임시 감옥에 갇혀 혹독한 고문을 받았다. 대부분 배교했지만 이 막달레나와 이성지 요한 등은 끝까지 신앙을 지키다 순교했다. 130년이 지난 1957년, 광주대교구는 이 자리에 곡성본당을 세워 선조들의 신앙을 기렸다. 오늘날 성당 옥사와 십자가의 길, 성모동산이 그날의 기억을 잇는다.', '을해박해(1815)를 피해 곡성 오곡면으로 피신한 신자들이 옹기를 구우며 신앙을 지키다, 1827년 정해박해로 다시 체포되어 곡성현 객사(임시 감옥)에서 고문받고 순교한 자리. 1958년 광주대교구가 이 순교 현장에 곡성본당을 세웠다.', '곡성 옥터 성지 - 정해박해의 진원지, 곡성성당', '전남 곡성군 곡성읍, 정해박해(1827) 때 신자들이 갇혀 순교한 옥터. 곡성성당 옥사전시실에서 옹기 교우촌의 아픈 역사를 만난다.', '위로', NULL, NULL),
  ('나주 순교자 기념성당', '순교성지', '광주', '전남', '전남 나주시 (나주성당)', '나주 읍내, 성당 마당 한켠에 130여 년 전의 흔적을 담은 받침돌이 여러 개 놓여 있다. 예전 나주 진영의 군사훈련장이자 형장이었던 무학당의 흔적이다. 1872년 병인박해가 저물어가던 시기, 강영원 바오로와 유치성 안드레아는 이곳에서 얼굴에 적신 종이를 여러 겹 붙이는 백지사형으로 순교했다. 이춘화 베드로, 유문보 바오로와 함께 이들 네 순교자를 기려 세워진 나주성당은 광주대교구 내 유일한 순교터를 품고 있다. 2001년 나주초등학교에 남아있던 받침돌을 성당으로 이전해 세운 기념 구조물 앞에서, 이름이 남은 네 순교자의 신앙을 되새겨본다.', '병인박해 말기인 1872년 나주 무학당(군사훈련장이자 형장)에서 강영원 바오로, 유치성 안드레아 등이 백지사형으로 순교. 광주대교구 내 유일한 순교터로, 무학당 초석 일부가 2001년 성당 경내로 이전되어 기념 구조물로 보존되어 있다.', '나주 순교자 기념성당 - 무학당 형장의 네 순교자', '전남 나주시, 1872년 무학당 형장에서 순교한 강영원·유치성 등 네 순교자를 기리는 성당. 광주대교구 내 유일한 순교터.', '치유', NULL, NULL),
  ('황사평 성지', '순례길', '제주', '제주', '제주특별자치도 제주시 기와 5길 117-22', '제주 시내를 벗어난 자리, 넓은 들판 사이로 십자가와 비석들이 조용히 늘어서 있다. 1901년 신축교안(이재수의 난)으로 수백 명의 천주교 신자가 희생된 뒤, 1903년 프랑스와의 합의에 따라 이곳이 공동묘지로 마련되었다. 이후 별도봉 아래에 묻혀 있던 무연고 순교자들의 유해도 이곳으로 이장되었고, 제주 선교 100주년을 맞아 지금의 공원묘지로 새롭게 단장되었다. 제주 첫 순교자 김기량 베드로의 현양비, 초대 교구장의 묘를 비롯해 외국 선교사들의 공덕비가 함께 자리한다. 1977년부터 해마다 열리는 순교자 현양대회를 통해, 이곳은 제주 천주교 신앙의 뿌리를 되새기는 자리로 이어지고 있다.', '1901년 신축교안(이재수의 난) 당시 희생된 수백 명의 천주교 신자를 위해 1903년 프랑스와의 합의로 조성된 공동묘지. 제주 첫 순교자 김기량 베드로와 초대 교구장의 묘가 있으며, 1977년부터 매년 순교자 현양대회가 열린다.', '황사평 성지 - 신축교안 순교자들의 안식처', '제주특별자치도 제주시, 1901년 신축교안 희생자들을 위한 공동묘지. 제주 첫 순교자 김기량의 현양비와 초대 교구장의 묘가 있는 제주교구 순교자 현양의 중심지.', '치유', NULL, NULL),
  ('제주 관덕정', '순례길', '제주', '제주', '제주특별자치도 제주시 관덕로 19', '제주 원도심 한복판, 우뚝한 누각 하나가 오백 년이 넘는 세월을 지키고 있다. 1448년 군사 훈련을 위해 지어진 관덕정은 제주에서 가장 오래된 건물이다. 1901년, 무거운 세금과 천주교회에 대한 반감이 쌓여가던 신축교안 당시, 민군을 이끌던 이재수가 이 광장에 모여 제주성으로 향했고, 이 과정에서 수백 명의 사상자가 나왔다. 사건이 수습된 뒤에는 관련자들이 이곳에서 처형되기도 했다. 오늘날 관광객으로 붐비는 관덕정 광장을 거니며, 신앙과 지역 공동체가 맞서서 싸우던 백여 년 전의 아픈 역사를 떠올려본다.', '1448년 군사 훈련을 위해 지어진 제주 최고(最古) 건물. 1901년 신축교안(이재수의 난) 당시 민군이 이 광장에 모였고, 충돌로 수백 명의 사상자가 발생한 사건 현장이다.', '제주 관덕정 - 신축교안의 현장', '제주특별자치도 제주시, 1901년 신축교안(이재수의 난)의 중심 무대였던 제주 최고(最古)의 건물. 신앙과 지역사회가 충돌했던 근대사의 현장.', '치유', NULL, NULL),
  ('용수성지 (성 김대건 신부 제주 표착 기념관)', '역사사적지', '제주', '제주', '제주특별자치도 제주시 한경면 용수리', '제주 서쪽 끝 용수리 포구, 파도가 밀려오는 해안에 배 한 척이 놓여 있다. 1845년 한국인 최초로 사제품을 받은 김대건 안드레아 신부가 페레올 주교, 다블뤼 신부와 함께 라파엘호를 타고 귀국하던 중, 거센 풍랑에 떠밀려 이곳 용수리 해안에 닿았다. 일행은 고국 땅에서의 첫 미사를 이곳에서 올린 뒤 배를 수리해 다시 길을 떠났다. 1999년 제주교구는 이 자리를 성지로 선포하고 기념성당과 기념관을 지었으며, 고증을 거쳐 복원한 라파엘호도 함께 전시하고 있다. 다음 해 새남터에서 순교하게 될 사제가 고국 땅을 처음 밟은 그 순간을, 파도 소리와 함께 마주한다.', '1845년 중국 상해에서 사제품을 받은 한국 최초의 사제 김대건 안드레아 신부가 귀국길에 폭풍을 만나 표착한 해안. 1999년 성지로 선포되어 기념성당과 기념관, 복원된 라파엘호가 전시되어 있다.', '용수성지 - 김대건 신부의 제주 표착지', '제주특별자치도 제주시 한경면, 김대건 신부가 귀국길에 표착해 첫 미사를 올린 해안. 기념성당과 복원된 라파엘호를 만나는 성지.', '새출발', NULL, NULL),
  ('대정성지 (정난주 마리아 묘)', '순례길', '제주', '제주', '제주특별자치도 서귀포시 대정읍 동일리', '서귀포 대정, 낮은 봉분 하나가 자리잡은 묘역에 파란만장한 삶이 잠들어 있다. 정약용의 조카이자 황사영의 아내였던 정난주 마리아는 1801년 남편의 백서 사건으로 관노 신분이 되어 대정현으로 귀양을 왔다. 어린 아들을 배 모는 사람에게 맡기고 추자도에 남겨둔 채 홀로 제주 땅을 밟은 그는, 신앙의 불모지에서도 학식과 믿음으로 주위의 존경을 받으며 37년을 살다 세상을 떠났다. 피를 흘리며 순교하지는 않았지만 유배지에서 끝까지 신앙을 지킨 그의 삶을 기려, 제주교구는 그를 백색 순교자로 공경하며 1994년 이곳을 대정성지로 조성했다. 조용한 묘역 앞에서, 낯선 섬에서 홀로 신앙을 지켜낸 한 여인의 생을 되새겨본다.', '정약용의 조카이자 황사영의 부인이었던 정난주 마리아(1773~1838)가 황사영 백서 사건으로 관노가 되어 유배 온 뒤 37년간 신앙을 지키며 살다 생을 마친 묘소. 피를 흘리지 않고 신앙을 지킨 삶으로 백색 순교자로 공경받는다.', '대정성지 - 백색 순교자 정난주 마리아의 묘', '제주특별자치도 서귀포시 대정읍, 유배지에서 37년간 신앙을 지킨 정난주 마리아의 묘소. 피 흘리지 않은 순교, 백색 순교자를 기리는 성지.', '위로', NULL, NULL),
  ('청주읍성 순교성지(서운동성당)', '순교성지', '청주', '충북', '충북 청주시 상당구 서운동', '청주 원도심, 예전 읍성의 흔적을 따라가면 순교자들의 이야기가 곳곳에 남아 있다. 신유박해(1801)부터 병인박해(1866)까지, 청주진영과 남문 밖 장터, 청주옥에서 신앙을 지키다 목숨을 잃은 이들이 있었다. 2014년 프란치스코 교황 방한 시 원시보 야고보, 배관겸 프란치스코, 오반지 바오로를 비롯한 5위가 복자품에 올랐다. 1932년 다른 성당에서 분리되어 청주 첫 본당이 된 서운동성당은 오반지 바오로의 유해를 모시고 있으며, 청주진영과 장대, 옥터까지 이어지는 순례길의 출발점이기도 하다. 도심 곳곳에 남은 순교의 자리를 걸으며, 이백여 년 전 청주 신앙의 뿌리를 되돌아본다.', '신유박해(1801)부터 병인박해(1866)까지 순교자를 낸 청주 지역 순교 사적지. 2014년 시복된 원시보 야고보, 배관겸 프란치스코, 오반지 바오로 등 5위가 이곳에서 순교했다. 서운동성당은 1932년 다른 성당에서 분리된 청주 첫 본당으로, 복자 오반지 바오로의 유해를 모시고 있다.', '청주읍성 순교성지 - 서운동성당과 다섯 복자', '충북 청주시 상당구, 신유박해부터 병인박해까지 순교자를 낸 청주 도심 순례길. 서운동성당에 오반지 바오로 유해가 모셔진 청주 첫 본당.', '치유', NULL, NULL),
  ('음성 감곡면 매괴성당', '주교좌성당', '청주', '충북', '충북 음성군 감곡면', '충북 음성군 감곡면, 나지막한 언덕 위에 고딕 첨탑이 하늘을 향해 서 있다. 1896년 프랑스인 임가밀로 신부가 세운 이 성당은 충북에서 가장 먼저 지어진 성당이다. 1930년 지금의 고딕 양식으로 새로 지어진 성당은 충북 유형문화재로 지정되어 있다. 임가밀로 신부는 51년 동안 이 자리를 지키며 문맹퇴치를 위한 학교를 세워 일제강점기 아이들에게 한글을 가르쳤고, 세상을 떠나서도 성당 소제대 곁에 잠들어 있다. 성모 순례지로도 이름난 이곳에서, 낯선 땅에 평생을 바친 한 선교사의 발자취를 만난다.', '1896년 프랑스인 임가밀로 신부가 세운 충북 최초의 성당(전국 18번째). 1930년 지어진 고딕 양식 성당은 충북 유형문화재 제188호. 임가밀로 신부는 51년간 사목하며 문맹퇴치를 위한 학교를 세워 한글을 가르쳤다.', '음성 감곡면 매괴성당 - 충북 천주교의 발상지', '충북 음성군, 1896년 임가밀로 신부가 세운 충북 최초의 성당(충북 유형문화재). 51년을 헌신한 선교사의 발자취가 남은 성모 순례지.', '감사', NULL, NULL),
  ('배티 순교성지', '순교성지', '청주', '충북', '충북 진천군 백곡면 양백리', '충북 진천과 경기 안성의 경계, 서운산 자락 깊은 계곡에 배나무 고개라는 뜻의 배티가 있다. 1830년경 박해를 피해 숨은 신자들이 이룬 비밀 교우촌으로, 한국 천주교의 카타콤이라 불린다. 1850년 프랑스인 주교가 이곳에 한국 최초의 신학교를 지었으며, 한국인 두 번째 사제 최양업 토마스 신부가 배티를 근거지 삼아 전국을 걸어 다니며 신자들을 돌보고 한글 기도서를 지어 나눠주었다. 1866년 병인박해 때는 55여 명이 이곳에서 순교했다. 오늘날 성지에는 고딕 양식 기념성당과 최양업 신부 박물관, 복원된 초가 신학교, 무명 순교자 묘역이 자리해 있어, 방문객은 걸음마다 조용히 신앙의 뿌리를 만나게 된다.', '1830년경부터 형성된 비밀 교우촌으로 한국 천주교의 카타콤으로 불린다. 1850년 프랑스인 주교가 한국 최초의 신학교(조선교구 소신학교)를 설립했고, 한국인 두 번째 사제 가경자 최양업 토마스 신부가 사목 중심지로 삼았다. 1866년 병인박해 때 55여 명이 순교했다.', '배티 순교성지 - 한국 천주교의 카타콤', '충북 진천군 백곡면, 최양업 신부가 사목 중심지로 삼았던 비밀 교우촌. 한국 최초 신학교 터와 병인박해 순교자 묘역을 품은 대표 성지.', '치유', NULL, NULL),
  ('연풍 순교성지', '순교성지', '청주', '충북', '충북 괴산군 연풍면', '문경새재로 넘어가는 길목, 연풍 예전 관아 터에 순교자들의 이야기가 남아 있다. 병인박해가 몰아치던 1866년, 새재를 오가며 신앙을 나누던 충북과 경북의 신자들이 이곳 연풍현 관아에 붙잡혀 처형되었다. 영남과 충청을 연결하는 교통 요충지였던 탓에, 이 길을 오가던 이들의 신앙도 함께 스러졌다. 조용한 산골 마을을 걸으며, 새재를 넘던 예전 신자들의 발걸음과 그 끝에 놓였던 형장을 함께 떠올려본다.', '병인박해(1866) 때 연풍현 관아에서 신자들이 처형된 순교지. 새재(조령) 인근 교통 요충지로, 충북과 경북을 오가던 신자들이 체포되어 순교했다.', '연풍 순교성지 - 새재 길목의 순교지', '충북 괴산군 연풍면, 병인박해 때 연풍현 관아에서 순교한 신자들의 자리. 문경새재를 오가던 충북·경북 신자들의 신앙이 스러진 곳.', '위로', NULL, NULL),
  ('충북 보은 멘에목 순례성지', '순례길', '청주', '충북', '충북 보은군', '보은 깊은 산골, 낮게 이어지는 작은 고개를 넘으면 이름 없이 살다 간 신자들의 자리가 있다. 1827년 정해박해 기록에 처음 등장하는 이 교우촌에는 박경화 바오로와 아들 박사의 안드레아가 신앙 공동체를 이루며 살았고, 최양업 신부가 이 산골까지 찾아와 성사를 베풀었다. 2014년 프란치스코 교황 방한 당시 이 세 사람이 복자품에 올랐고, 2016년 청주교구는 이곳을 정식 성지로 지정했다. 산으로 둘러싸인 고요한 계곡을 걸으며, 오래도록 잊혔던 작은 교우촌의 신앙을 다시 만난다.', '1827년 정해박해 때부터 기록에 등장하는 산골 교우촌. 복자 박경화 바오로·박사의 안드레아 부자가 거주했고 최양업 신부가 방문해 성사를 베풀었다. 2014년 프란치스코 교황 방한 시 박경화, 박사의, 그리고 김씨 복자까지 3위가 시복, 2016년 청주교구가 성지로 지정했다.', '충북 보은 멘에목 순례성지 - 보은 산골의 작은 교우촌', '충북 보은군, 정해박해 때부터 이어진 산골 교우촌. 복자 박경화·박사의 부자를 기리는 2016년 지정 성지.', '위로', NULL, NULL),
  ('전동성당', '주교좌성당', '전주', '전북', '전북 전주시 완산구 태조로 51 (전동)', '전주 한옥마을 입구, 경기전 맞은편에 회색 벽돌 성당이 우뚝 서 있다. 전동성당은 1791년 신해박해 때 한국 천주교 최초의 순교자 윤지충 바오로와 권상연 야고보가 풍남문 밖에서 처형된 바로 그 자리에 세워졌다. 1801년에는 호남의 사도 유항검 아우구스티노가 이곳에서 능지처참형을 당했다. 1908년 착공해 1914년 완공된 로마네스크 양식 성당 내부에는 18개의 색유리창이 순교자들의 이야기를 담고 있다. 한옥마을과 경기전, 치명자산으로 이어지는 순례길의 출발점으로, 호남 천주교 역사의 상징으로 자리잡았다.', '한국 천주교 최초의 순교자 윤지충 바오로와 권상연 야고보가 1791년 신해박해 때 처형된 자리에 세워진 성당(사적 제288호). 1908년 착공, 1914년 완공된 로마네스크 양식 건축.', '전동성당 - 한국 최초 순교자의 자리', '전북 전주시 완산구, 윤지충·권상연이 순교한 자리에 세워진 로마네스크 성당(사적 제288호). 한옥마을과 어우러진 호남 천주교의 상징.', '감사', NULL, NULL),
  ('치명자산 성지', '순례길', '전주', '전북', '전북 전주시 완산구 교동 승암산(치명자산) 정상', '전주 시내를 내려다보는 승암산 정상, 순교자의 산이라는 뜻의 치명자산이 있다. 1914년 보두네 신부가 유항검 아우구스티노와 그 가족 7명의 유해를 이 산 정상에 모시면서 붙은 이름이다. 유항검과 부인 신희, 동정부부 유중철·이순이를 비롯한 일가족이 나란히 합장되어 있다. 프랑스 파리의 순교 언덕과 견주어지는 이유다. 2014년 프란치스코 교황 방한 시 이 중 5위가 시복되었다. 십자가의 길을 따라 정상까지 오르는 순례 코스는 전주 시내를 한눈에 담는 야경 명소로도 사랑받는다.', '1914년 보두네 신부가 유항검 가족 순교자 7위의 유해를 산 정상에 모시면서 치명자산(순교자의 산)으로 불리게 되었다. 프랑스 파리의 순교 언덕과 견주어 한국의 순교자 언덕으로 불리며 2014년 프란치스코 교황 방한 시 5위가 시복되었다.', '치명자산 성지 - 전주의 순교자 언덕', '전북 전주시 완산구 승암산 정상, 유항검 일가족 7위가 합장된 순교성지. 십자가의 길과 전주 야경을 함께 만나는 순례 코스.', '새출발', NULL, NULL),
  ('초남이 성지', '순례길', '전주', '전북', '전북 전주시 완산구 (바우배기)', '전주 외곽 초남이 마을, 바우배기라 불리는 자리에 호남 신앙의 뿌리가 묻혀 있었다. 이곳은 호남의 사도 유항검 가족이 신앙을 키워가던 터전으로, 호남 지역 복음 전래가 시작된 자리로 알려져 있다. 오랜 세월 사람들의 기억에서 멀어졌던 이곳은 2014년 성역화 작업이 진행되며 뜻밖의 발굴로 이어졌다. 한국 최초의 순교자 윤지충과 권상연, 그리고 윤지헌의 유해가 이곳 바우배기에서 발견된 것이다. 평범한 마을 땅속에서 다시 세상에 나온 순교자들의 흔적 앞에서, 호남 신앙의 첫 자리를 다시 한번 되새겨본다.', '호남 천주교 복음 전래의 출발점이자 유항검 가족의 신앙 터전. 2014년 바우배기 성역화 작업 중 윤지충·권상연·윤지헌의 유해가 발굴되었다.', '초남이 성지 - 호남 신앙의 첫 자리, 바우배기', '전북 전주시 완산구, 유항검 가족의 신앙 터전이자 2014년 윤지충·권상연·윤지헌 유해가 발굴된 바우배기. 호남 복음 전래의 출발점.', '위로', NULL, NULL),
  ('나바위 성지', '순례길', '전주', '전북', '전북 익산시 망성면', '금강이 내려다보이는 나바위 언덕에 한옥 지붕을 얹은 특별한 성당이 있다. 1845년 김대건 신부가 중국에서 사제품을 받고 페레올 주교, 프랑스인 신부와 함께 황산 나루터에 배를 대고 내렸다. 한국인 최초의 사제가 고국 땅을 밟으며 처음 전도를 시작한 곳이기도 하다. 1906년 시공해 이듬해 완공한 성당은 서양식 건축과 한옥 양식을 절충한 독특한 모습으로, 사적 제318호로 지정되었다. 경내에는 김대건 신부 순교 100주년에 세워진 순교비가 자리한다. 금강을 따라 불어오는 바람 속에서, 조선 땅을 처음 밟은 사제의 설렘을 상상해본다.', '1845년 김대건 신부가 중국에서 사제 서품을 받고 페레올 주교, 프랑스인 신부와 함께 황산 나루터로 상륙해 처음 전도한 자리. 1906년 착공, 1907년 완공된 성당은 한옥과 서양식 건축이 어우러진 사적 제318호.', '나바위 성지 - 김대건 신부가 첫발로 내린 성당', '전북 익산시 망성면, 김대건 신부가 사제 서품 후 처음 상륙해 전도한 자리에 세워진 한옥 양식 성당(사적 제318호).', '새출발', NULL, NULL),
  ('천호성지', '순례길', '전주', '전북', '전북 완주군 비봉면 천호성지길', '완주 비봉면, 천호산 깊은 계곡에 박해를 피해 숨어든 신자들의 자리가 있다. 기해박해(1839) 이후 이 산자락에 교우촌이 형성되었고, 병인박해 때는 이명서·손선지·정문호·한재권 네 성인이 순교했다. 산속에는 프랑스인 주교와 신부가 몸을 숨긴 채 미사를 드렸던 작은 굴, 미사굴이 지금도 남아 있다. 피정의 집과 봉안경당, 성물박물관이 들어선 오늘날의 천호성지를 걸으며, 산속 깊이 숨어 신앙을 지켰던 이들의 절박한 시간을 만난다.', '기해박해(1839) 이후 천호산 자락에 형성된 교우촌. 병인박해 때 순교한 성인 4위(이명서·손선지·정문호·한재권)와 여산 순교자 10명이 안장되어 있다. 프랑스인 주교와 신부가 숨어 미사를 드린 미사굴이 남아 있다.', '천호성지 - 미사굴에 숨은 신앙', '전북 완주군 비봉면, 기해박해 이후 형성된 천호산 교우촌. 페레올 주교가 숨어 미사를 드린 미사굴과 병인박해 순교 성인 4위를 만나는 성지.', '평온', NULL, NULL),
  ('죽산 순교성지', '순교성지', '수원', '경기', '경기도 안성시 일죽면 죽림리', '충청·전라·경상으로 갈라지는 길목, 조선시대 죽산 도호부가 있던 자리에 잊혔던 순교의 역사가 남아 있다. 넓은 관할 구역 곳곳의 교우촌에서 체포된 신자들이 죽산 도호부의 옥에 갇혀 혹독한 고문을 받은 뒤, 지금의 성지 자리에서 처형되었다. 이름이 확인된 순교자만 24명에 이른다. 고려시대 몽골군이 진을 쳤던 이진터라는 이 자리에는, 박해가 남긴 아픔을 담아 잊은 터라는 이름이 붙었다. 오가는 이들의 발길 속에 잊혀갔던 순교자들의 이름을, 오늘 다시 불러본다.', '병인박해 때 체포된 신자들이 죽산 도호부 옥사에서 고문당한 뒤 처형된 자리. 이름이 밝혀진 순교자만 24명에 이른다. 예전 지명 이진터에 박해 시기 잊은 터라는 이름이 더해졌다.', '죽산 순교성지 - 잊은 터에 새긴 스물네 이름', '경기도 안성시 일죽면, 병인박해 때 죽산 도호부에서 순교한 24명의 신자를 기리는 성지. 충청·전라·경상 교통 요지에 새겨진 신앙의 역사.', '치유', NULL, NULL),
  ('은이 성지', '순례길', '수원', '경기', '경기도 용인시 처인구', '용인 처인구 산자락, 숨겨진 동네라는 뜻의 은이마을이 있다. 이곳은 열다섯 살 소년 김대건이 1836년 모방 신부에게 세례와 첫 성체를 받은 자리이자, 신학생으로 선발되어 마카오 유학길에 오른 출발점이다. 사제가 되어 돌아온 김대건 안드레아는 이곳을 첫 사목지로 삼았고, 순교하기 전 마지막으로 공식 미사를 드린 곳도 바로 은이였다. 소년의 첫 세례부터 사제의 마지막 미사까지, 김대건 신부의 생애 전체가 이 작은 교우촌 하나에 고스란히 담겨 있다.', '숨겨진 동네라는 뜻의 교우촌. 김대건 안드레아가 1836년 모방 신부에게 세례와 첫 성체를 받았고, 15세에 신학생으로 선발되어 마카오로 떠난 곳. 사제 서품 후 첫 사목지이자 순교 전 마지막 공식 미사를 드린 곳이다.', '은이 성지 - 김대건 신부, 세례부터 마지막 미사까지', '경기도 용인시 처인구, 김대건 신부가 세례를 받고 첫 사목과 마지막 미사를 드린 교우촌. 그의 생애 전체가 담긴 수원교구 핵심 성지.', '새출발', NULL, NULL),
  ('미리내 성지', '순례길', '수원', '경기', '경기도 안성시 양성면 미산리', '안성 깊은 산골, 밤하늘 은하수를 닮았다 하여 미리내라는 이름이 붙은 마을이 있다. 1846년 새남터에서 순교한 한국 최초의 사제 김대건 안드레아 신부의 시신을, 신자 이윤봉 루가가 위험을 무릅쓰고 이곳에 몰래 묻었다. 그날 이후 이 산골 마을은 한국 천주교에서 가장 성스러운 자리 중 하나가 되었다. 1906년 세워진 성 요셉 성당은 세계에서 가장 작은 성당으로 알려져 있고, 1991년 지어진 103위 시성 기념 성당에서는 오늘도 순례 미사가 드려진다. 가을 단풍이 절정에 이르는 10월, 미리내로 향하는 길 자체가 이미 순례의 시작이 된다.', '1846년 새남터에서 순교한 성 김대건 안드레아 신부의 시신이 이윤봉 루가에 의해 비밀리 안장된 곳(한국 최초 사제 유해 최초 안장지). 1906년 세워진 성 요셉 성당은 세계에서 가장 작은 성당으로 알려져 있다.', '미리내 성지 - 김대건 신부가 잠든 은하수 마을', '경기도 안성시 양성면, 김대건 신부의 유해가 최초로 안장된 수원교구 대표 성지. 세계에서 가장 작은 성당과 가을 단풍으로 유명하다.', '치유', NULL, NULL),
  ('남한산성 순교성지', '순교성지', '수원', '경기', '경기도 광주시 남한산성면', '조선의 오랜 역사를 간직한 유네스코 세계문화유산 남한산성, 그 성벽 안쪽에 순교의 기억이 조용히 스며 있다. 병인박해가 몰아치던 시절, 체포된 천주교 신자들이 이곳으로 압송되어 옥에 갇히고 처형당했다. 산성의 웅장한 성곽과 누각을 둘러보는 트레킹 코스를 걷다 보면, 화려한 역사 유산 이면에 새겨진 신앙의 아픔과 마주하게 된다. 세계유산 탐방과 순교 성지 순례가 하나로 이어지는 독특한 자리다.', '유네스코 세계문화유산 남한산성 내에서 병인박해 때 체포된 천주교 신자들이 옥사하거나 처형된 순교지.', '남한산성 순교성지 - 세계유산 속 순교의 기억', '경기도 광주시 남한산성면, 병인박해 때 신자들이 옥사·처형된 세계문화유산 내 순교지. 산성 트레킹과 함께하는 순례.', '평온', NULL, NULL),
  ('골배마실 성지', '순례길', '수원', '경기', '경기도 용인시 처인구 (은이성지 인근)', '은이성지 동쪽 갈미봉 아래, 계곡을 따라 들어앉은 작은 마을 골배마실이 있다. 김대건 신부의 조부 김택현은 가세가 기울고 신앙을 지키기 어려워지자 가족을 이끌고 이 산골 땅으로 이주해 왔고, 아버지 김제준도 1835년부터 이곳에 자리 잡았다. 소년 김대건이 뛰놀며 유년 시절을 보낸 곳도 바로 이 계곡이었다. 지금은 조용한 산길이 된 이 마을을 걸으며, 한국 최초의 사제가 자란 어린 시절의 풍경을 그려본다.', '김대건 신부의 조부 김택현과 부친 김제준이 신앙을 지키기 위해 이주해 정착한 교우촌. 김대건 신부가 유년 시절을 보낸 곳이다.', '골배마실 성지 - 김대건 신부의 유년 마을', '경기도 용인시 처인구, 김대건 신부 가족이 신앙을 지키기 위해 정착한 산속 교우촌. 그의 유년 시절이 담긴 조용한 성지.', '평온', NULL, NULL),
  ('풍수원성당', '주교좌성당', '원주', '강원', '강원특별자치도 횡성군 서원면 유현리', '횡성 깊은 산골, 220여 년 전 박해를 피해 신자들이 찾아든 자리에 고딕 첨탑이 서 있다. 1801년 신유박해 이후 경기도 용인에서 8일간 피난처를 찾아 고생하던 신태보 베드로와 40여 명의 신자들이 이 산골에 정착하며 한국 천주교 최초의 교우촌을 이루었다. 도기를 구우며 신앙을 지키던 이들의 후손들은 1896년 정규하 신부를 맞이해 성당을 짓기 시작했고, 1907년 완공된 이 성당은 한국인 신부가 직접 설계하고 지은 최초의 성당이자 강원도 첫 본당이 되었다. 고딕 양식의 붉은 벽돌 성당 앞에 서면, 산골 교우촌에서 이어져 온 220년 신앙의 시간을 느낀다.', '1801년 신유박해 이후 신태보 베드로를 중심으로 40여 명이 정착한 한국 천주교 최초의 교우촌. 1907년 완공된 성당은 한국인 신부가 설계·건립한 최초의 성당이자 강원도 첫 성당(강원도 유형문화재 제69호).', '풍수원성당 - 한국 최초의 산골 교우촌', '강원특별자치도 횡성군, 신유박해 이후 형성된 한국 최초의 교우촌에 세워진 성당. 한국인 신부가 지은 최초의 성당이자 강원도 첫 본당(강원 유형문화재).', '평온', NULL, NULL),
  ('용소막성당', '주교좌성당', '원주', '강원', '강원특별자치도 원주시 신림면', '원주 신림면, 들판 사이로 서양식 붉은 벽돌 성당이 고요히 자리하고 있다. 1898년 신자 최석두의 초가집에서 작은 공소로 출발한 용소막성당은 풍수원·원주에 이어 강원도에서 세 번째로 세워진 성당이 되었다. 1915년 프랑스인 신부의 손으로 지금의 벽돌 성당이 완공되었고, 1986년 강원도 유형문화재로 지정되었다. 이 아름다운 근대 건축물은 원주의 자랑거리로 사랑받는다. 조용한 시골 마을에서 만나는 이 작은 성당은, 소박하지만 단단했던 초기 신앙 공동체의 시간을 보여준다.', '1898년 신자 최석두의 초가집에서 시작되어 1915년 현재 건물이 완공된 강원도 세 번째 성당(강원도 유형문화재). 풍수원성당, 원주성당에 이어 세워졌다.', '용소막성당 - 원주 들판의 붉은 벽돌 성당', '강원특별자치도 원주시 신림면, 1915년 완공된 강원도 세 번째 성당(강원 유형문화재). 원주를 대표하는 아름다운 근대 건축물이다.', '감사', NULL, NULL),
  ('배론성지', '순례길', '원주', '충북', '충북 제천시 봉양읍 배론성지길', '제천 봉양읍, 배 밑바닥처럼 깊은 계곡이라 하여 배론이라 불리는 자리가 있다. 1801년 신유박해가 일어나자 황사영은 이곳 도기장을 가장한 토굴에 8개월간 숨어 지내며, 북경 주교에게 보낼 편지 백서를 비단에 써 내려갔다. 박해의 참상과 신앙의 자유를 향한 절박한 호소가 담긴 이 편지는 조선 천주교사의 가장 극적인 기록으로 남았다. 1855년에는 한국 최초의 신학교인 성 요셉 신학당이 이곳에 세워져 한국인 성직자를 길러냈고, 한국인 두 번째 사제 최양업 토마스 신부가 이곳에 잠들어 있다. 깊은 계곡을 걸으며, 박해와 배움이 함께 새겨진 조선 천주교의 뿌리를 만난다.', '1801년 신유박해 때 황사영이 8개월간 숨어 지내며 백서를 쓴 토굴이 있는 곳. 1855년 한국 최초의 신학교 성 요셉 신학당이 세워졌고, 한국인 두 번째 사제 최양업 토마스 신부의 묘가 있다.', '배론성지 - 황사영 백서와 한국 최초 신학교', '충북 제천시 봉양읍, 황사영이 백서를 쓴 토굴과 한국 최초 신학교 터. 최양업 신부의 묘가 있는 원주교구 대표 성지.', '치유', NULL, NULL),
  ('강릉 임당동성당', '주교좌성당', '원주', '강원', '강원특별자치도 강릉시 임영로 148', '강릉 임당동, 높다란 종탑과 첨두형 아치 창문을 가진 성당이 오래된 동네를 지키고 있다. 1921년 금광리에서 시작된 강릉 본당은 여러 차례 자리를 이전한 끝에 1955년 지금의 성당을 신축하며 새 이름을 얻었다. 전쟁의 상처가 채 가시지 않은 시절 지어진 이 성당은 1950년대 강원도 성당 건축의 특징을 고스란히 간직해 국가등록문화재로 지정되었다. 정교한 몰딩과 아치 장식이 남아있는 성당 내부를 둘러보면, 전후 강원 신앙 공동체가 다시 일어서던 시간이 느껴진다.', '1921년 시작된 강릉 지역 첫 본당. 1955년 신축된 성당은 1950년대 강원도 성당 건축의 전형을 보여주는 건물로 국가등록문화재 제457호.', '강릉 임당동성당 - 전후 강원 신앙의 증언', '강원특별자치도 강릉시, 1955년 신축된 강릉 첫 본당. 1950년대 강원 성당 건축의 전형을 보여주는 국가등록문화재 제457호.', '감사', NULL, NULL),
  ('소양로 순교성지', '순교성지', '춘천', '강원', '강원특별자치도 춘천시 서면 모수물길 22번길 26', '춘천 도심에서 소양강 쪽으로 발걸음을 옮기면 조용한 순교의 언덕이 나타난다. 병인박해가 몰아치던 1866년, 강원도 곳곳에서 붙잡힌 천주교 신자들이 이곳에서 처형되었다. 소양강의 맑은 물소리를 배경으로 순교자 현양비가 고요히 서 있어, 낭만적인 호반 도시 춘천의 이면에 새겨진 신앙의 역사를 마주하게 된다. 춘천역에서 멀지 않은 거리라 도심 산책 삼아 들르기 좋은 조용한 성지다.', '병인박해(1866) 때 강원도 지역 천주교인들이 처형된 춘천 지역 순교터.', '소양로 순교성지 - 소양강변의 작은 순교 언덕', '강원특별자치도 춘천시, 병인박해 때 강원 지역 신자들이 순교한 춘천 도심 성지. 소양강변의 조용한 현양비.', '위로', NULL, NULL),
  ('화현 이벽 성지', '순례길', '의정부', '경기', '경기도 포천시 화현면 화현리', '포천 화현리, 평신도의 힘만으로 신앙 공동체를 이룩한 한국 천주교 최초의 지도자가 태어난 자리가 있다. 무반 집안 출신이던 광암 이벽은 정약전·정약용 형제와 교유하며 학문을 닦다가, 1779년 겨울 천진암에서 열린 강학회를 통해 서학과 천주교 신앙을 받아들였다. 사제 없이 평신도들 스스로 시작한 한국 천주교회에서, 이벽은 그 첫 지도자였다. 순교 후 190년 넘게 사람들의 기억에서 멀어져 있던 그의 묘는 1970년대 후반 발견되어 천진암성지로 이전되었고, 태어나고 순교한 이곳 화현리는 2023년 춘천교구에 의해 성지로 선포되었다. 가장 늦게 태어난 성지에서, 가장 처음 신앙을 일으킨 이의 자취를 만난다.', '한국 천주교회 최초의 지도자 광암 이벽 요한(1754~1785)이 태어나고 순교한 자리. 정약전·정약용과 교유하며 1779년 천진암 강학을 통해 신앙을 받아들였다. 2023년 5월 춘천교구가 성지로 선포한 가장 최근의 성지다.', '화현 이벽 성지 - 한국 천주교 첫 지도자의 고향', '경기도 포천시 화현면, 한국 천주교회 최초 지도자 이벽이 태어나고 순교한 자리. 2023년 춘천교구가 선포한 가장 최근의 성지.', '새출발', NULL, NULL),
  ('갑곶 순교성지', '순교성지', '인천', '경기', '인천광역시 강화군 강화읍 해안동로1366번길 35', '강화도 돈대 인근, 바다를 바라보는 언덕 위에 순교의 기억이 자리한다. 병인박해가 몰아치던 시절, 강화도에서 신앙을 지키던 이들이 이곳에서 생을 마감했다. 가톨릭 순교 역사를 직접 증언한 인물로 유명한 박순집 베드로의 묘가 이곳에 있으며, 인천교구 설정 50주년을 기념해 세운 영성센터가 함께 자리해 피정과 순례를 겸할 수 있다. 강화대교를 건너 만나는 첫 번째 신앙의 증거지다.', '병인박해 때 강화도에서 순교한 이들을 기리는 성지. 가톨릭 순교 역사를 증언한 박순집 베드로의 묘가 있다.', '갑곶 순교성지 - 강화 바다가 품은 신앙', '인천광역시 강화군, 병인박해 때 강화도 순교자를 기리는 성지. 박순집 베드로의 묘와 영성센터가 함께 있어 피정과 순례를 겸한다.', '치유', NULL, NULL),
  ('제물진두 순교성지', '순교성지', '인천', '경기', '인천광역시 중구 제물량로 240', '인천역 인근, 늘 바다를 향해 열려있던 포구 한자리에 순교의 기억이 새겨져 있다. 1866년 병인박해 이후 한국 최초의 영세자 이승훈 베드로의 증손자 이연구와 이균구를 비롯한 열 명이 이곳에서 처형되었다. 1845년에는 한국인 최초의 사제가 될 김대건 부제가 사제 서품을 받기 위해 이 근처 포구에서 작은 배를 타고 중국으로 떠났다. 2014년 완공된 순교기념경당은 하늘을 향해 솟아오르는 15m 높이의 높다란 건물로 순교자들의 영성을 상징한다. 조용한 포구에서, 떠나간 이들과 남은 이들의 신앙을 함께 떠올려본다.', '1866년 병인박해 이후 한국 첫 영세자 이승훈 베드로의 후손들을 비롯한 열 명이 처형된 자리. 1845년 김대건 부제가 사제 서품을 받기 위해 중국으로 떠난 포구이기도 하다.', '제물진두 순교성지 - 포구에 새겨진 신앙', '인천광역시 중구, 이승훈 베드로의 후손들을 비롯한 10명이 순교한 제물포 포구 순교지. 김대건 부제가 사제 서품을 받으러 떠난 포구이기도 하다.', '치유', NULL, NULL),
  ('답동주교좌성당', '주교좌성당', '인천', '경기', '인천광역시 중구 우현로50번길 2', '인천 차이나타운에서 가파른 계단길을 오르면 갑자기 로마네스크 양식 붉은 벽돌 건물이 눈앞에 펼쳐진다. 1889년 제물포 개항과 함께 세워진 답동성당은 한국에서 가장 오래된 서양식 성당 중 하나로, 사적 제287호로 지정되어 있다. 개항장의 이국적인 풍경과 유서 깊은 천주교 역사가 한 자리에서 어우러진다. 성당 앞에 서면 인천항이 내려다보여, 개항 당시의 분위기를 상상하게 한다. 인천역에서 도보 10분 거리라 차이나타운과 함께 둘러보기 좋다.', '1889년 제물포 개항과 함께 세워진 한국에서 가장 오래된 서양식 성당 중 하나(사적 제287호). 인천교구의 주교좌성당이자 개항장 역사를 대표하는 건축물이다.', '답동주교좌성당 - 개항장 언덕 위의 백년 성당', '인천광역시 중구, 1889년 세워진 한국 최고(最古) 서양식 성당 중 하나(사적 제287호). 인천 차이나타운과 가까운 개항장 순례지.', '감사', NULL, NULL),
  ('이승훈 베드로 성지', '순례길', '인천', '경기', '인천광역시 남동구 무네미로 143', '인천 남동구, 한국 천주교 첫 영세자의 이름을 따 이승훈베드로길이 난 자리에 기념관이 서 있다. 어린 시절 베이징 북당에서 프랑스인 신부에게 교리를 배운 이승훈은 1784년 귀국후 세례를 받아 한국 최초의 천주교 영세자가 되었다. 이후 미사와 세례를 직접 진행하며 교리를 전해 신앙 공동체의 출발을 이끌었다. 1801년 신유박해 때 순교한 뒤 인천 이 자리에 묻혔고, 2024년에는 그를 기리는 성지기념관이 새롭게 문을 열었다. 한국 천주교회의 출발점에 선 이의 이야기를, 이곳에서 만난다.', '1784년 한국 최초로 세례를 받은 이승훈 베드로(1756~1801)의 선산이 있는 성지. 1801년 신유박해 때 순교한 뒤 이곳에 묻혔다. 2024년 기념관이 건립되었다.', '이승훈 베드로 성지 - 한국 천주교 첫 영세자', '인천광역시 남동구, 한국 최초 영세자 이승훈 베드로의 선산이 있는 성지. 2024년 건립된 기념관에서 그의 생애를 만난다.', '치유', NULL, NULL),
  ('황사영 순교순례지', '순교성지', '의정부', '경기', '경기도 양주시 장흥면 부곱리 일대 (홍복산)', '양주 홍복산 자락, 오랜 세월 이름 없는 묘로 남아있던 자리가 있다. 1801년 신유박해 때 배론 토굴에서 백서를 쓴 죄로 능지처참형을 받은 황사영 알렉시오가 이곳에 묻혔다. 세월이 흘러 이 묘의 주인이 누구인지조차 사람들의 기억에서 멀어질 무렵인 1980년, 후손들이 홍복산 선영에서 오래된 봉분 하나를 조사하다 뜻밖의 유물을 발견했다. 항아리 속에는 돌로 만든 십자가와 비단 조각이 들어 있었고, 이는 이 묘의 주인이 황사영임을 증명하는 결정적 단서가 되었다. 조용한 산자락에서, 목숨을 걸고 진실을 알리려 했던 한 신자의 마지막 자리를 마주한다.', '신유박해(1801) 때 백서를 써 능지처참형을 받은 황사영 알렉시오가 묻힌 자리. 1980년 후손들이 무덤을 발견해 석제 십자가와 비단 조각이 담긴 항아리를 확인, 신원이 밝혀졌다.', '황사영 순교순례지 - 백서를 쓴 이의 마지막 자리', '경기도 양주시 홍복산, 신유박해 때 백서를 쓰고 순교한 황사영 알렉시오의 묘소. 1980년 유물 발견으로 신원이 밝혀진 순례지.', '치유', NULL, NULL),
  ('파티마평화의성당', '주교좌성당', '의정부', '경기', '경기도 파주시 문산읍 마정로 110', '파주 문산, 임진각에서 멀지 않은 자리에 거의 눈에 띄지 않는 특별한 성당이 있다. 휴전선과 가장 가까운 이 성당은 고도 제한 때문에 지상에 지을 수 없어 통째로 지하에 만들어졌다. 1982년부터 30여 년간 평화통일을 기원하는 성당을 세우려는 노력이 이어졌고, 후보지가 여러 번 바뀌었던 어려움 끝에 2015년 드디어 봉헌되었다. 티 없으신 마리아 성심 수녀회가 관리하는 이곳은 분단의 아픔을 품고 한반도의 평화를 기도하는 공간이다. 땅 아래 조용한 성전에서, 통일을 향한 오랜 염원과 마주한다.', '휴전선에서 가장 가까운 성당으로, 고도 제한 때문에 지하에 지어졌다. 1982년부터 30여 년간 추진되어 2015년 문을 열었으며 한반도 평화통일을 기원하는 기도의 공간이다.', '파티마평화의성당 - 땅 아래 지어진 평화의 기도', '경기도 파주시 문산읍, 휴전선에서 가장 가까운 지하 성당. 30여 년의 노력 끝에 2015년 봉헌된 한반도 평화통일 기원의 공간.', '평온', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('구산 성지', '순교성지', '수원', '경기', '경기도 하남시 망월동 387-10', '하남 검단산 자락, 170년 넘게 이어온 신앙 공동체의 숨결이 남아있는 마을. 이곳은 순교성인 김성우 안토니오가 태어나고 자란 자리다. 그는 두 형제와 함께 온 마을을 신앙 공동체로 일으켰으나, 1839년 기해박해 때 체포되었다가 풀려난 뒤 이듬해 다시 붙잡혀 배교를 강요받았다. "나는 천주교인이오. 살아도 죽어도 천주교인으로 살겠소"라는 말을 남기고 1841년 마흔일곱의 나이로 순교했다. 2001년 하남시 향토유적 제4호로 지정되었고 1980년 로마 교황청으로부터 세계 성지로 선포되었다.', '103위 순교성인 김성우 안토니오(1795~1841)의 생가터이자 신앙공동체 발상지. 1841년 기해박해 순교, 1984년 시성. 하남시 향토유적 제4호.', '구산 성지 - 김성우 안토니오의 신앙 마을', '경기 하남 구산성지, 순교성인 김성우 안토니오가 태어나 온 마을을 신앙 공동체로 일으킨 자리.', '치유', NULL, NULL),
  ('남양 성모 성지', '순례길', '수원', '경기', '경기도 화성시 남양리 1704', '화성 남양리, 넓은 들판 한가운데 하늘에서 내려다보면 이콘화처럼 보인다는 로사리오 기도 경당이 자리한다. 1866년 병인박해 당시 신앙 공동체가 있던 이곳은 1991년 한국 최초의 마리아 성지로 봉헌되었다. 지름 70센티미터 돌구슬이 늘어선 20단 로사리오 기도길을 천천히 걸으면 어느새 기도가 된다. 2006년에는 자비의 예수님 동산이, 2023년에는 이탈리아 건축가 마리오 보타가 설계하고 남북통일을 기원하는 남양 성모 대성당이 봉헌되며 성지는 계속 자라나고 있다.', '1991년 봉헌된 한국 최초의 마리아 성지. 1866년 병인박해기 교우촌 터. 2023년 마리오 보타 설계의 남양 성모 대성당 봉헌.', '남양 성모 성지 - 한국 최초의 마리아 성지', '경기 화성 남양성모성지, 1991년 봉헌된 한국 첫 마리아 성지. 로사리오 기도길과 2023년 마리오 보타 설계 대성당.', '평온', NULL, NULL),
  ('단내 성가정 성지', '순교성지', '수원', '경기', '경기도 이천시 호법면 단천리 357', '이천 호법면, 남한산성에서 백지사형을 받은 두 친족의 이야기가 전해지는 자리. 예순셋의 정은 바오로는 박해를 피해 동굴에 숨어 지내다 결국 체포되었고, 재종손 정양묵 베드로는 병든 숙부를 홀로 둘 수 없다며 스스로 자원해 함께 붙잡혔다. 혹독한 고문에도 신앙을 버리지 않은 두 사람은 1866년 12월 8일 순교했다. 1784년 한국천주교회 창립보다도 앞서 신앙 공동체가 있었던 유서 깊은 땅으로, 103위 순교성인 중 다섯 명이 이천 지역과 인연이 있다.', '1866년 병인박해 때 정은 바오로·정양묵 베드로 등이 백지사형으로 순교. 한국 최초기 교우촌 중 하나로 103위 순교성인 5위와 연고.', '단내 성가정 성지 - 가족이 함께 지킨 신앙', '경기 이천 단내성가정성지, 정은 바오로·정양묵 베드로 두 친족이 함께 순교한 병인박해 성지.', '위로', NULL, NULL),
  ('손골 성지', '순례길', '수원', '경기', '경기도 용인시 수지구 동천동 734', '용인 광교산 자락, 열두 가구 남짓한 작은 교우촌이 있던 자리에 파리외방전교회 선교사들이 조선말을 익히며 사목을 준비하던 흔적이 남아있다. 다블뤼, 페레올, 오매트르 신부 등이 이곳을 거쳐 갔고, 특히 성 앙리 도리 신부는 1866년 2월 27일 이곳에서 체포되어 3월 7일 서울 새남터에서 순교했다. 1966년 도리 신부 순교 100주년을 맞아 프랑스 고향에 있던 그의 아버지 연자맷돌로 만든 십자가가 반으로 나뉘어, 하나는 프랑스에 하나는 이곳 손골에 세워졌다.', '파리외방전교회 선교사들의 조선어·사목 준비지. 성 앙리 도리 신부가 1866년 이곳에서 체포되어 새남터에서 순교.', '손골 성지 - 선교사들이 조선을 배운 자리', '경기 용인 손골성지, 파리외방전교회 선교사들이 사목을 준비하던 교우촌. 성 도리 신부의 체포지이자 한불 우정의 상징.', '평온', NULL, NULL),
  ('수리산 성지', '순교성지', '수원', '경기', '경기도 안양시 만안구 안양 9동 1151-2', '안양 수리산 자락, 예전에는 담배골 또는 병목골이라 불리던 산골 마을. 한국 두 번째 사제 최양업 토마스 신부의 아버지 최경환 프란치스코가 1837년 무렵 가족을 이끌고 정착해 교우촌을 이루었다. 그는 마을의 회장으로 신자들을 이끌다 1839년 기해박해 때 체포되었는데, 관헌을 태연히 맞아들이고 아침상까지 차려주었다는 일화가 전해진다. 고문 후유증으로 옥사한 뒤, 부인 이성례 마리아도 이듬해 순교해 2014년 프란치스코 교황 방한 때 함께 시복되었다.', '최양업 신부의 부친 최경환 프란치스코가 이끈 교우촌 터. 1839년 기해박해 순교, 부인 이성례 마리아도 순교, 2014년 시복.', '수리산 성지 - 담배골에 숨은 교우촌', '경기 안양 수리산성지, 최양업 신부의 부친 최경환 프란치스코 일가가 신앙을 지킨 교우촌 터.', '위로', NULL, NULL),
  ('양근 성지', '순례길', '수원', '경기', '경기도 양평군 양평읍 오빈리 173-2', '양평 남한강변, 홍수마다 마을을 지켜준 버드나무 뿌리에서 이름을 딴 양근 땅. 권철신·권일신 형제가 초기 신앙 공동체를 이끌었고, 1784년 북경에서 세례를 받고 돌아온 한국 첫 영세자 이승훈이 이곳에서 권철신에게 세례를 주며 신앙이 충청·전라로 퍼져나갔다. 가성직 제도가 시행되던 이 땅에서 동정부부 조숙 베드로와 권천례 데레사가 태어나 순교했고, 양근천이 한강과 만나는 오빈다리 인근에서는 윤유오·윤점혜·권상문 등이 참수되었다. 2014년 네 명이 프란치스코 교황에 의해 시복되었다.', '한국천주교회 초기 신앙 공동체의 요람. 이승훈이 권철신에게 세례를 준 자리, 오빈다리 순교터. 2014년 4위 시복.', '양근 성지 - 한국 천주교의 요람', '경기 양평 양근성지, 이승훈이 세례를 전한 초기 신앙공동체의 요람이자 오빈다리 순교터.', '새출발', NULL, NULL),
  ('어농 성지', '순교성지', '수원', '경기', '경기도 이천시 모가면 어농리 322-4', '이천 모가면, 죽음으로 신앙을 지킨 윤유일 바오로 일가의 안식처. 윤유일은 북경을 세 차례 오가며 조선에 첫 외국인 사제를 모셔오는 임무를 완수한 인물이다. 1794년 12월 주문모 야고보 신부를 조선 땅에 이끌어 이듬해 부활절 한국 최초의 미사가 봉헌되도록 했으나, 1795년 6월 28일 지황·최인길과 함께 순교했다. 1987년 성지로 조성되고 2002년 을묘·신유박해 순교자 현양성지로 지정되었으며, 2014년 17위가 시복되었다.', '조선에 첫 외국인 사제 주문모 신부를 모셔온 윤유일 바오로 등 3인이 1795년 순교한 자리. 2014년 17위 시복.', '어농 성지 - 첫 사제를 모셔온 이의 안식처', '경기 이천 어농성지, 주문모 신부를 조선에 모셔온 윤유일 바오로 등이 순교한 자리. 2014년 17위 시복 성지.', '치유', NULL, NULL),
  ('요당리 성지', '순교성지', '수원', '경기', '경기도 화성시 양감면 요당리 191-1', '화성 양감면, 밀물 때 물길이 닿는 지형 덕에 충청·경기 내륙과 서울을 잇는 은밀한 선교 거점이 되었던 마을. 1801년 신유박해 이후 서울과 내포 지방에서 피신해 온 신자들이 자리를 잡았다. 순교성인 장주기 요셉과 복자 장 토마스 형제가 이곳에서 나고 자랐으며, 다블뤼 주교의 피신을 도운 이들도 이 땅과 인연이 깊다. 수원교구는 2006년부터 경당과 로사리오 기도길, 십자가의 길을 조성했고 2010년 대성당이 봉헌되었다. 1998년 화재로 그을린 나무로 만든 십자가의 길 조각도 눈여겨볼 만하다.', '순교성인 장주기 요셉의 고향이자 신유박해 이후 형성된 교우촌. 2010년 대성당 봉헌.', '요당리 성지 - 장주기 요셉의 고향', '경기 화성 요당리성지, 순교성인 장주기 요셉의 고향이자 신유박해 이후 피신 교우촌. 2010년 봉헌된 대성당.', '평온', NULL, NULL),
  ('천진암 성지', '순례길', '수원', '경기', '경기도 광주시 퇴촌면 천진암로 1203', '광주 앵자봉 자락, 폐허가 된 암자 터에 한국 천주교 신앙이 처음 싹텄다. 1779년 겨울, 권철신·이벽 등 젊은 학자들이 이곳에 모여 서학과 천주교 교리를 강학했고, 이벽의 권유로 이승훈이 북경에 파견되어 1784년 세례를 받고 돌아오며 한국천주교회가 정식으로 창립되었다. 정하상 바오로, 유진길 아우구스티노 등 순교자들의 넋도 함께 기려진다. 매년 세례자 요한 탄생 축일에 창립기념미사가 봉헌되며, 매월 첫째 토요일 저녁이면 촛불을 든 순례객들의 로사리오 기도 행렬이 산길을 밝힌다.', '1779년 강학회가 열려 한국천주교회 신앙이 싹튼 자리. 이벽·권철신 등이 참여, 이승훈의 북경 파견으로 이어짐.', '천진암 성지 - 한국 천주교 신앙이 싹튼 자리', '경기 광주 천진암성지, 1779년 강학회로 한국천주교 신앙이 시작된 발상지. 매월 첫 토요일 촛불 기도 행렬.', '새출발', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('가톨릭 목포 성지', '성당', '광주대', '전남', '전라남도 목포시 산정동 90-1', '목포항이 내려다보이는 산정동 언덕, 붉은 벽돌 성당이 개항 도시의 첫 신앙 역사를 품고 있다. 1897년 목포 개항과 함께 세워진 이 성당은 광주대교구 첫 본당이자 한국 레지오 마리애가 처음 조직된 발상지다. 6·25전쟁 때는 브레난 주교와 두 명의 신부가 순교했고, 전쟁 후에는 순교자 기념비와 한국 레지오 마리애 기념관이 세워졌다. 1937년 지어진 옛 주교관은 국가등록문화재 제513호로 지정되어 2017년 역사박물관으로 새 단장했다.', '1897년 목포 개항과 함께 설립된 광주대교구 첫 본당. 한국 레지오 마리애 발상지. 6·25전쟁 때 브레난 주교 등 순교.', '가톨릭 목포 성지 - 개항과 함께한 첫 본당', '전남 목포 산정동성당, 1897년 개항과 함께 세워진 광주대교구 첫 본당. 한국 레지오 마리애 발상지이자 6·25 순교의 기억.', '감사', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('왜고개 성지', '순교성지', '군종', '서울', '서울시 용산구 용산동 5가 2-65', '용산 군종교구청과 국군중앙성당이 자리한 이 언덕은 예전에 기와와 벽돌을 굽던 가마터라 왜고개라 불렸다. 1839년 기해박해 때 새남터에서 순교한 앵베르 주교, 모방·샤스탕 신부의 유해가 이곳에 임시로 묻혔고, 1866년 병인박해 순교자 7위는 33년, 서소문 순교자 2위는 43년간 이 땅에 잠들어 있었다. 김대건 안드레아 신부의 유해도 1846년 순교 직후 잠시 이곳에 모셔졌다. 열 분의 순교자 중 여덟 분이 1984년 성인으로 선포되었으며, 2013년 군종교구가 현양비와 대형 십자가, 십자가의 길을 조성했다.', '1839·1866년 순교자들의 유해가 임시로 묻혔던 곳. 김대건 신부 유해도 순교 직후 잠시 안장. 8위 성인의 인연이 깃든 땅.', '왜고개 성지 - 순교자들이 잠시 머문 자리', '서울 용산 왜고개성지, 앵베르 주교와 김대건 신부 등 순교자들의 유해가 임시로 묻혔던 군종교구 성지.', '위로', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('김기량 순교 기념관', '순교성지', '제주', '제주', '제주도 제주시 조천읍 함덕리 940-2', '제주 조천읍 함덕리, 김기량 펠릭스 베드로가 태어난 바닷가 마을. 뱃사람이었던 그는 1857년 풍랑을 만나 표류하다 영국 배에 구조되어 홍콩에서 조선인 신학생을 만나 교리를 배우고 제주 사람 최초로 세례를 받았다. 고향으로 돌아와 가족과 동료 뱃사람들에게 신앙을 전하던 그는 1866년 병인박해 때 통영에서 체포되었고, 혹독한 매질 속에서도 함께 잡힌 신자들에게 "나는 순교하기로 결심했으니 흔들리지 마시오"라고 격려한 뒤 1867년 순교했다.', '제주인 최초의 세례자 복자 김기량 펠릭스 베드로(1816~1867)의 고향. 1867년 통영에서 순교, 2014년 시복.', '김기량 순교 기념관 - 제주 첫 신앙인의 고향', '제주 조천읍 함덕리, 제주인 최초 세례자 복자 김기량 펠릭스 베드로의 고향에 세워진 기념관.', '새출발', NULL, NULL),
  ('새미 은총의 동산', '순례길', '제주', '제주', '제주도 제주시 한림읍 금악리 365-1', '한림읍 금악리, 세 봉우리에 둘러싸인 연못이라는 뜻의 새미소 옆으로 은총의 동산이 펼쳐진다. 1992년 이 자리에 순례지를 조성하자는 사제들의 바람이 모여 시작되었고, 2009년 샘물처럼 끝없이 흐르는 은총을 뜻하는 지금의 이름을 얻었다. 연못을 도는 15단 로사리오 기도길과 켈트 십자가 모양의 삼위일체 대성당, 열두 장면으로 꾸며진 예수 생애 공원, 실물 크기 14처 십자가의 길까지 걸으며 하루를 온전히 기도로 채울 수 있는 곳이다.', '1992년 조성 시작, 2009년 새미 은총의 동산으로 명명된 제주교구 대표 순례지. 삼위일체 대성당과 로사리오 기도길.', '새미 은총의 동산 - 샘물처럼 흐르는 은총', '제주 한림읍 금악리, 연못을 도는 로사리오 기도길과 삼위일체 대성당이 있는 제주교구 대표 순례지.', '평온', NULL, NULL),
  ('황경한 묘', '순교성지', '제주', '제주', '제주도 제주시 추자면 신양리 산 20-1', '제주 추자도 예초리 바닷가, 황사영의 두 살배기 아들이 홀로 남겨졌던 자리. 1801년 신유박해로 아버지 황사영이 백서 사건으로 처형된 뒤, 어머니 정난주 마리아는 관비 신분으로 제주에 유배되던 뱃길에서 아들만이라도 평생 종의 신분을 면하게 하려고 갓난아기를 이 바위 해안에 남겨두었다. 오씨 성을 가진 늙은 어부가 아이를 발견해 거두어 키웠고, 아이는 자라 이곳에서 후손을 남겼다. 1999년 제주교구가 그의 묘가 있는 신양리 산자락을 성지로 지정했다.', '순교자 황사영의 아들 황경한이 어머니 정난주에 의해 남겨진 자리. 오씨 어부가 아이를 거두어 키운 사연이 전해짐. 1999년 성지 지정.', '황경한 묘 - 추자도에 남겨진 아이', '제주 추자도, 정난주 마리아가 아들 황경한을 남겨두고 떠난 자리. 1999년 성지로 지정된 애끓는 모정의 흔적.', '위로', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('농은 홍유한 선생 고택지', '순례길', '안동', '경북', '경상북도 영주시 단산면 구구리 322-5', '영주 소백산 자락, 한국천주교회가 창립되기 30년도 전에 이미 스스로 신앙을 실천한 이가 살던 자리. 농은 홍유한은 성호 이익 문하에서 실학을 공부하다 1750년 무렵 천주교 서적을 접했고, 세례 없이도 매달 7·14·21·28일을 주일로 삼아 기도와 묵상, 단식으로 신앙을 살았다. 1775년 이곳 구고리로 옮겨와 마지막 십 년을 은수자처럼 지내다 세상을 떠났다. 그의 후손 13명이 순교자가 되었고 그중 홍병주 베드로, 홍영주 바오로 형제는 103위 성인 반열에 올랐다.', '세례 없이 스스로 신앙을 실천한 농은 홍유한(1726~1785)의 고택지. 후손 13명이 순교, 그중 2명은 103위 성인으로 시성.', '농은 홍유한 선생 고택지 - 세례 없이 산 신앙', '경북 영주 홍유한 고택지, 한국천주교 창립 전 스스로 신앙을 실천한 농은 홍유한의 자취. 후손 13명이 순교자가 된 신앙 명가의 뿌리.', '평온', NULL, NULL),
  ('마원 성지', '순교성지', '안동', '경북', '경상북도 문경시 문경읍 마원리 600-1', '문경새재 인근 마원리, 1801년 이후 박해를 피해 온 신자들이 화전을 일구며 살던 산골 마을. 1866년 병인박해 때 이 지역 신자 40여 명이 체포되어 순교했다. 그중 서른 살의 지역 아전이었던 복자 박상근 마티아는 갈레 신부의 은신을 도왔는데, 신부가 안전을 위해 집으로 돌아가라 이르자 "제가 신부님 곁을 떠나다니요" 하며 눈물로 거절하고 끝내 함께 체포되어 1867년 옥에서 순교했다.', '복자 박상근 마티아(1837~1867)가 갈레 신부를 보호하다 순교한 자리. 1866년 병인박해 때 40여 명 체포·순교.', '마원 성지 - 신부님 곁을 떠나지 않은 이', '경북 문경 마원성지, 갈레 신부를 지키다 순교한 복자 박상근 마티아의 자취가 남은 산골 교우촌 터.', '위로', NULL, NULL),
  ('머루산 교우촌', '교우촌', '안동', '경북', '경상북도 영양군 석보면 포산리 131 부근', '영양 태백산맥 깊은 산자락, 포도산 정상 부근에 자리했던 산간 교우촌. 1801년 신유박해를 피해 충청 지역에서 넘어온 신자들이 산을 일구어 밭을 만들고 머루와 다래를 따 먹으며 신앙을 지켰다. 1815년 을해박해로 다시 발각되어 신자들이 체포되면서 교우촌은 완전히 흩어지고 말았다. 2014년 이곳과 인연이 깊은 김시우 알렉시오, 이시임 안나, 김강이 시몬이 나란히 시복되었다.', '신유박해 이후 형성된 산간 교우촌, 1815년 을해박해로 해체. 김시우 알렉시오 등 3위가 2014년 시복.', '머루산 교우촌 - 산 위에서 지킨 신앙', '경북 영양 머루산 교우촌, 신유박해를 피해 산속으로 숨어든 신자들의 자취. 2014년 시복된 3위 순교자의 고향.', '평온', NULL, NULL),
  ('상주 옥 터', '순교성지', '안동', '경북', '경상북도 상주시 성동동 (남문시장 옛 자리)', '상주 성동동 남문시장 자리, 조선말 상주진영의 옥이 있던 곳. 정해박해가 일어난 1827년, 순교자 박보록·박사의 부자가 살던 멍애목, 순교자 사건 안드레아가 살던 앵무동, 순교자 신태보 일가가 살던 잣골 등 상주 곳곳에서 붙잡힌 신자들이 이곳 옥에 갇혀 문초를 받았다. 지금은 시장통 골목으로 변한 이 자리에서, 안동교구 상주 지역에 뿌리내렸던 여러 순교자 가문의 마지막 발자취를 되짚어본다.', '1827년 정해박해 때 상주 지역 신자들이 갇혀 문초받은 상주진영 옥터.', '상주 옥 터 - 정해박해 순교자들의 마지막 자리', '경북 상주 옥터, 정해박해 때 상주 지역 신자들이 갇혀 문초받은 옛 상주진영 옥터.', '위로', NULL, NULL),
  ('상주 신앙 고백비', '역사사적지', '안동', '경북', '경상북도 상주시 청리면 삼괴리 361', '상주 청리면, 화강암에 손수 자신의 신앙을 새겨넣은 한국 유일의 신앙고백비가 서 있다. 1866년 병인박해 이전부터 천주교를 믿어온 김복운의 넷째 아들 김삼록 도미니코는 형제들이 박해 속에 신앙을 버렸을 때도 끝까지 신앙을 지켰다. 1886년 한불조약으로 박해가 끝난 뒤에도 은근한 냉대가 이어지자, 1894년부터 1900년까지 그는 스스로 바위에 교황과 주교, 사제와 신자들을 위한 기도를 새겼다. 오랫동안 나무에 가려 잊혔던 이 비석은 1945년 광복 후 손자에 의해 다시 세상에 드러났고, 2009년 경상북도 문화재자료 제562호로 지정되었다.', '김삼록 도미니코가 1894~1900년 직접 새긴 한국 유일의 신앙고백비. 2009년 경북 문화재자료 제562호 지정.', '상주 신앙 고백비 - 바위에 새긴 믿음', '경북 상주 신앙고백비, 김삼록 도미니코가 직접 바위에 새긴 한국 유일의 신앙고백비. 2009년 경북 문화재자료 지정.', '감사', NULL, NULL),
  ('여우목 성지', '순교성지', '안동', '경북', '경상북도 문경시 문경읍 중평리 96', '문경 조령 관문 인근, 서울로 향하던 나그네들의 옛 고갯길에 자리한 교우촌 터. 1839년 기해박해 무렵 상주에서 피신해 온 이윤일 요한 일가와 청풍에서 넘어온 서치보 요셉 일가가 이곳에 정착했다. 이윤일은 전교회장으로 활동하며 서른 명 가까운 신자를 이끄는 공동체를 일구었으나, 서치보의 아들들과 이윤일 자신도 병인박해 때 순교했다. 이윤일 요한은 1867년 1월 대구 관덕정에서 참수형으로 순교, 103위 성인 중 영남 유일의 성인이 되었다. 1999년 유해를 이장하고 2002년 성지로 조성되었다.', '성 이윤일 요한(103위 성인)이 이끈 교우촌 터. 1867년 대구 관덕정에서 순교. 1999년 유해 이장, 2002년 성지 조성.', '여우목 성지 - 영남의 성인 이윤일이 일군 교우촌', '경북 문경 여우목성지, 103위 성인 중 영남 유일 성인 이윤일 요한이 이끈 교우촌 터.', '새출발', NULL, NULL),
  ('우곡 성지', '순례길', '안동', '경북', '경상북도 봉화군 봉성면 우곡리 151-2', '봉화 산골, 한국천주교 첫 은수자의 후손들이 잠들어 있는 안식처. 홍유한은 서울 명문가에서 태어나 어려서부터 학문에 재능을 보였으나 벼슬길 대신 성호 이익 문하에서 실학을 공부했다. 1750년 무렵 천주실의 등 서학서를 접하고 유교와 불교에서 찾지 못한 깊이를 발견한 그는, 1757년 예산으로, 1775년에는 영주 소백산 아래 구고리로 옮겨가 18년 넘게 금욕적인 신앙생활을 이어갔다. 그의 사후 후손 13명이 순교자가 되었고 그중 홍병주 베드로, 홍영주 바오로 두 사람은 103위 성인으로 시성되었다.', '한국 첫 은수자 홍유한(1726~1785)의 후손들이 안장된 곳. 후손 13명 순교, 그중 2명 성인 시성.', '우곡 성지 - 홍유한 가문의 신앙 안식처', '경북 봉화 우곡성지, 한국 첫 은수자 홍유한의 후손들이 잠든 곳. 13명의 순교자를 낳은 신앙 명가의 안식처.', '위로', NULL, NULL),
  ('진안리 성지', '순례길', '안동', '경북', '경상북도 문경시 문경읍 진안리 92-6', '문경새재 조령, 영남과 한양을 잇던 옛 관문 길목에 자리한 자리. 한국 두 번째 사제 최양업 토마스 신부가 사목 활동을 보고하러 가던 길에 병을 얻은 곳으로 전해진다. 충청도에서 순교자의 아들로 태어난 그는 1836년 한국 최초의 신학생이 되어 마카오에서 김대건 신부와 동문수학했고, 1849년 상해에서 사제품을 받아 12년 가까이 다섯 개 도를 돌며 사목했다. 1860년 경신박해 때는 죽림굴에 숨어 지내기도 했던 그는 1861년 6월 15일 과로와 장티푸스로 마흔의 나이에 눈을 감았다.', '한국 두 번째 사제 최양업 신부가 사목 중 병을 얻은 곳. 조령 관문 길목의 옛 선교 경로.', '진안리 성지 - 최양업 신부의 마지막 여정', '경북 문경 진안리성지, 최양업 신부가 사목길에 병을 얻은 조령 관문 길목의 성지.', '위로', NULL, NULL),
  ('한실 교우촌', '교우촌', '안동', '경북', '경상북도 문경시 마성면 상내리 999', '문경 산속 깊은 골짜기, 자연 요새와도 같은 지형 덕에 신자들의 은신처가 되었던 마을. 1801년 신유박해 때 서유도 일가가 이곳 한실 잣골로 피신해 온 것이 교우촌의 시작이다. 병인박해 무렵에는 갈레 신부가 여러 교우촌을 오가며 사목하는 거점이 되었으나, 1866년 박해 때 신자 15명가량이 체포되어 순교했다. 그중 김예기·김인기 회장 형제는 1867년 1월 21일 대구에서 함께 처형되었다.', '1801년 서유도 일가가 피신해 형성된 교우촌. 1866년 병인박해 때 15명가량 순교, 김예기·김인기 형제도 포함.', '한실 교우촌 - 산속 자연 요새의 신앙', '경북 문경 한실교우촌, 신유박해 피난민들이 세운 산중 교우촌. 김예기·김인기 형제 등이 순교한 자리.', '평온', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('김범우 순교자 성지', '순교성지', '부산', '경남', '경상남도 밀양시 삼랑진읍 용전리 205-1', '밀양 삼랑진 낙동강변, 한국천주교 최초의 증거자로 불리는 이의 무덤이 1989년에야 세상에 다시 드러났다. 김범우 토마스는 명례방에서 열리던 신앙 모임의 집주인으로, 1785년 을사추조적발사건으로 발각되어 유배형을 받았다. 오랫동안 그의 유배지는 충청도 단양으로 알려져 왔지만, 후손과 연구자들의 노력으로 실제로는 이곳 밀양이었음이 밝혀졌다. 부산교구 순교자현양위원회가 주변 부지를 매입해 성역화하여, 2005년 야외 제대와 십자가의 길을, 2011년 성모동굴경당을, 2017년에는 교육관과 피정의 집을 세웠다.', '한국 최초의 증거자 김범우 토마스(1751~1786/87)의 유배지이자 묘소. 1989년 묘소 발견, 부산교구가 성역화.', '김범우 순교자 성지 - 최초의 증거자, 되찾은 무덤', '경남 밀양 김범우순교자성지, 한국 최초의 증거자 김범우 토마스의 유배지이자 1989년 되찾은 무덤.', '위로', NULL, NULL),
  ('살티 공소', '교우촌', '부산', '울산', '울산시 울주군 상북면 덕현리 1144-4', '울주 상북면 산길, 호랑이가 출몰하던 깊은 숲이 오히려 신자들의 은신처가 되어준 자리. 관헌들이 신자를 쫓다가도 석남사에 이르면 경주 쪽으로 돌아서곤 해, 살 수 있는 땅이라는 뜻에서 살티라는 이름을 얻었다. 인근 간월과 대재의 공소가 박해로 무너진 뒤 1868년 세워진 이 공소는 부산교구에서 가장 오래된 공소로 남아있다. 이후 최재선 주교를 비롯해 여러 성직자와 수도자를 배출한 성소의 못자리가 되었다.', '1868년 설립된 부산교구 최고(最古)의 공소. 병인박해 피신 신자들의 은신처, 다수의 성직자 배출.', '살티 공소 - 살 수 있었던 산속 은신처', '울산 울주군 살티공소, 병인박해 신자들의 산중 은신처였던 부산교구 최고(最古)의 공소.', '평온', NULL, NULL),
  ('수영 장대 순교성지', '순교성지', '부산', '부산', '부산시 수영구 광안 4동 546-4', '부산 수영구, 조선 수군 좌수영이 있던 자리에 군사 지휘대인 장대가 있었다. 1868년 병인박해 말기, 쉰아홉의 나이에 회장이 된 옛 무관 이정식 요한이 아들 이월주 프란치스코, 며느리 박조이 마리아 등 가족과 함께 이곳에서 군문효수형으로 처형되었다. 함께 순교한 여덟 명 중 이정식과 양재현 마르티노는 2014년 프란치스코 교황 방한 때 시복되었다. 1988년 현양비가 세워졌고, 2004년 대형 십자가와 14처 십자가의 길, 순교자 위패가 마련되었다.', '1868년 병인박해 때 이정식 요한 일가 등 8명이 처형된 좌수영 장대터. 2014년 이정식·양재현 시복.', '수영 장대 순교성지 - 좌수영에 새겨진 여덟 순교', '부산 수영구, 1868년 이정식 요한 일가 등 8명이 순교한 좌수영 장대터. 2014년 시복된 순교자들의 자리.', '치유', NULL, NULL),
  ('언양 성당', '성당', '부산', '울산', '울산시 울주군 언양읍 송대리 422', '울산 언양, 부산교구에서 유일하게 화강석으로 지어진 고딕 성당이 지역 화강암 언덕을 배경으로 서 있다. 경남 최초의 공소인 내간월 불당골 공소에서 시작된 이 지역 신앙은 병인박해의 혹독한 시련을 딛고 1926년 정식 본당으로 세워졌다. 보드뱅 신부가 직접 설계해 1929년 착공, 1936년 완공한 성당 돌 하나하나에는 지역 신자들의 정성이 깃들어 있다. 이 작은 본당에서 훗날 70여 명의 사제·수도자와 20여 명의 동정녀가 배출되었다.', '1926년 설립, 1936년 완공된 부산교구 유일의 석조 고딕 성당. 경남 최초 공소(내간월 불당골)에서 이어진 신앙 공동체.', '언양 성당 - 화강암에 새긴 신앙', '울산 언양성당, 1936년 완공된 부산교구 유일의 석조 고딕 성당. 70여 명의 성직자를 배출한 성소의 못자리.', '감사', NULL, NULL),
  ('오륜대 순교자 성지', '순교성지', '부산', '부산', '부산시 금정구 부곡 3동 1-4', '부산 금정구 오륜대, 박물관 건물을 지나 언덕에 오르면 이정식 요한, 양재현 마르티노 등 부산 지역 순교자 8위가 잠든 묘역과 십자가의 길, 로사리오 기도동산이 이어진다. 경내 순교자 성당에는 성 김대건 안드레아 신부가 조선으로 향할 때 탔던 라파엘호의 복원 모형과 함께, 한국 103위 순교성인 중 26위의 유해가 모셔져 있다. 박물관 관람에 더해 묘역과 성당을 함께 순례하면 부산·울산 지역 신앙사를 한 자리에서 만날 수 있다.', '부산 지역 순교자 8위(이정식·양재현 등)의 묘역과 103위 성인 중 26위의 유해가 봉안된 순교자 성당.', '오륜대 순교자 성지 - 26위 성인의 유해가 모인 언덕', '부산 금정구 오륜대, 부산 지역 순교자 묘역과 103위 성인 중 26위 유해가 모셔진 순교자 성당.', '치유', NULL, NULL),
  ('울산 병영 순교성지', '순교성지', '부산', '울산', '울산시 중구 남외동 569', '울산 중구 병영, 군사들이 주둔하던 병영성 자리에 순교의 기억이 새겨져 있다. 1860년 경신박해 때 언양 출신 양반 오치문이 백지사형으로 처형되며 이 땅 첫 순교자가 되었다. 1868년 병인박해 말에는 산골 교우촌에 숨어 지내던 허인백 야고보, 김종륜 루카, 이양등 베드로 세 사람이 경주에서 붙잡혀 고문받은 뒤 이곳 병영으로 옮겨져 9월 14일 참수되었다. 세 사람의 유해는 1973년 대구 복자성당으로 이장되었고, 2014년 프란치스코 교황 방한 때 나란히 시복되었다.', '1860년 오치문, 1868년 허인백·김종륜·이양등 3위가 순교한 병영성 옛터. 2014년 3위 시복.', '울산 병영 순교성지 - 병영성에 새겨진 순교', '울산 중구 병영성지, 1868년 허인백·김종륜·이양등 3위가 순교한 자리. 2014년 시복된 순교자들의 흔적.', '치유', NULL, NULL),
  ('조씨 형제 순교자 묘', '순교성지', '부산', '부산', '부산광역시 강서구 생곡동 272', '부산 강서구 생곡동, 성품도 나이도 사뭇 달랐던 두 형제가 나란히 잠들어 있다. 창녕 조씨 김해 문중 출신인 조석빈과 조석증 형제는 양반 신분으로 천주교를 받아들여 은밀히 한글 교리서를 품고 다니며 유학과 서학을 비교하며 공부했다. 1868년 가락면에서 체포된 두 사람은 혹독한 고문에도 신앙을 버리지 않았다. 동생 조석증은 형의 순교 소식에 "형님 목에 십자가 꽃이 피었다"며 오히려 기뻐하고 자신의 처형을 자청했다고 전해진다. 두 형제는 김해 왜장대에서 참수되었으나 순교자라는 이유로 선산에 묻히지 못하고, 백씨 문중 어른의 도움으로 인근 밭에 몰래 묻혔다.', '조석빈·조석증 형제(1868년 순교)의 묘소. 순교 후 선산 매장을 거부당해 인근에 비밀리 안장.', '조씨 형제 순교자 묘 - 형제가 함께 지킨 신앙', '부산 강서구, 1868년 순교한 조석빈·조석증 형제의 묘소. 신앙으로 맺어진 형제애의 자리.', '위로', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('대산 성당 복자 구한선 타대오 성지', '순교성지', '마산', '경남', '경상남도 함안군 대산면 구혜리 246-3', '함안 대산면 민바위골, 열여섯의 소년이 매질 속에서도 신앙을 지킨 자리에 성당이 서 있다. 지적인 집안에서 태어난 구한선 타대오는 우연히 천주교를 접해 다블뤼 주교에게 세례를 받았고, 병인박해 전에는 리델 신부를 보좌해 거제 지역까지 함께 다녔다. 1866년 체포된 그는 배교 대신 교리를 직접 써서 관장 부인에게 전했다가 더 혹독한 매질을 당했고, 풀려난 지 이레 만에 그 후유증으로 숨을 거두었다. 1959년 발견되어 1976년 이장된 그의 유해는 2014년 프란치스코 교황 방한 때 시복되었고, 2016년 대산성당으로 옮겨졌다.', '복자 구한선 타대오(1844~1866)의 순교와 유해 안치지. 2014년 시복, 2016년 대산성당으로 유해 이전.', '대산 성당 - 열여섯 순교자 구한선의 자리', '경남 함안 대산성당, 복자 구한선 타대오의 순교와 유해가 모셔진 성지. 2014년 시복.', '위로', NULL, NULL),
  ('명례 성지', '순교성지', '마산', '경남', '경상남도 밀양시 하남읍 명례리 1122', '밀양 낙동강변, 마산교구 신앙의 고향으로 불리는 자리. 1897년 이 지역 첫 본당이 세워졌고, 1828년에는 훗날 순교하게 될 복자 신석복 마르코가 이곳에서 태어났다. 소금과 누룩 장사를 하던 신석복은 1866년 병인박해 때 체포되어 대구에서 뼈가 부러지도록 고문받으면서도 신앙을 버리지 않고 1866년 3월 31일 서른여덟의 나이로 교수형에 처해졌다. 한국인 세 번째 사제 강성삼 라우렌시오 신부가 초대 본당 신부로 사목하다 1903년 이곳에서 선종하기도 했다. 2011년 국가등록문화재 제526호로 지정된 이 자리에 2018년 신석복 마르코 기념성당이 봉헌되었다.', '마산교구 신앙의 발상지. 복자 신석복 마르코(1828~1866)의 고향이자 순교 연고지. 국가등록문화재 제526호.', '명례 성지 - 마산교구 신앙의 고향', '경남 밀양 명례성지, 마산교구 첫 본당터이자 복자 신석복 마르코의 고향. 국가등록문화재 제526호.', '감사', NULL, NULL),
  ('복자 박대식 빅토리노 묘', '순교성지', '마산', '경남', '경상남도 김해시 진례면 청천리 산30 (책골)', '김해 진례면 산기슭, 부유한 집안에서 태어나 가족과 함께 신앙을 키워가던 이가 잠들어 있다. 박대식 빅토리노는 1868년 병인박해 때 조카 박수연과 함께 체포되어 대구로 압송되었다. 뼈가 부러지고 몸이 뒤틀리는 혹독한 고문에도 신앙을 버리지 않았던 그는 그해 10월 12일 관덕정에서 참수되어 순교했다. 순교자라는 이유로 선산에 묻히지 못한 유해는 아들과 친척들이 몰래 유씨 문중 산에 평장으로 모셨고, 1956년 봉분을 넓히고 1966년 표석을 세웠다. 2001년 세례명 빅토리노가 확인되었고, 2014년 시복되었다.', '복자 박대식 빅토리노(1812~1868)의 묘소. 1868년 대구 관덕정에서 순교, 2014년 시복.', '복자 박대식 빅토리노 묘 - 몰래 지킨 순교자의 안식', '경남 김해 박대식 빅토리노 묘, 1868년 관덕정에서 순교한 복자의 무덤. 2014년 시복.', '위로', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('경주 관아와 옥 터', '역사사적지', '대구대', '경북', '경상북도 경주시 동부동 일대 (옛 경주읍성 옥터)', '경주 시내, 아파트 단지 사이 작은 공원 한쪽에 옛 경주읍성 옥터였음을 알리는 표지석이 서 있다. 조선시대 이곳 관아 옥에는 병인박해 무렵 산속 동굴에 숨어 신앙을 지키던 허인백 야고보, 김종륜 루카, 이양등 베드로가 붙잡혀 온 뒤 혹독한 문초를 받았다. 세 사람은 이곳에서 고문당한 뒤 울산 병영으로 옮겨져 처형되었다. 도시화로 옛 관아 건물은 모두 사라졌지만, 표지석 하나가 이 자리에 있었던 신앙의 시련을 오늘도 전하고 있다.', '병인박해 때 허인백·김종륜·이양등이 문초받은 경주읍성 옥터. 현재는 아파트 단지 내 표지석만 남아있다.', '경주 관아와 옥 터 - 도심 속에 남은 표지석', '경북 경주, 병인박해 순교자들이 문초받은 경주읍성 옥터. 아파트 단지 사이 표지석에 남은 신앙의 기억.', '위로', NULL, NULL),
  ('구룡 공소', '교우촌', '대구대', '경북', '경상북도 청도군 운문면 방음리 (구룡산)', '청도·영천·경산의 경계, 하늘 아래 첫 동네라 불릴 만큼 첩첩산중인 구룡산 자락에 자리한 공소. 병인박해 때 간월에서 체포되었다가 풀려난 살티의 김영제 베드로가 이곳 자인골로 옮겨와 신앙 공동체를 이루었다. 1887년 로베르 신부의 사목 보고서에는 이 공소에 60명의 신자가 있었다고 기록되어 있으며, 1921년에는 드망즈 주교가 성모 성당으로 축복했다. 200여 년 공소의 역사와 부속건물의 가치를 인정받아 2018년 대구대교구와 지역 성당이 함께 신앙유적지로 축복식을 가졌다.', '병인박해 피신 신자들이 세운 산중 공소. 1887년 신자 60명 기록, 2018년 신앙유적지로 선포.', '구룡 공소 - 하늘 아래 첫 동네의 신앙', '경북 청도 구룡공소, 병인박해 피신 신자들이 산속에 일군 200년 신앙 공동체. 2018년 신앙유적지 선포.', '평온', NULL, NULL),
  ('김수환 추기경 사랑과 나눔 공원', '역사사적지', '대구대', '경북', '대구광역시 군위군 군위읍 용대리 238-10', '군위 산골 마을, 한국 최초의 추기경이 태어난 생가 터에 사랑과 나눔의 정신을 기리는 공원이 조성되었다. 2012년부터 6년에 걸친 공사 끝에 2018년 문을 연 이곳은 김수환 추기경의 생애를 담은 기념관과 경당, 옛집과 옹기 가마, 추모정원, 십자가의 길을 갖추고 있다. 기념관 내부는 그의 아호인 옹기를 주제로 꾸며졌고 천장은 십자가 모양의 조명으로 장식되었다. 평생 낮은 자리에서 나눔을 실천한 추기경의 발자취를 따라 걷는 평화의 숲길이 인상적이다.', '故 김수환 추기경(1922~2009)의 생가 터에 조성된 기념공원. 2012~2018년 조성, 대구대교구 관리.', '김수환 추기경 사랑과 나눔 공원 - 옹기의 정신을 담다', '대구 군위 김수환 추기경 사랑과 나눔공원, 추기경의 생가 터에 조성된 기념관과 나눔의 숲길.', '감사', NULL, NULL),
  ('김천 황금성당', '성당', '대구대', '경북', '경상북도 김천시 황금동', '김천 황금동 자라밭골, 병인박해 때 충청·전라 신자들이 소백산맥을 넘어 피난 온 산악 지대에 자리한 본당. 1901년 김성학 신부가 초가 한 채를 사들여 김천본당을 세운 것이 시작으로, 이 지역 순교자 유 시몬과 이름을 남기지 못한 동료 순교자 4명의 신앙을 이어받고자 했다. 계산성당, 가실성당에 이어 대구대교구에서 세 번째로 지어진 유서 깊은 본당으로, 2000년 새 성전을 지으면서도 70년 된 옛 성당 건물을 허물지 않고 나란히 남겨 고풍스러움과 현대미가 함께 어우러진다.', '1901년 설립된 김천 지역 첫 본당, 대구대교구에서 세 번째로 지어진 성당. 병인박해 순교자 유 시몬 등을 기림.', '김천 황금성당 - 옛 성당과 새 성당이 나란히', '경북 김천 황금성당, 1901년 설립된 대구대교구 세 번째 본당. 옛 성전과 새 성전이 함께 남은 고풍스러운 순례지.', '감사', NULL, NULL),
  ('복자 성당', '순교성지', '대구대', '대구', '대구광역시 동구 송라로 22', '대구 동구, 병인박해가 저물어가던 1868년 순교한 세 사람을 기리는 성당이 서 있다. 김해 출신 허인백 야고보, 공주 출신 김종륜 루카, 서울 출신 이양등 베드로는 각지에서 박해를 피해 경상도 교우촌으로 숨어들었다가 단석산 굴에 은신한 채로 붙잡혔다. 50리 길을 끌려가 울산에서 9월 14일 참수된 이들의 유해는 1973년 이 성당에 모셔졌다. 병인박해 100주년을 기려 1970년 세워진 이 성당은 순교 신심의 중심지가 되었고, 2014년 세 사람 모두 시복되었다.', '허인백·김종륜·이양등 3위의 유해가 1973년 봉안된 성당. 1970년 병인박해 100주년 기념 설립. 2014년 3위 시복.', '복자 성당 - 세 순교자의 유해가 잠든 곳', '대구 동구 복자성당, 1868년 순교한 허인백·김종륜·이양등 3위의 유해가 모셔진 순교 신심의 중심지.', '치유', NULL, NULL),
  ('비산 성당', '성당', '대구대', '대구', '대구광역시 서구 비산동', '대구에서 가장 먼저 로마 가톨릭 신앙이 전해진 마을, 비산(날뫼)에 자리한 성당. 1829년 무렵부터 이미 신자들이 살고 있었다는 이 마을에는 1909년 신자 송기택이 자신의 집을 희사하고 신자들이 모은 성금으로 수리해 공소가 세워졌다. 대구대교구 설정 이후 신자가 늘면서 1927년 대구에서 세 번째 본당으로 승격했고, 1931년 남산본당의 명도회관 건물을 옮겨와 골격으로 삼아 1958년 지금의 성전을 축성했다. 벽화로도 유명한 이 성당은 대구 서구의 역사 명소로 꼽힌다.', '대구 최초 신앙 전파지 비산(날뫼) 마을에 1927년 승격된 대구 세 번째 본당. 1958년 현 성전 축성.', '비산 성당 - 대구 첫 신앙이 뿌리내린 날뫼', '대구 서구 비산성당(날뫼성당), 대구에서 가장 먼저 가톨릭 신앙이 전해진 마을에 세워진 본당.', '감사', NULL, NULL),
  ('새방골 성당', '성당', '대구대', '대구', '대구광역시 서구 새방동 일대', '대구 서구, 공단 개발로 철거 위기를 겪기도 한 영남 선교의 요람. 1886년 한불조약 체결 이후 경상도 전교를 맡게 된 김보록(로베르트) 신부가 1888년 겨울 이곳에 임시 성당을 꾸미고 은신하며 전교 활동을 펼쳤다. 계산성당의 전신이 되는 유서 깊은 자리로, 100여 년 전 신자들이 기도하던 14처가 지금도 보존되어 있어 옛 신앙 선조들의 자취를 더듬으려는 순례객의 발길이 이어진다.', '1888년 김보록 신부가 은신 전교를 펼친 계산성당의 전신. 100여 년 된 14처가 보존된 영남 선교의 요람.', '새방골 성당 - 계산성당의 뿌리가 된 은신 전교지', '대구 서구 새방골성당, 김보록 신부가 은신 전교를 펼친 계산성당의 전신. 100년 된 14처가 남은 성지.', '평온', NULL, NULL),
  ('성 유스티노 신학교', '역사사적지', '대구대', '대구', '대구광역시 중구 남산동', '대구 남산동, 대구대교구 첫 신학교가 있던 자리. 1911년 대구 지목구가 설정되자 드망즈 주교는 신학교 설립을 다짐했고, 1912년 후원자의 조건부 기부로 성 유스티노라는 이름을 얻어 1913년 공사를 시작해 1914년 문을 열었다. 서울 용산신학교에서 옮겨온 17명을 포함해 57명의 학생으로 출발한 이 학교는 1918년 첫 사제 주재용 신부를 배출한 이래 67명의 사제를 길러냈다. 일제의 탄압으로 1945년 문을 닫았다가, 1982년 선목신학교로 다시 문을 열어 오늘날 대구가톨릭대학교 신학대학으로 이어지고 있다.', '1914년 개교한 대구 최초의 신학교, 67명의 사제를 배출. 1945년 폐교 후 1982년 재개교, 현 대구가톨릭대 신학대학의 전신.', '성 유스티노 신학교 - 영남 사제 성소의 못자리', '대구 남산동, 1914년 개교한 대구 최초의 신학교 터. 67명의 사제를 배출한 영남 성소의 요람.', '감사', NULL, NULL),
  ('성모당·성직자 묘지', '성당', '대구대', '대구', '대구광역시 중구 남산동 (대구대교구청 내)', '대구대교구청 경내, 프랑스 루르드 동굴을 그대로 옮겨온 듯한 성모동굴이 백 년 넘게 순례객을 맞고 있다. 대구대교구 초대 교구장 드망즈 주교는 교구 발전을 위한 세 가지 소원이 이뤄지면 루르드 성모동굴을 짓겠다고 서원했는데, 한 신부가 기적적으로 병을 회복하자 이를 계기로 공사를 서둘러 1918년 10월 13일 축성되었다. 동굴 안에는 전통 도상을 따른 성모상이 모셔져 있고, "1911 EX VOTO IMMACULATAE CONCEPTIONI 1918"이라는 문구가 교구 설정(1911년)과 서원 성취(1918년)를 함께 새기고 있다. 기도하는 이들의 발길이 사시사철 끊이지 않는 치유와 회복의 자리다.', '드망즈 주교의 서원으로 1918년 축성된 프랑스 루르드 성모동굴의 복제. 대구대교구청 내 대표 기도처.', '성모당 - 루르드를 옮겨온 백 년의 기도처', '대구대교구청 성모당, 1918년 축성된 루르드 성모동굴 복제. 치유와 회복을 구하는 순례객의 발길이 이어지는 곳.', '치유', NULL, NULL),
  ('신나무골 성지', '순교성지', '대구대', '경북', '경상북도 칠곡군 지천면 연화리 20', '칠곡, 영남 선교의 요람이라 불리는 이곳에 순교자 이선이 엘리사벳의 묘가 자리한다. 1815년 을해박해 무렵부터 신앙 공동체가 형성된 이 자리는 샤스탕, 다블뤼, 최양업, 로베르 신부 등이 거쳐 간 선교 거점이었다. 1882년부터 로베르(김보록) 신부가 본격적으로 전교 활동을 넓혀 1886년 대구 첫 본당을 세웠고 1898년에는 십자가 모양의 한옥 성당을 지었다. 1860년 경신박해 때 한티로 피신하던 중 붙잡힌 이선이 엘리사벳과 큰아들 배도령 스테파노는 죽어도 신앙을 지키겠다며 그 자리에서 참수당했다.', '을해박해(1815) 이후 형성된 영남 선교의 요람. 1860년 경신박해 때 이선이 엘리사벳 모자가 순교.', '신나무골 성지 - 영남 선교의 요람', '경북 칠곡 신나무골성지, 대구 첫 본당의 뿌리이자 이선이 엘리사벳 모자가 순교한 영남 선교의 요람.', '위로', NULL, NULL),
  ('진목정', '순교성지', '대구대', '경북', '경상북도 경주시 산내면 수의길 192', '경주 산내면, 바위굴에 몸을 숨긴 채 신앙을 지키던 세 신자의 이야기가 전해지는 산골. 김해 출신 허인백 야고보, 공주 출신 김종륜 루카, 서울 출신 이양등 베드로는 1868년 이 범굴에 숨어 지내다 발각되어 체포되었고, 혹독한 고문 끝에 그해 9월 14일 울산 병영에서 참수되었다. 오늘날 이곳에는 세 순교자가 숨어 지내던 범굴과 2017년 세워진 기념경당, 피정의 집, 십자가의 길, 진목 공소가 자리해 순교자들의 마지막 은신처를 기리고 있다.', '허인백·김종륜·이양등 3위가 은신하다 체포된 범굴이 있는 자리. 1868년 울산 병영에서 순교, 2014년 시복.', '진목정 성지 - 범굴에 숨은 세 순교자', '경북 경주 진목정성지, 병인박해 순교자 3위가 은신했던 범굴과 기념경당이 있는 산골 성지.', '치유', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('강경 성당', '성당', '대전', '충남', '충청남도 논산시 강경읍 중앙리 228', '논산 강경, 금강 포구를 낀 이 마을은 김대건 신부가 조선 땅에서 첫 사목을 시작한 자리다. 1845년 10월 12일 페레올 주교와 다블뤼 신부, 김대건 신부 일행이 강경포에 배를 대고 상륙해, 신자 구순오의 집에 한 달가량 머물며 사목 활동을 폈다. 주교는 두 달 넘게 은신하며 조선대목구장으로서 첫 임무를 수행했다. 1961년 완공된 지금의 성당은 첨두형 아치와 근대적 공법이 어우러진 건축으로 2015년 국가등록문화재 제650호로 지정되었고, 2019년에는 김대건 신부가 서품받은 상해 성당을 본뜬 기념관이 더해졌다.', '1845년 김대건 신부·페레올 주교 일행이 상륙해 첫 사목을 시작한 자리. 1961년 완공 성당은 국가등록문화재 제650호.', '강경 성당 - 김대건 신부 첫 사목의 포구', '충남 논산 강경성당, 1845년 김대건 신부와 페레올 주교가 상륙해 첫 사목을 시작한 자리. 국가등록문화재 제650호.', '새출발', NULL, NULL),
  ('남방제 성지', '순교성지', '대전', '충남', '충청남도 아산시 신창면 남성리 412-3', '아산 신창면, ㄱ자로 굽은 둑에서 이름을 딴 마을에 200년 넘은 버드나무가 옛 정착의 세월을 증언한다. 이곳 출신 조화서 베드로는 아버지가 기해박해로 순교한 뒤 이 마을로 피신해 최양업 토마스 신부의 마부이자 복사로 전국 사목 여정을 도왔다. 그의 아들 조윤호 요셉은 깊은 신심으로 살다 1866년 아버지와 함께 체포되었을 때 회유에도 흔들리지 않고 순교의 길을 택했다. 두 부자는 그해 12월 13일 전주에서 순교했다. 2016년 순교 150주년을 맞아 두 부자와 신창 지역 순교자 36위를 기리는 원뿔형 기념비가 세워졌다.', '성 조화서 베드로·조윤호 요셉 부자가 자란 마을. 1866년 전주에서 부자가 함께 순교. 2016년 순교 150주년 기념비 건립.', '남방제 성지 - 조화서·조윤호 부자의 신앙 마을', '충남 아산 남방제성지, 성 조화서 베드로와 아들 조윤호 요셉이 자란 마을. 1866년 부자가 함께 순교한 자리.', '위로', NULL, NULL),
  ('다락골 성지', '순례길', '대전', '충남', '충청남도 청양군 화성면 농암리 676-1', '청양 화성면 산골, 땀의 순교자로 불리는 최양업 토마스 신부와 그 아버지 최경환 프란치스코 성인이 태어난 고향. 1791년 최인주가 박해를 피해 이 외진 산골에 정착하며 형성된 초기 교우촌 중 하나다. 최경환 성인은 1839년 기해박해 때 고문 후유증으로 옥사했고 부인 이성례 마리아도 이듬해 순교했다. 구전에 따르면 1866년 병인박해 때 홍주 관아에서 순교한 이들의 유해가 밤을 틈타 몰래 이곳에 묻혔다고 한다. 이름 없는 순교자들의 줄무덤 앞에 2008년 기념경당이, 2019년에는 최양업 신부를 기리는 성지박물관이 세워졌다.', '최경환 프란치스코·최양업 토마스 신부 부자의 고향. 1791년부터 형성된 초기 교우촌. 2019년 성지박물관 개관.', '다락골 성지 - 땀의 순교자 최양업의 고향', '충남 청양 다락골성지, 최양업 신부와 부친 최경환 성인의 고향. 이름 없는 순교자들의 줄무덤이 남은 초기 교우촌.', '위로', NULL, NULL),
  ('대흥 봉수산 순교 성지', '순교성지', '대전', '충남', '충청남도 예산군 대흥면 동서리 105-3 (대흥 동헌 옆)', '예산 대흥면 옛 관아 터 옆, 조선시대 형옥을 재현한 형옥원이 서 있다. 이곳에서 1801년 신유박해 때 복자 김정득 베드로와 그의 사촌 김광옥 안드레아가 형제처럼 신앙을 나누다 나란히 체포되었다. 관장은 조상 제사를 폐하지 않으면 살려주겠다 했으나 두 사람은 산속에 숨어서라도 하느님의 말씀을 전하겠다며 신앙을 굽히지 않았다. 각각 대흥과 예안에서 따로 처형되기 직전, 두 사람은 손을 맞잡고 "내일 낮에 하늘에서 다시 만나자"는 말을 남기고 1801년 음력 7월 17일 함께 순교했다. 2014년 프란치스코 교황 방한 때 두 사람 모두 시복되었다.', '복자 김정득 베드로와 사촌 김광옥 안드레아가 1801년 신유박해 때 각각 처형된 자리. 옛 대흥 관아 옥터 재현. 2014년 시복.', '대흥 봉수산 순교 성지 - 손을 맞잡은 사촌 형제', '충남 예산 대흥봉수산순교성지, 복자 김정득·김광옥 사촌 형제가 1801년 순교한 대흥 관아 옥터.', '위로', NULL, NULL),
  ('덕산 순교 성지', '순교성지', '대전', '충남', '충청남도 예산군 덕산면 상가리 일대', '예산 덕산면, 흥선대원군의 아버지 남연군의 묘가 있는 가야산 자락. 1868년 5월 독일 상인 오페르트가 통상을 요구하며 이 묘를 도굴하려다 실패한 사건이 벌어졌고, 이는 대원군에게 서양 세력과 천주교에 대한 경계심을 굳히게 하여 병인박해를 한층 가혹하게 몰아붙이는 계기가 되었다. 이 여파로 덕산 일대에서도 적잖은 신자들이 붙잡혀 순교했다고 전해진다. 오늘날 성지에는 이름 없는 순교자들과 신앙 선조들의 유해가 함께 모셔져 있어, 한 사건이 어떻게 박해의 불길을 키웠는지를 돌아보게 한다.', '1868년 오페르트 남연군 묘 도굴 사건의 현장 인근으로, 이 사건이 병인박해를 격화시키는 계기가 되었다. 덕산 일대 무명 순교자들의 유해가 안장되어 있다.', '덕산 순교 성지 - 박해를 키운 도굴 사건의 땅', '충남 예산 덕산순교성지, 1868년 오페르트 도굴 사건으로 병인박해가 격화된 가야산 자락의 순교지.', '위로', NULL, NULL),
  ('도앙골 성지', '순례길', '대전', '충남', '충청남도 부여군 내산면 금지리 249', '부여 내산면, 복숭아나무가 많아 도원곡이라 불리던 골짜기에 이존창 루도비코의 전교로 교우촌이 형성되었다. 한국 두 번째 사제 최양업 토마스 신부는 1850년 이곳에서 아홉 달간의 사목 활동을 보고하며 "교우촌 신자들의 처참한 가난을 자주 목격한다. 가족과 이웃에게서조차 세금과 박해에 시달린다"고 적었다. 1866년 병인박해 때는 오 요한, 김술장 요한 등이 갈매못에서 순교했다. 2011년 기도의 집이 축복되었고, 같은 해 12월 최양업 신부 시복을 기념하는 비가 세워졌다. 인근 삽티 성지까지 옛 박해 시대의 길을 되살린 도보 순례길로 이어진다.', '최양업 신부가 1850년 아홉 달의 사목보고서를 남긴 교우촌. 1866년 병인박해 때 오 요한 등이 갈매못에서 순교.', '도앙골 성지 - 최양업 신부의 사목 보고서', '충남 부여 도앙골성지, 최양업 신부가 사목 활동을 보고한 교우촌 터. 삽티 성지로 이어지는 도보 순례길.', '평온', NULL, NULL),
  ('배나드리 성지', '순교성지', '대전', '충남', '충청남도 예산군 삽교읍 용동리 270-23', '예산 삽교천변, 홍수 때마다 배를 타고 건너야 했던 지형에서 이름을 얻은 마을. 양반가에서 태어난 인언민 마르티노는 황사영과의 인연으로 천주교를 접해 서울에서 주문모 신부에게 세례를 받았다. 1797년 정사박해 때 공주에서 체포되어 청주에서 문초받고 해미로 이송된 그는 1800년 1월 9일 예순셋의 나이로 매를 맞아 순교했다. 1817년에는 해미 관아가 이 마을을 급습해 20~30명의 신자를 체포했는데, 민참지 베드로와 그의 형수 안나 등은 배교 대신 옥중 순교를 택했다. 2014년 인언민 마르티노가 123위와 함께 시복되었다.', '복자 인언민 마르티노(1737~1800)의 순교 연고지. 1817년 해미 관아의 급습으로 다수 순교. 2014년 시복.', '배나드리 성지 - 물길 건너 지킨 신앙', '충남 예산 배나드리성지, 복자 인언민 마르티노와 1817년 순교자들의 자취가 남은 삽교천변 신앙 마을.', '위로', NULL, NULL),
  ('산막골·작은재 성지', '순교성지', '대전', '충남', '충청남도 서천군 판교면 금덕리 236 (산막골)', '서천 판교면, 1839년 기해박해 이후 신앙 선조들이 산속 깊이 숨어들었던 피난처. 다블뤼 주교와 페롱 신부가 이곳을 사목 거점으로 삼았고, 성 황석두 루카는 병인박해 전 십여 년을 이 골짜기에서 속죄와 보속의 삶으로 지냈다. 이름 없는 신자들의 떼무덤도 곳곳에 남아있었지만, 1994년 도로 공사로 콘크리트에 덮이고 말았다. 2010년 서종태 박사의 연구로 그 가치가 다시 드러나 정성용 신부가 기념 공간과 14처, 관련지를 잇는 3.5킬로미터 순례길을 조성했다.', '성 황석두 루카가 병인박해 전 십여 년을 보낸 피신처. 무명 순교자들의 떼무덤이 있던 자리, 2010년 재발견.', '산막골·작은재 성지 - 황석두 루카의 은둔지', '충남 서천 산막골·작은재성지, 성 황석두 루카가 보속의 삶을 살던 산중 피신처. 3.5km 순례길로 조성.', '평온', NULL, NULL),
  ('삽티 성지', '순교성지', '대전', '충남', '충청남도 부여군 홍산면 상천리 491', '부여와 보령의 경계, 삽티 고개 너머 산속 마을에 성 황석두 루카의 흔적이 남아있다. 충북 관평에서 가족을 이끌고 1850년대 이곳으로 옮겨온 그는 때때로 마을을 찾아 교리를 가르치고 신자들을 격려하다, 1866년 병인박해 때 3월 30일 갈매못에서 순교했다. 친척들이 몰래 유해를 거두어 이곳에 묻었으나 훗날 발각되어 처형당하기도 했다. 1962년 이 자리에서 십자가와 성모상, 묵주가 담긴 옹기 항아리가 발굴되어 현재 절두산순교성지 박물관에 소장되어 있다. 2016년부터 복원 사업이 시작되어 2018년 부여군이 십자가와 기념 공간을 세웠다.', '성 황석두 루카의 가족이 정착한 은신처. 1962년 유물 발굴(현 절두산박물관 소장). 2016~2018년 복원.', '삽티 성지 - 옹기 항아리에 숨긴 신앙', '충남 부여 삽티성지, 성 황석두 루카 일가의 은신처. 1962년 발굴된 유물이 절두산박물관에 전시된 성지.', '평온', NULL, NULL),
  ('서짓골 성지', '순교성지', '대전', '충남', '충청남도 보령시 미산면 평라리 438-3', '보령 미산면, 순교자들의 유해가 백오십 년 가까이 세상을 떠돌았던 사연이 깃든 담배밭. 1866년 3월 30일 성 금요일, 갈매못 백사장에서 순교한 다블뤼 주교와 오매트르·위앵 신부, 회장 장주기 요셉을 비롯해 오백여 명의 신자가 함께 처형되었다. 처형지에 임시로 묻혔던 이들의 유해는 그해 5월 오포골로, 7월에는 배를 타고 이곳 서짓골로 옮겨져 15년 6개월을 머물렀다. 이후 1882년 일본 나가사키로, 1894년 용산 신학교로, 1900년 명동대성당 지하로, 1967년 절두산 순교성지로 차례차례 이장되었다. 2013년 네 순교자의 이름을 새긴 오십 톤 흑요석 야외 제대가 봉헌되며 성지로 조성되었다.', '다블뤼 주교 등 4위 순교자의 유해가 1866~1882년 15년 6개월간 임시로 안장되었던 자리. 2013년 성지 조성.', '서짓골 성지 - 15년을 떠돈 순교자의 유해', '충남 보령 서짓골성지, 다블뤼 주교 등 순교자들의 유해가 15년 넘게 임시로 머물렀던 담배밭.', '치유', NULL, NULL),
  ('수리치골 성모 성지', '순례길', '대전', '충남', '충청남도 공주시 신풍면 봉갑리 356-6', '공주 신풍면 깊은 골짜기, 외딴 곳에 자리한 신심 깊은 한 가정의 작은 집이 한국 첫 마리아 신심회의 출발점이 되었다. 1846년 11월 2일, 페레올 주교가 이곳에서 원죄 없이 잉태되신 성모성심회를 세우며 한국 최초의 성모 신심 단체가 탄생했다. 박해를 피해 살아가야 했던 시절, 깊은 골짜기와 은둔이 가능했던 지형 덕에 신자들이 모일 수 있었던 자리다. 1990년 성삼위 조각상이 세워지고, 1993년에는 성모 일곱 고통의 길이 조성되었고, 1997년 미리내 성모의 성심수녀회 본원이 이곳으로 옮겨왔다.', '1846년 페레올 주교가 한국 최초의 성모 신심 단체(성모성심회)를 세운 자리.', '수리치골 성모 성지 - 한국 첫 마리아 신심의 출발', '충남 공주 수리치골성모성지, 1846년 한국 최초의 성모 신심 단체가 탄생한 산골 성지.', '평온', NULL, NULL),
  ('원머리 성지', '순교성지', '대전', '충남', '충청남도 당진시 신평면 한정리 231-1', '당진 신평면, 밀물 때면 섬처럼 변하던 지형 덕에 언덕머리라는 뜻의 원머리라는 이름을 얻은 마을. 1790년대부터 삽교천변에 자리 잡은 신자들은 소금을 굽고 옹기를 구우며 생계를 이었다. 박선진 마르코와 박태진 마티아 부자는 1868년 체포되어 수원으로 압송되었는데, 박태진은 고문에 못 이겨 한때 배교했다가 뉘우치고 열닷새 뒤 아버지와 함께 순교의 길을 택했다. 서른셋과 쉰둘의 나이로 세상을 떠난 두 사람의 유해는 신평성당에 모셔져 있다가 2009년 이곳 원머리 옛 매장지로 다시 옮겨졌다.', '박선진 마르코·박태진 마티아 부자가 1868년 수원에서 순교. 2009년 유해를 원머리로 이장.', '원머리 성지 - 뉘우침 끝에 지킨 부자의 신앙', '충남 당진 원머리성지, 박선진 마르코·박태진 마티아 부자가 1868년 순교한 삽교천변 신앙 마을.', '위로', NULL, NULL),
  ('지석리 성지', '순교성지', '대전', '충남', '충청남도 부여군 충화면 지석리 368-1 (팔충사 옆)', '부여 충화면, 두 순교성인이 나고 자란 고향 마을. 손선지 베드로는 회장으로서 옥에 갇힌 동료 신자들에게까지 신앙의 위로를 전했고, 양반가 출신 정문호 바르톨로메오는 "오늘 하늘로 과거 보러 간다"는 말을 남기며 기쁘게 순교를 맞았다고 전해진다. 두 사람은 1866년 병인박해 때 전주 숲정이에서 함께 참수되었다. 1988년 홍산본당이 세운 기념비와 야외 제대가 있던 이 자리는 2014년 안내판과 주차장을 갖추며 새롭게 단장되었다.', '성 손선지 베드로·정문호 바르톨로메오의 고향. 1866년 전주 숲정이에서 함께 순교, 1984년 시성.', '지석리 성지 - 기쁘게 순교를 맞은 두 성인의 고향', '충남 부여 지석리성지, 성 손선지·정문호 두 순교성인의 고향. 1866년 전주 숲정이에서 함께 순교.', '새출발', NULL, NULL),
  ('진산 성지', '순교성지', '대전', '충남', '충청남도 금산군 진산면 지방리 335-2', '금산 진산면, 한국 천주교 첫 순교자 두 사람이 태어난 고향. 윤지충 바오로와 외종형 권상연 야고보는 교황의 제사 금지령에 따라 조상의 신주를 불사르고 천주교식으로 모친상을 치렀다가 1791년 발각되어 불효자로 고발당했다. 두 사람은 그해 12월 8일 전주 남문 밖에서 참수형을 당했고, 이 진산 사건은 신해박해의 도화선이 되었다. 이후 흩어져 있던 신자들이 조금씩 모여 본당을 이루었고, 1980년 전주교구에서 대전교구로 이관되었다가 2009년 작은 공소에서 순례 성당으로 승격했다. 2014년 두 순교자는 프란치스코 교황에 의해 시성되었다.', '한국 천주교 첫 순교자 윤지충 바오로·권상연 야고보의 고향. 1791년 진산사건으로 신해박해 촉발, 2014년 시성.', '진산 성지 - 첫 순교자들의 고향, 신해박해의 시작', '충남 금산 진산성지, 한국 첫 순교자 윤지충·권상연의 고향이자 신해박해가 시작된 진산사건의 현장.', '새출발', NULL, NULL),
  ('합덕 성당', '성당', '대전', '충남', '충청남도 당진시 합덕읍 합덕리 275-2', '당진 합덕읍, 쌍탑이 솟은 붉은 벽돌 성당이 내포 평야를 내려다본다. 1890년 예산 양촌공소로 시작된 이 본당은 1899년 지금의 자리로 옮겨와 합덕이라는 이름을 얻었고, 1929년 페랭 신부 재임 때 지금의 벽돌 성당이 완공되었다. 6·25전쟁이 한창이던 1950년 페랭 신부는 체포되어 순교했고, 평신도 윤복수와 복사 송상원도 함께 목숨을 잃었다. 성당 마당에는 이들을 기리는 순교 기념비가 서 있으며, 바로 옆에는 다블뤼 주교의 은거지였던 신리성지가 자리해 함께 순례하기 좋다.', '1890년 설립, 1929년 완공된 성당(충남 기념물 제145호). 6·25전쟁 때 페랭 신부 등 3명 순교.', '합덕 성당 - 내포 평야의 쌍탑 성당', '충남 당진 합덕성당, 1929년 완공된 쌍탑 벽돌 성당. 6·25전쟁 순교자 페랭 신부를 기리는 내포 평야의 랜드마크.', '감사', NULL, NULL),
  ('홍주 순교 성지', '순교성지', '대전', '충남', '충청남도 홍성군 홍성읍 아문길 37-1', '홍성 읍내, 조선시대 넓은 관할을 거느렸던 홍주읍성 전체가 순교의 피로 물든 자리였다. 관장이 신자들을 문초하던 동헌, 백 명 넘게 갇혔던 옥터, 월계천변 처형장, 두 물길이 만나는 곳의 떼무덤까지—1791년부터 1870년대까지 세 시기에 걸쳐 이름이 확인된 순교자만 212명, 기록에 남지 못한 이들까지 합하면 천 명이 넘을 것으로 추정된다. 2014년 프란치스코 교황 방한 때 원시장 베드로, 방 프란치스코, 박취득 라우렌시오, 황일광 시몬 등 홍성 출신 네 사람이 시복되었다.', '조선시대 홍주읍성 전역이 순교지. 확인된 순교자만 212명, 실제로는 1,000명 이상 추정. 2014년 4위 시복.', '홍주 순교 성지 - 읍성 전체가 순교의 땅', '충남 홍성 홍주순교성지, 확인된 순교자만 212명에 이르는 홍주읍성 전역의 순교지. 2014년 4위 시복.', '치유', NULL, NULL),
  ('황무실 성지', '순례길', '대전', '충남', '충청남도 당진시 합덕읍 석우리 1013', '당진과 예산의 경계, 나지막한 구릉 지대에 1791년부터 1868년까지 여러 박해를 관통하며 신앙을 지킨 교우촌이 있었다. 이곳은 신리와 더불어 파리외방전교회 선교사들이 머물며 사목한 거점으로, 고아 사업과 배론 신학교를 세운 매스트르 신부, 이곳에서 선종한 랑드르 신부, 순교한 위앵 신부 등 여러 프랑스 선교사들의 흔적이 남아있다. 인근에서만 70여 명에 이르는 순교자가 나왔다고 전해진다. 1970년 무덤들이 이장되며 한동안 잊혔던 이곳은 2008년 청소년 순례 출발지로 지정되었고, 2014년 이보현 프란치스코의 시복을 계기로 다시 활기를 되찾았다.', '1791~1868년 여러 박해를 거친 교우촌. 파리외방전교회 선교사들의 사목 거점, 70여 명의 순교자 배출.', '황무실 성지 - 선교사들이 머문 내포의 교우촌', '충남 당진·예산 경계 황무실성지, 파리외방전교회 선교사들의 사목 거점이었던 내포 지방 교우촌.', '평온', NULL, NULL),
  ('정산 순교 성지', '순교성지', '대전', '충남', '충청남도 청양군 정산면 서정리 496-1 (정산면사무소 인근)', '청양 정산면, 옹기장수로 각지를 떠돌며 복음을 전하던 이가 마지막으로 신앙을 증거한 자리. 칠갑산 너머로 피신해 이곳에 정착한 이도기 바오로는 옹기를 팔러 다니며 은밀히 교리를 전하다, 1798년 정사박해 때 쉰넷의 나이로 정산 관아에 끌려가 혹독한 문초를 받았다. 관장이 벼슬자리를 미끼로 배교를 종용하자 그는 "정산고을을 다 준다 해도 하느님을 배반할 수 없다"고 답했다. 오늘날 정산면사무소 인근 이 자리에서, 옹기 하나에 의지해 신앙을 전하던 한 평신도의 결기를 만난다.', '복자 이도기 바오로(1743~1798)가 1798년 정사박해 때 문초받고 순교한 정산 관아 터.', '정산 순교 성지 - 옹기장수 이도기의 신앙', '충남 청양 정산순교성지, 옹기장수로 복음을 전하다 1798년 순교한 복자 이도기 바오로의 관아 터.', '위로', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('원동 주교좌성당', '주교좌성당', '원주', '강원', '강원도 원주시 원동 85', '원주 원동, 둥근 돔 모양의 종탑이 인상적인 원주교구 주교좌성당. 1896년 풍수원본당에서 분리되어 설립된 이 본당은 초대 주임 르메르 신부가 원주 관아 인근 땅을 사들여 터를 잡았다. 1913년 고딕 양식의 성당이 완공되어 뮈텔 주교의 축성을 받았으나, 6·25전쟁으로 크게 파괴되었다. 1954년 재건된 성당은 1970년대 민주화운동의 중심지가 되어, 1974년 지학순 주교가 구속되자 시국 관련 기도회가 이곳에서 이어졌다. 2004년 독특한 돔형 종탑을 인정받아 국가등록문화재 제139호로 지정되었다.', '1896년 설립된 원주교구 주교좌성당. 1970년대 민주화운동의 중심지, 지학순 주교 구속 관련 기도회 개최지. 국가등록문화재 제139호.', '원동 주교좌성당 - 민주화 기도의 중심, 원주교구좌', '강원 원주 원동주교좌성당, 1896년 설립된 원주교구 주교좌성당. 1970년대 민주화운동의 중심지, 국가등록문화재 제139호.', '감사', NULL, NULL),
  ('강원 감영', '역사사적지', '원주', '강원', '강원도 원주시 일산동 54-1', '원주 시내, 500년간 강원도 행정의 중심이었던 감영 자리. 조선시대 이곳 선화당에서는 강원도 각지에서 붙잡혀 온 천주교 신자들이 문초받고 처형되었다. 2014년 시성된 김강이 시몬, 최해성 요한, 최영이 브리지타 등이 이곳에서 순교했다. 감영의 정문 포정루와 선화당은 1971년 문화재 제3호로 지정되어 원형 일부가 남아있고, 2018년 복원 공사를 통해 옛 모습을 되찾았다.', '500년간 강원도 행정 중심이었던 감영, 조선시대 천주교 신자 문초·처형지. 2014년 시성된 김강이 시몬 등이 순교. 포정루·선화당은 문화재 제3호.', '강원 감영 - 순교자들이 문초받은 500년 관아', '강원 원주 강원감영, 500년 강원도 행정 중심지이자 천주교 순교자들의 문초·처형지. 포정루·선화당은 문화재 제3호.', '위로', NULL, NULL),
  ('대안리 공소', '성당', '원주', '강원', '강원도 원주시 흥업면 대안리 659', '원주 흥업면, 100년 넘은 한옥 목조 공소가 마을을 지키고 있다. 1886년 한불조약으로 신앙의 자유를 얻은 신자들이 모여든 이 교우촌은 1892년 무렵 공소로 시작되었는데, 이는 원주교구에서 풍수원본당 다음으로 오래된 신앙 공동체다. 1900년대 초 지어진 목조 한옥 건물은 1910년 뮈텔 주교의 일기에 축복식이 기록될 만큼 유서 깊다. 초가지붕이 1950년대 기와로 바뀌고 6·25전쟁 때는 병영과 구호물자 배급소로도 쓰였던 이 공소는 2004년 국가등록문화재 제140호로 지정되었다.', '1892년 무렵 설립된 원주교구에서 두 번째로 오래된 교우촌 공소. 국가등록문화재 제140호.', '대안리 공소 - 원주에서 두 번째로 오래된 공소', '강원 원주 대안리공소, 1892년 무렵 설립된 원주교구 두 번째 유서 깊은 교우촌. 국가등록문화재 제140호.', '평온', NULL, NULL),
  ('성 남종삼 요한·순교자 남상교 아우구스티노 유택지', '순교성지', '원주', '충북', '충청북도 제천시 봉양읍 학산리 326-1', '제천 봉양읍 학산리, 조선 조정에서 가장 높은 관직에 오른 순교성인이 마지막으로 신앙을 준비하던 자리. 철종과 고종 아래 승지와 왕의 사부를 지낸 남종삼 요한은 러시아의 남하를 막기 위해 프랑스와의 수교를 조정에 건의했으나 받아들여지지 않았고, 대원군의 박해가 시작되자 관직 대신 신앙을 택했다. 그는 이곳 묘재에 내려와 순교를 각오하며 마음을 다잡은 뒤 상경길에 올랐고, 고양에서 체포되어 1866년 3월 7일 베르뇌·다블뤼 주교와 함께 서대문에서 처형되었다. 정약용의 학풍을 이은 학자였던 그의 아버지 남상교 아우구스티노도 공주에서, 큰아들은 전주에서, 부인은 창녕 유배지에서 세상을 떠나 3대에 걸쳐 네 명의 순교자를 낳은 집안의 자취가 이곳에 남아있다.', '성 남종삼 요한이 상경 전 마지막으로 머문 자리. 부친 남상교 아우구스티노 등 3대 4명이 순교한 가문의 유택지.', '묘재 - 남종삼 요한 3대 순교 가문의 자리', '충북 제천 묘재, 최고위 관직을 지낸 성 남종삼 요한과 3대에 걸친 순교 가문의 유택지.', '위로', NULL, NULL),
  ('성내동 성당', '성당', '원주', '강원', '강원도 삼척시 성내동 3-1', '삼척 시내가 한눈에 내려다보이는 언덕, 6·25전쟁의 아픔을 딛고 세워진 성당이 자리한다. 1946년 강릉본당의 공소로 시작해 1949년 본당으로 승격했으나, 초대 주임이었던 콜롬반 외방선교회 소속 매긴 신부가 1950년 7월 4일 공산군에 의해 순교했다. 이후 코너스 신부가 성당 건립을 이끌어 1957년 3월 착공, 그해 11월 축성되었다. 133평 규모로 당시 춘천교구에서 가장 큰 건물이었던 이 성당은 1950년대 지방 건축 기법을 잘 보여주어 2004년 국가등록문화재 제141호로 지정되었으며, 1965년 신설된 원주교구로 이관되었다.', '매긴 신부가 1950년 순교한 성당. 1957년 완공된 당시 춘천교구 최대 규모 건물, 국가등록문화재 제141호.', '성내동 성당 - 삼척을 내려다보는 순교의 기억', '강원 삼척 성내동성당, 매긴 신부가 순교한 자리에 1957년 세워진 성당. 국가등록문화재 제141호.', '위로', NULL, NULL),
  ('단양 김범우 순교 성지', '순교성지', '원주', '충북', '충청북도 단양군 단성면 상방리·하방리 일대', '단양 단성면, 한국천주교회 최초의 증거자 김범우 토마스가 유배되어 생을 마친 자리. 명례방에서 열리던 신앙 모임의 집주인이었던 그는 1785년 을사추조적발사건으로 발각되어 유배형을 받았고, 이곳 단양에서 유배 생활을 하다 1787년 세상을 떠났다. 오랫동안 잊혀 있던 이 자리는 2026년 원주교구에 의해 단양 김범우 순교성지로 선포되며 다시 세상에 알려졌다. 부산 밀양의 김범우 순교자 성지와 더불어, 한국 최초 증거자의 신앙과 고난을 함께 기억하게 하는 자리다.', '한국천주교회 최초의 증거자 김범우 토마스(1751~1787)가 유배되어 선종한 자리. 2026년 원주교구가 순교성지로 선포.', '단양 김범우 순교 성지 - 최초 증거자의 유배지', '충북 단양 김범우순교성지, 한국 최초 증거자 김범우 토마스가 유배되어 선종한 자리. 2026년 성지 선포.', '위로', NULL, NULL),
  ('서지 마을', '교우촌', '원주', '강원', '강원도 원주시 부론면 서지리', '원주 부론면, 최양업 신부의 자취를 좇는 희망의 순례길 위에 자리한 작은 마을. 박해를 피해 가족을 이끌고 이곳에 숨어든 최해성 요한은 가난 속에서도 굳은 신앙으로 가난한 이웃을 돌보며 "천주를 위해 목숨을 바치는 것이 얼마나 큰 행복인가"라는 말을 자주 남겼다고 전해진다. 그는 2014년 프란치스코 교황 방한 때 시복되었다. 오늘날 서지 교우촌은 춘천·원주교구에 걸쳐 있는 최양업 신부 연고지 30여 곳을 잇는 희망의 순례길의 한 구간으로, 땀의 순교자가 다니던 옛길을 따라 걷는 이들의 발길이 이어진다.', '복자 최해성 요한이 가족과 숨어 지내며 신앙을 지킨 교우촌. 2014년 시복. 최양업 신부 순례길의 한 구간.', '서지 마을 - 땀의 순교자 순례길의 한 구간', '강원 원주 서지마을, 복자 최해성 요한이 신앙을 지킨 교우촌. 최양업 신부 희망의 순례길 구간.', '평온', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('의정부 주교좌성당', '주교좌성당', '의정부', '경기', '경기도 의정부시 의정부 2동 429-6', '의정부 중심가, 6·25전쟁의 상흔을 딛고 돌 하나하나를 쌓아 올린 성당이 서 있다. 1945년 김베드로 신부가 덕정리본당을 이곳으로 옮겨오며 시작된 본당은 전쟁 중 목조 성당이 불타 없어지자, 1953년 미군 종군신부 로제스키의 도움을 받아 석조 성당으로 다시 세워졌다. 포탄의 피해를 줄이기 위해 낮고 튼튼하게 지어진 이 성당은 2002년 경기도 문화재자료 제99호로 지정되었다. 이후 여러 본당을 분가시켜 의정부의 어머니 본당이라 불리게 되었고, 2004년 의정부교구가 설정되며 주교좌성당이 되었다.', '1945년 설립, 1953년 석조로 재건된 의정부 지역 어머니 본당. 2004년 의정부교구 설정으로 주교좌성당 승격. 경기도 문화재자료 제99호.', '의정부 주교좌성당 - 전쟁의 상흔을 딛고 세운 석조 성당', '경기 의정부 주교좌성당, 6·25전쟁 후 1953년 재건된 석조 성당. 의정부 지역 어머니 본당이자 경기도 문화재자료 제99호.', '감사', NULL, NULL),
  ('갈곡리 성당', '성당', '의정부', '경기', '경기도 파주시 법원읍 갈곡리 182', '파주 법원읍, 칡이 많아 칡울이라 불리던 마을에 자리한 성당. 1896년 무렵 박해를 피해 온 신자들이 정착해 옹기를 구우며 살아갔고, 1898년 약현본당 관할 공소로 출발해 20명이던 신자가 2년 만에 145명으로 늘었다. 6·25전쟁으로 무너진 성당은 1955년 미 해병대 군종신부 마요셉의 도움으로 의정부 성당을 본떠 다시 세워졌다. 2018년 이 마을 출신 순교자 김치호 베네딕토 신부와 김정숙 마리안나 수녀를 기리는 준본당 성지로 지정되었다.', '1898년 설립된 옹기 교우촌 성당. 2018년 순교자 김치호 베네딕토 신부·김정숙 마리안나 수녀 기념 성지로 지정.', '갈곡리 성당 - 칡울 옹기 마을의 신앙', '경기 파주 갈곡리성당, 1898년 설립된 옹기 교우촌 성당. 순교자 김치호 신부·김정숙 수녀를 기리는 성지.', '위로', NULL, NULL),
  ('마재 성가정 성지', '순례길', '의정부', '경기', '경기도 남양주시 조안면 능내리 116', '남양주 조안면 능내리, 다산 정약용을 비롯한 네 형제가 태어난 마을이자 한국천주교회의 요람. 셋째 형 정약종 아우구스티노는 신앙을 지키다 순교해 2014년 시복되었고, 그의 아들 정하상 바오로와 딸 정정혜 엘리사벳은 1984년 성인으로 시성되었다. 정약용 자신은 십여 년 신앙을 탐구했으나 박해 속에 거리를 두었고, 1801년부터 18년간 강진 유배 생활을 하며 방대한 학문적 업적을 남긴 뒤, 만년에는 묵상과 보속, 기도의 삶으로 되돌아왔다고 전해진다. 2007년 한옥 양식 경당과 색동옷 입은 예수·성모상이 조성되었고, 2017년 성가정 성지로 정식 선포되었다.', '다산 정약용 형제의 생가터이자 한국천주교회의 요람. 정약종 아우구스티노(2014 시복)와 두 자녀(1984 시성)를 배출한 성가정. 2017년 성지 선포.', '마재 성가정 성지 - 정약용 형제의 신앙 마을', '경기 남양주 마재성가정성지, 정약용 형제의 생가이자 정약종 아우구스티노 일가를 배출한 한국천주교회의 요람.', '새출발', NULL, NULL),
  ('성 남종삼 요한과 가족 묘소', '순교성지', '의정부', '경기', '경기도 양주시 장흥면 울대리 산 22-2', '양주 장흥면 울대리 산자락, 103위 성인 중 가장 높은 관직에 올랐던 이가 가족과 함께 잠들어 있다. 좌승지를 지낼 만큼 조정의 신임이 두터웠던 남종삼 요한은 조상 제사 문제로 관직과 신앙 중 하나를 택해야 하는 순간, 벼슬을 내려놓고 아버지 곁으로 물러나 은둔했다. 1866년 3월 7일 서소문 밖에서 순교한 그의 유해 일부가 1967년 이곳 의령 남씨 선산으로 옮겨져 가족과 나란히 묻혔다. 청빈하고 겸손했던 고위 관료가 끝내 신앙을 택한 결단이 이 조용한 가족 묘역에 깃들어 있다.', '103위 성인 중 최고위 관직자였던 남종삼 요한(1817~1866)이 가족과 함께 묻힌 묘소. 1967년 유해 일부 이장.', '성 남종삼 요한과 가족 묘소 - 관직 대신 택한 신앙', '경기 양주, 최고위 관직을 내려놓고 순교한 성 남종삼 요한과 가족이 잠든 묘소.', '위로', NULL, NULL),
  ('신암리 성당', '성당', '의정부', '경기', '경기도 양주시 남면 신암리 264-3', '양주 남면, 박해를 피해 옹기를 구우며 살아가던 신자들이 뿌리내린 마을에 자리한 성당. 1909년 개성본당 관할 공소로 시작해 1925년 본당으로 승격했으나 살림이 어려워 1930년 다시 공소로 돌아갔다. 6·25전쟁으로 무너진 성당은 1953~1955년 영국군의 도움으로 재건되었다. 오랜 세월 딸린 공소로 지내다 2008년 준본당, 2013년 정식 본당으로 승격했고, 2018년에는 이 마을 출신 순교자 이춘근 신부를 기리는 순례성지로 지정되었다.', '옹기 교우촌에서 출발한 성당, 6·25전쟁 후 영국군의 도움으로 재건. 2018년 이춘근 신부 순례성지로 지정.', '신암리 성당 - 옹기 마을의 순례성지', '경기 양주 신암리성당, 옹기 교우촌에서 출발한 성당. 순교자 이춘근 신부를 기리는 순례성지.', '평온', NULL, NULL),
  ('양주 순교 성지', '순교성지', '의정부', '경기', '경기도 양주시 유양동 233 (양주 향교 앞)', '양주 유양동, 조선시대 500년 가까이 이 지역 행정을 관장하던 관아 터. 1866년 병인박해 때 김윤오 요한과 그의 부인 권 마르타, 김 마리아, 박 아무개, 홍성원 아우구스티노 등 다섯 명이 이곳 관아에서 순교했다. 2000년부터 2017년까지 이어진 발굴로 여러 건물터와 유물이 드러났고, 1997년 복원된 동헌은 2017년 더욱 온전한 모습을 갖추었다. 의정부교구는 2016년 5월 28일 이곳을 교구 첫 순교성지로 선포했으며, 2025년 9월 새 경당이 봉헌되었다.', '1866년 병인박해 때 김윤오 요한 부부 등 5위가 순교한 옛 양주 관아 터. 2016년 의정부교구 첫 순교성지로 선포.', '양주 순교 성지 - 의정부교구 첫 순교성지', '경기 양주 순교성지, 1866년 김윤오 요한 부부 등 5위가 순교한 옛 관아 터. 의정부교구 첫 순교성지.', '치유', NULL, NULL),
  ('참회와 속죄의 성당', '성당', '의정부', '경기', '경기도 파주시 탄현면 일대', '파주 탄현면, 임진각에서 가까운 이 성당은 분단의 아픔을 참회와 속죄의 기도로 승화시키려는 바람에서 태어났다. 파리 몽마르트르 언덕의 사크레쾨르 대성전이 프로이센 전쟁 당시 동족상잔을 참회하며 세워졌듯, 6·25전쟁의 비극을 반성하고 화해를 청하고자 구상되었다. 외관은 신의주 진사동성당을, 내부는 함경남도 덕원 성 베네딕도 수도원의 전쟁 전 모습을 재현했다. 2008년 완공된 성당 옆에는 2014년 민족화해센터가 세워져, 매주 토요일 오후 화해의 기도와 미사가 이어진다.', '6·25전쟁 동족상잔을 참회하는 뜻으로 2008년 완공. 신의주 진사동성당 외관과 덕원 수도원 내부를 재현. 2014년 민족화해센터 건립.', '참회와 속죄의 성당 - 분단을 위로하는 기도', '경기 파주 참회와속죄의성당, 6·25전쟁을 참회하며 2008년 완공된 성당. 신의주·덕원 건축을 재현한 민족화해의 기도처.', '위로', NULL, NULL),
  ('행주 성당', '성당', '의정부', '경기', '경기도 고양시 덕양구 행주외동 194', '고양 행주, 한강 물길을 낀 상업 중심지에 자리한 성당. 1899년 약현본당 관할 공소로 시작해 52명이던 신자가 1년 만에 102명으로 늘었을 만큼 신앙이 빠르게 뿌리내렸다. 1909년 본당으로 승격되어 김원영 신부가 초대 주임으로 부임했고, 1910년 목조 성당이 봉헌되어 1928년 지금 자리로 옮겨졌다. 일제 강점기 공소로 격하되었다가 광복 후 다시 본당이 되었으나, 도시 변화에 따라 1957년 신촌동으로 옮겨가며 오랫동안 공소로 남아있었다. 2004년 의정부교구 설정과 함께 다시 본당으로 승격했고, 2010년 한식 목조 건축의 가치를 인정받아 국가등록문화재 제455호로 지정되었다.', '1899년 설립, 1910년 봉헌된 한식 목조 성당. 국가등록문화재 제455호. 2004년 의정부교구 설정으로 본당 재승격.', '행주 성당 - 한강변의 한옥 목조 성당', '경기 고양 행주성당, 1910년 봉헌된 한식 목조 성당. 국가등록문화재 제455호로 지정된 한강변의 유서 깊은 본당.', '감사', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('성모 순례지', '순례길', '인천', '인천', '인천시 동구 박문로 1 (인천교구청)', '인천 동구, 옛 박문여고 자리에 세계 각국의 성모상을 한자리에 모신 성모당이 들어섰다. 인천교구가 세운 이 순례지는 로마의 성모 마리아 대성전과 영적 유대를 맺어 이곳을 찾는 이들에게 대사의 은혜를 청원한다. 전시실에는 독일의 검은 성모 알트외팅, 멕시코의 과달루페 성모, 그리고 1885년 박해받는 신자들을 보호하려 성당 지붕에 나타났다는 베트남의 짜끼우 성모상 등이 함께 자리해, 대륙을 넘나드는 성모 신심의 풍경을 한눈에 담을 수 있다.', '옛 박문여고 자리에 건립된 인천교구 성모순례지. 세계 각국의 성모상을 전시하는 로마 성모 마리아 대성전 영적 유대 성지.', '성모 순례지 - 세계의 성모를 한자리에서', '인천 동구 성모순례지, 세계 각국의 성모상을 모은 인천교구 성모당. 로마 성모마리아대성전과 영적 유대를 맺은 순례지.', '평온', NULL, NULL),
  ('성체 순례 성지', '성당', '인천', '경기', '경기도 김포시 북변동 259-1', '김포, 새 성당 아래 옛 석조 성당이 나란히 남아있는 특별한 풍경. 1900년 무렵 약현본당 전교회장 유공현의 전교로 시작된 이 지역 신앙은 1946년 행주본당에서 분리되며 본당이 되었다. 1956년 완공된 옛 성당은 신자들이 직접 큰 돌을 나르고 곡괭이로 땅을 일구며 낮에는 농사, 저녁에는 성당 짓기에 매달려 세운 땀의 결실이다. 2013년 국가등록문화재 제542호로 지정된 이 석조 성당 아래로 1999년 새 성당이 들어섰고, 2015년 인천교구는 한국 교회 최초로 이곳을 성체 성지로 선포해 밤낮없는 성체조배가 이어진다.', '1946년 설립, 1956년 완공된 옛 석조 성당(국가등록문화재 제542호). 2015년 한국 교회 최초의 성체 성지로 선포.', '성체 순례 성지 - 신자들이 돌로 쌓은 옛 성당', '경기 김포 성체순례성지, 신자들이 직접 지은 1956년 석조 성당(국가등록문화재 제542호). 한국 첫 성체 성지.', '감사', NULL, NULL),
  ('일만 위 순교자 현양 동산', '순례길', '인천', '인천', '인천시 강화군 내가면 고천리 1486', '강화 내가면, 이름 남지 못한 만 명의 순교자를 기리는 침묵의 순례지. 백여 년 박해 기간 동안 만 명에서 삼만 명에 이르렀을 것으로 추정되는 순교자 중, 이름이 확인된 이는 겨우 천 명 남짓이다. 1996년 가을 인천가톨릭대학교의 노력으로 시작되어 2002년 인천교구가 축성한 이곳에는 무명관을 개조한 경당, 십자가의 길, 순교자 성당이 자리한다. 2007년에는 병인박해 희생자 성 남종삼의 유해를 모신 기념관이, 2018년에는 홀로 걷는 묵주기도 길이 조성되어, 이름 없이 스러진 이들 앞에서 저마다 조용히 자신을 돌아보게 한다.', '1996년 조성 시작, 2002년 인천교구 축성. 이름 남기지 못한 순교자 약 1만~3만 명을 기리는 침묵의 순례지.', '일만 위 순교자 현양 동산 - 이름 없는 이들을 위한 침묵', '인천 강화 일만위순교자현양동산, 이름 남기지 못한 순교자 만여 명을 기리는 침묵의 순례지. 성 남종삼 유해 봉안.', '위로', NULL, NULL),
  ('진무영 순교 성지', '순교성지', '인천', '인천', '인천시 강화군 강화읍 관청리 643 (강화 성당 내)', '강화읍, 조선 숙종 4년인 1678년 강화도 해안 방어를 위해 설치된 군영 진무영 자리에 순교의 기억이 서려 있다. 1866년 병인양요 당시 프랑스 함대와 내통했다는 혐의로 1868년 장치선과 최영준이 처형되었는데, 실제로는 리델 신부의 중국 탈출을 돕고 박해받는 신자들을 구하려 애쓴 것이었다. 조정은 이들을 군영 안에서 공개 처형해 군사들에게 경고로 삼았다. 오늘날 강화성당 경내에 마련된 이 자리에는 소박한 야외 제대와 십자가가 서 있어, 신앙과 애국이 뒤섞였던 그날의 복잡한 사연을 전한다.', '1868년 장치선·최영준이 프랑스 함대 내통 혐의로 처형된 진무영 옛터. 실제로는 리델 신부의 탈출을 도운 것으로 전해짐.', '진무영 순교 성지 - 강화 군영에 새겨진 순교', '인천 강화 진무영순교성지, 1868년 장치선·최영준이 처형된 조선 군영 터. 강화성당 경내의 소박한 순교 기념지.', '치유', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('음성 봉암 성지', '교우촌', '청주', '충북', '충청북도 음성군 맹동면 봉현로 145 (봉현리 318-3)', '음성 맹동면, 방축골과 계마대 두 자락에 걸쳐 있던 옛 교우촌 마을. 1839년 기해박해 이후 김백심 암브로시오, 송군명 바오로 등이 이곳으로 숨어들어 신앙 공동체를 이루었고, 뒤이어 충주 광벌에서 옮겨온 민윤명 프란치스코 회장 가족이 계마대에 자리 잡았다. 한국 두 번째 사제 최양업 신부는 사목 순방 중 이 마을에 들러 성사를 주었고, 김백심의 막내아들을 신학생으로 선발해 진천 배티 신학교로 보내기도 했다. 1892년 정무선 요셉이 다시 신앙 공동체를 일으켜 세운 봉암공소는 1897년 설립되어 지금까지 신앙의 뿌리를 이어가고 있으며, 2020년 청주교구가 이곳을 성지로 선포했다.', '1839년 기해박해 이후 형성된 방축골·계마대 교우촌. 최양업 신부가 사목 순방한 자리, 1897년 봉암공소 설립. 2020년 성지 선포.', '음성 봉암 성지 - 최양업 신부가 다녀간 교우촌', '충북 음성 봉암성지, 기해박해 이후 형성된 방축골·계마대 교우촌. 최양업 신부의 사목 흔적이 남은 2020년 선포 성지.', '평온', NULL, NULL),
  ('충주 숲거리 순교 성지', '순교성지', '청주', '충북', '충청북도 충주시 문화동 552 (문화동 544~봉방동 11-1 일대)', '충주 문화동과 봉방동 접경, 조선시대 군사 훈련 지휘소인 무학당에서 충주천변까지 길게 이어지던 수풀 지역. 군사 훈련장이자 충주의 대표적인 형장이었던 이곳은 1801년 신유박해 이후 각지에서 체포된 천주교 신자들의 순교지가 되어, 참수형과 군문효수형이 잇따랐다. 충주에 가장 먼저 신앙의 씨앗을 뿌려 연풍까지 전한 충주의 사도 이기연은 신유박해 때 이곳에서 참수되었고, 아전 출신 이부춘과 과부 권아기련도 뒤이어 순교의 화관을 썼다. 청주교구는 2020년 이곳을 숲거리순교성지로 선포하고 이들의 시복을 추진하고 있다.', '1801년 신유박해 이후 순교지가 된 조선시대 군사 훈련장·형장. 충주의 사도 이기연, 이부춘, 권아기련이 순교. 2020년 성지 선포, 시복 추진 중.', '충주 숲거리 순교 성지 - 충주의 사도가 잠든 형장', '충북 충주 숲거리순교성지, 충주의 사도 이기연 등이 순교한 조선시대 형장. 2020년 청주교구가 성지로 선포.', '치유', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('개갑 장터 순교 성지', '순교성지', '전주', '전북', '전라북도 고창군 공음면 석교리 157-1', '고창 공음면, 조선시대 물산이 모여들던 장터에 순교의 기억이 새겨져 있다. 무장의 양반가에서 태어난 최여겸 마티아는 윤지충 바오로와 이존창 루도비코에게 교리를 배워 신앙을 받아들인 뒤, 이웃 스물여덟 명에게 복음을 전했다. 1801년 신유박해 때 처가로 피신했으나 발각되어 무장·전주·한양을 오가며 문초를 받았고, 그해 8월 21일 사형이 확정되어 8월 27일 이곳 개갑장터에서 참수되었다. 2013년 전주교구가 12미터 순교탑과 야외 제대, 400미터 십자가의 길을 조성해 성역화했다.', '복자 최여겸 마티아(1763~1801)가 1801년 신유박해 때 순교한 장터. 2014년 시복, 2013년 성역화.', '개갑 장터 순교 성지 - 스물여덟을 전도한 이의 순교', '전북 고창 개갑장터순교성지, 복자 최여겸 마티아가 1801년 순교한 장터. 12m 순교탑과 십자가의 길.', '위로', NULL, NULL),
  ('김제 순교 성지', '순교성지', '전주', '전북', '전라북도 김제시 요촌동 (요촌성당 내)', '김제 요촌성당 경내, 가난한 양반 출신 한 신자가 신앙을 지킨 자리가 있다. 한정흠은 1784년 이승훈에게 세례를 받은 뒤 고향 김제로 돌아와 복음을 전했다. 1801년 신유박해 때 체포되어 전라감영에서 심문받고 한양으로 압송되어서도 신앙을 굽히지 않았던 그는, 그해 8월 26일 마흔다섯의 나이로 참수되어 순교했다. 오늘날 요촌성당 경내에 마련된 이 작은 성지는 김제 지역 신앙의 뿌리를 조용히 증언한다.', '한정흠이 1801년 신유박해 때 순교한 자리. 김제 요촌성당 경내에 조성.', '김제 순교 성지 - 한정흠의 흔들리지 않은 신앙', '전북 김제 순교성지, 1801년 신유박해 때 순교한 한정흠을 기리는 요촌성당 내 성지.', '위로', NULL, NULL),
  ('되재 성당지', '성당', '전주', '전북', '전라북도 완주군 화산면 승치리 729-1', '완주 화산면 산골, 논산의 폐사지에서 옮겨온 목재로 지은 한국 최초의 한옥 성당이 있던 자리. 1891년 비예모트 신부가 설립한 이 본당은 1895년 지금 자리로 옮겨오며 한강 이남 첫 성당이자 한국 최초의 한옥 성당으로 자리 잡았다. 박해를 피해 산속으로 숨어든 신자들의 공동체가 이 성당을 중심으로 완전한 신앙촌을 이루었다. 1950년 한국전쟁 때 반군의 거점이 될 것을 우려한 군에 의해 불타 사라졌으나, 2004년 전라북도 기념물 제119호로 지정되고 2009년 복원 축복식을 가졌다.', '1895년 이전, 한강 이남 첫 성당이자 한국 최초의 한옥 성당. 1950년 한국전쟁 때 소실, 2009년 복원.', '되재 성당지 - 한국 최초의 한옥 성당', '전북 완주 되재성당지, 한강 이남 첫 성당이자 한국 최초 한옥 성당 터. 전라북도 기념물 제119호.', '새출발', NULL, NULL),
  ('서천교 순교 터', '순교성지', '전주', '전북', '전라북도 전주시 완산구 서완산동 1가 351-1', '전주 완산구, 다리 아래에 걸인들의 손을 빌려 한 소년의 목숨을 앗아간 잔혹한 사연이 새겨진 자리. 태중 교우로 신앙을 키운 조윤호 요셉은 1866년 병인박해 때 아버지 조화서 베드로와 함께 체포되어 전라감영에서 혹독한 문초를 당했다. 부자는 서로를 격려하며 신앙을 지켰고, 아버지가 12월 13일 먼저 참수된 뒤 열여덟 살 아들은 열흘 뒤 다리 밑에 살던 걸인들에게 강요되어 목에 줄이 매인 채 교살당했다. 두 부자는 1968년 시복, 1984년 성인으로 시성되었고, 2006년 전주교구가 순교 현장에 모자이크 벽화를 세웠다.', '성 조윤호 요셉(1848~1866)이 1866년 열여덟의 나이로 순교한 자리. 아버지 조화서 베드로와 함께 1984년 시성.', '서천교 순교 터 - 열여덟 소년의 마지막 순간', '전북 전주 서천교순교터, 성 조윤호 요셉이 열여덟에 순교한 자리. 아버지 조화서 베드로와 함께 성인 반열에 올랐다.', '위로', NULL, NULL),
  ('수류 성당', '성당', '전주', '전북', '전라북도 김제시 금산면 화율리 223', '김제 금산면, 영화 보리울의 여름 촬영지로도 알려진 아담한 벽돌 성당. 1889년 산속 배재 마을에서 설립되어 1895년 접근이 좋은 수류로 옮겨오면서 주변 신자들이 모여들어 온전한 신앙 공동체를 이루었다. 1907년 지어진 목조 성당은 6·25전쟁 때 파괴되어 오십여 명의 신자가 순교했고, 이후 신자들이 직접 벽돌을 구워 1959년 지금의 벽돌 성당을 세웠다. 15명 가까운 사제를 배출한 성소의 못자리로, 청소년 야영장과 수영장, 농촌 체험관을 갖추고 있다.', '1889년 설립, 1959년 신자들이 직접 벽돌을 구워 지은 성당. 6·25전쟁 때 50여 명 순교, 15명 가까운 사제 배출.', '수류 성당 - 신자들이 직접 구운 벽돌 성당', '전북 김제 수류성당, 6·25전쟁 순교자를 기리며 신자들이 직접 벽돌을 구워 지은 성당. 15명 가까운 사제를 배출한 성소의 못자리.', '위로', NULL, NULL),
  ('수분 공소', '성당', '전주', '전북', '전라북도 장수군 장수읍 수분리 662-1', '장수 깊은 산골, 서양식 평면과 한옥의 외형이 조화를 이룬 공소가 자리한다. 1850년대 최양업 신부의 사목으로 뿌리내린 이 신앙 공동체는 1921년 함양에서 28킬로미터 떨어진 곳까지 기와를 져 나르고 인근 숲에서 목재를 베어 지금의 건물을 지었다. 1926년부터 한동안 본당이었다가 1950년대 이후 장수본당의 공소가 되었으며, 2005년 국가등록문화재 제189호로 지정되었다. 2011~2013년 문화재 지원을 받아 정밀하게 복원되었다.', '1850년대 최양업 신부의 사목으로 시작, 1921년 신축된 한옥 공소. 국가등록문화재 제189호.', '수분 공소 - 최양업 신부가 뿌리내린 산골 공소', '전북 장수 수분공소, 최양업 신부의 사목으로 뿌리내린 산골 공소. 1921년 신축된 국가등록문화재 제189호.', '평온', NULL, NULL),
  ('신성 공소', '교우촌', '전주', '전북', '전라북도 정읍시 신성리 일대', '정읍 신성리, 1903년 김원영 신부가 부임하며 설립된 본당이 있던 자리. 전주교구 초기 정읍·태인 지역 신앙 공동체의 중심이 되었던 이곳은 세월이 흐르며 규모가 작아져 오늘날에는 인근 본당의 관할 공소로 남아있다. 화려하진 않지만, 전북 내륙 깊숙이까지 신앙이 퍼져나간 역사를 소박하게 증언하는 자리다.', '1903년 김원영 신부가 설립한 정읍 신성리 본당 터, 현재는 공소로 남아있다.', '신성 공소 - 정읍 신앙의 옛 중심', '전북 정읍 신성공소, 1903년 설립된 옛 신성리 본당 터. 전북 내륙 신앙 확산의 흔적이 남은 공소.', '평온', NULL, NULL),
  ('안대동 성당지', '성당', '전주', '전북', '전라북도 익산시 안대동 일대', '익산 안대동, 1878년 블랑 신부와 두세 신부가 처음 복음을 전한 이래 호남 천주교 포교의 역사가 깊은 자리. 1910년 나바위본당 베르모렐 신부가 익산과 임피 지역 신자들을 위해 본당 신설을 계획해 그해 10월 19일 안대동본당이 문을 열었고, 성모 성탄을 주보로 삼았다. 1914년 사제가 없어 잠시 문을 닫고 나바위본당에 합병되었다가, 사제 수급이 원활해진 1938년에야 다시 복원되었다. 지금은 자취만 남은 이 성당터는 익산 지역 초기 본당사의 굴곡을 보여준다.', '1878년 블랑 신부의 전교로 시작된 익산 안대동. 1910년 안대동본당 설립, 1914년 폐쇄 후 1938년 복원.', '안대동 성당지 - 익산 초기 본당의 자취', '전북 익산 안대동성당지, 1910년 설립된 익산·임피 지역 옛 본당터. 폐쇄와 복원을 거친 초기 본당사의 흔적.', '평온', NULL, NULL),
  ('어은 공소', '성당', '전주', '전북', '전라북도 진안군 진안읍 죽산리 453', '진안 죽산리, 병인박해 이후 충청도에서 전라도 산간으로 피신한 신자들이 세운 신앙 공동체. 1888년 공소로 출발해 1900년 김양홍 신부가 부임하며 본당으로 승격했다. 1901년 초가지붕 목조 건물로 지어졌다가 신자가 1,400명까지 늘며 1904년과 1909년 두 차례 증축되었고, 1909년 지어진 건물은 남녀를 가운데 통로로 나눈 당시 좌석 배치를 그대로 간직해 2002년 국가등록문화재 제28호로 지정되었다. 산골 오지라는 이유로 1922년 본당이 한덕으로 옮겨간 뒤에도 공소로 남아 신앙의 자리를 지키고 있다.', '1888년 설립된 산간 교우촌 공소. 1909년 신축 건물은 국가등록문화재 제28호로 지정.', '어은 공소 - 산골에 세운 신앙 공동체', '전북 진안 어은공소, 병인박해 이후 산간에 피신한 신자들이 세운 공동체. 국가등록문화재 제28호.', '평온', NULL, NULL),
  ('여산 순교 성지', '순교성지', '전주', '전북', '전라북도 익산시 여산면 여산리 445-2 (동헌)', '익산 여산면, 전주교구의 제2성지라 불리는 이곳에는 1868년 무진박해 때 고산·금산·진산의 산골에 숨어 지내던 신자들이 끌려와 굶주림과 혹독한 형벌 속에 순교했다. 최소 스물다섯 명이 이곳에서 참수와 교수형, 백지사형이라는 잔혹한 방식으로 목숨을 잃었다. 백지사형은 두 손을 뒤로 묶고 상투를 그 손에 매어 얼굴이 위를 향하게 한 뒤, 얼굴에 물을 뿌리고 백지를 겹겹이 발라 질식시키는 방법이었다. 동헌과 옥터, 숲정이, 다리 밑까지 여산 곳곳이 순교의 자리였는데, 1959년 설립된 여산성당이 동헌 아래 땅을 사들여 백지사터 기념 공간과 순교탑, 십자가의 길을 조성했다.', '1868년 무진박해 때 최소 25명이 순교한 여산 관아. 백지사형 등 잔혹한 처형이 자행된 전주교구 제2성지.', '여산 순교 성지 - 백지사형의 잔혹한 기억', '전북 익산 여산순교성지, 1868년 무진박해 때 25명 이상이 백지사형 등으로 순교한 전주교구 제2성지.', '치유', NULL, NULL),
  ('전라 감영', '역사사적지', '전주', '전북', '전라북도 전주시 완산구 (옛 전라북도청 자리)', '전주 옛 전라북도청 자리, 2020년 일부가 복원된 조선시대 전라도 행정의 중심지. 관찰사의 명에 따라 이곳 전주부영과 중진영, 전주 옥에서는 백여 년에 걸쳐 수많은 천주교 신자들이 체포되고 문초당했다. 1791년 신해박해 때 한국 첫 순교자 윤지충 바오로와 권상연 야고보, 1801년 신유박해 때 유항검 아우구스티노 일가와 윤지헌 프란치스코, 1827년 정해박해 때 이경언 바오로, 1839년 기해박해 때 신태보 베드로 등, 1866년 병인박해 때 손선지 베드로를 비롯한 일곱 명까지—전주 순교사의 굵직한 장면들이 모두 이 감영 뜰에서 펼쳐졌다.', '조선시대 전라도 행정 중심지, 1791~1866년 여러 박해에 걸쳐 천주교 신자들이 체포·문초·처형된 곳. 2020년 일부 복원.', '전라 감영 - 전주 순교사의 무대', '전북 전주 전라감영, 신해박해부터 병인박해까지 백여 년 순교자들이 문초당한 조선시대 행정 중심지. 2020년 복원.', '치유', NULL, NULL),
  ('초록바위 순교 터', '순교성지', '전주', '전북', '전라북도 전주시 완산구 동완산동 산 1-9', '전주천변 싸전다리 인근, 열네 살 소년들이 강물에 잠긴 비극의 자리. 1866년 병인박해 때 서소문 밖에서 순교한 남종삼 요한의 열네 살 아들 명희와 순교자 홍봉주 토마스의 아들은 어린 나이에도 전주 옥에 갇혔다가, 1867년 가을 끝내 이 초록바위 아래 강물에 수장되어 순교했다. 나이 어린 자녀에게까지 미친 박해의 잔혹함이 이 강가에 새겨져 있다. 2006년 전주교구는 이 두 소년을 기리는 모자이크 벽화를 강변 도로변에 세웠다.', '1867년 남종삼 요한의 아들 명희 등 두 소년이 수장되어 순교한 자리. 2006년 모자이크 벽화 조성.', '초록바위 순교 터 - 강물에 잠긴 두 소년', '전북 전주 초록바위, 남종삼 요한의 아들 등 두 소년이 1867년 수장되어 순교한 전주천변 자리.', '위로', NULL, NULL),
  ('전주 숲정이 성지', '순교성지', '전주', '전북', '전라북도 전주시 덕진구 진북동 1034-13', '전주 공북로, 숲이 울창하다 하여 숲머리라고도 불린 이곳은 조선시대 군사들이 무술을 연마하던 자리였다가 박해가 시작되며 천주교 신자들의 처형장이 되었다. 1801년 신유박해, 1839년 기해박해, 1866년 병인박해에 걸쳐 수많은 순교자가 이곳에서 목숨을 잃었는데, 그중에는 정결한 부부의 삶을 살다 함께 순교한 동정부부 유중철 요한과 이순이 루갈다도 있었다. 1930년대 이 땅을 매입해 보존하기 시작한 이래 1935년 십자가 기념비, 1968년 순교자 기념탑이 세워졌고, 1992년 도시 개발로 자리를 옮겨 2004년 성모상과 십자가의 길을 더했다.', '1801~1866년 여러 박해에 걸친 순교지, 동정부부 유중철 요한·이순이 루갈다 등이 순교. 전라북도 기념물 제71호(1984).', '전주 숲정이 성지 - 동정부부가 함께 지킨 순교', '전북 전주 숲정이성지, 세 차례 박해에 걸친 순교지. 동정부부 유중철 요한과 이순이 루갈다가 함께 순교한 자리.', '치유', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('순교자의 딸 유섬이 묘', '순교성지', '마산', '경남', '경상남도 거제시 일대 (유배지 인근)', '거제, 아홉 살 어린 나이에 관노비로 유배된 한 소녀가 일흔한 살까지 살아낸 자리. 호남의 사도라 불린 순교자 유항검 아우구스티노의 딸 섬이는 1801년 신유박해로 아버지가 전주 남문 밖에서 능지처참형에 처해지자, 죄인의 자식이라는 이유로 경상도 거제부로 유배되었다. 관비의 신분으로 살면서도 그녀는 정절을 지켜 평생 혼인하지 않았고, 스스로 토굴을 짓고 그 안에서 25년을 하느님과 함께 지내는 고행의 삶을 살았다. 이 조용한 묘소는 아버지의 순교를 온몸으로 이어받은 딸의 신앙을 오늘도 증언한다.', '순교자 유항검 아우구스티노의 딸 유섬이(1792~1863경, 향년 71세)가 거제 관비로 유배되어 평생 정절을 지킨 자리.', '순교자의 딸 유섬이 묘 - 토굴에서 지킨 25년의 정절', '경남 거제, 순교자 유항검의 딸 유섬이가 관비로 유배되어 평생 정절을 지킨 묘소. 25년 토굴 고행의 신앙.', '위로', NULL, NULL),
  ('창원 웅천 왜성', '역사사적지', '마산', '경남', '경상남도 창원시 진해구 남문동 (웅천왜성)', '진해만이 내려다보이는 웅천 왜성, 임진왜란의 상흔 속에 예상 밖의 신앙 이야기가 숨어 있다. 천주교 신자였던 왜장 고니시 유키나가는 이곳 웅천성에 주둔하며 일본 예수회에 밀사를 보내 사제를 요청했고, 1593년 12월 28일 스페인 출신 세스페데스 신부가 이 성에 도착해 약 일 년간 머물며 왜군들에게 미사를 봉헌하고 세례를 주었다. 조선 땅에 서양인 성직자가 처음 발을 디딘 사건이었으나, 그 대상이 침략군이었다는 역사의 아이러니가 이 성터에 함께 새겨져 있다.', '1593년 스페인 출신 세스페데스 신부가 약 1년간 머물며 미사를 봉헌한 곳. 서양인 성직자의 한반도 첫 체류 기록.', '창원 웅천 왜성 - 서양 신부가 처음 밟은 조선 땅', '경남 창원 웅천왜성, 1593년 스페인 신부 세스페데스가 머물며 미사를 봉헌한 서양 성직자의 한반도 첫 체류지.', '감사', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('강릉 대도호부 관아', '역사사적지', '춘천', '강원', '강원도 강릉시 용강동 58-1', '강릉 원도심, 고려·조선시대 지방관이 머물던 관아 건물이 오늘도 옛 모습을 지키고 있다. 1868년 병인박해 때 심능석 스테파노와 이유일 안토니오 등 신자들이 이곳으로 끌려와 제대로 된 심문조차 없이 혹독한 고문 끝에 참수되었다. 세금과 재판 등 지방 행정의 일곱 가지 업무를 처리하던 칠사당은 강원도 유형문화재 제7호로 지정되어 있고, 고려시대 양식을 간직한 임영관 삼문은 국보 제51호로 그 정교한 조각이 남아있다.', '1868년 병인박해 때 심능석 스테파노 등이 순교한 옛 강릉 관아. 칠사당은 강원도 유형문화재 제7호, 임영관 삼문은 국보 제51호.', '강릉 대도호부 관아 - 국보 삼문과 순교의 기억', '강원 강릉 대도호부관아, 병인박해 순교자들이 처형된 옛 관아. 국보 제51호 임영관 삼문이 남아있는 성지.', '위로', NULL, NULL),
  ('겟세마니 피정의 집', '순례길', '춘천', '강원', '강원도 인제군 남면 부평리', '인제 깊은 산골, 조용히 묵상하며 기도할 수 있는 춘천교구의 피정의 집. 세상의 소음을 벗어나 하루쯤 침묵 속에 머물고 싶은 이들이 찾는 이곳은, 예수님이 마지막 밤을 홀로 기도하신 겟세마니 동산의 이름을 따랐다. 화려한 볼거리는 없지만, 강원도 산자락의 고요함 속에서 자신을 돌아보는 묵상과 쉼의 시간을 마련해준다.', '춘천교구가 운영하는 피정의 집. 인제 산골에 자리해 묵상과 쉼을 위한 공간으로 이용된다.', '겟세마니 피정의 집 - 인제 산골의 침묵과 기도', '강원 인제 겟세마니피정의집, 춘천교구가 운영하는 산중 피정 시설. 침묵 속에서 묵상하는 쉼의 공간.', '평온', NULL, NULL),
  ('곰실 공소', '교우촌', '춘천', '강원', '강원도 춘천시 동내면 고은리 439-1', '춘천 동내면, 상주 신부 없이도 홀로 신앙을 키워간 한 평신도의 헌신이 낳은 공동체. 엄주언 마르티노는 천주교 서적을 접한 뒤 가족과 함께 이곳으로 옮겨와 신앙을 공부했고, 고향으로 돌아와 이웃에게 복음을 전했다. 그의 선행에 감화된 마을 사람들이 하나둘 신자가 되었고, 물구비·춘천·화천·양구를 돌던 정규하 신부는 이곳에서만 해마다 마흔에서 쉰 명씩 세례를 줄 정도였다. 1920년 본당이 되었던 이 공소는 오늘날 춘천 주교좌 죽림동성당의 모태가 되었다.', '평신도 엄주언 마르티노의 헌신으로 형성된 교우촌. 1920년 본당 승격, 죽림동 주교좌성당의 모태.', '곰실 공소 - 평신도가 일군 춘천 신앙의 모태', '강원 춘천 곰실공소, 평신도 엄주언 마르티노가 일군 교우촌. 죽림동 주교좌성당의 뿌리가 된 공소.', '새출발', NULL, NULL),
  ('금광리 공소', '교우촌', '춘천', '강원', '강원도 강릉시 구정면 어단리 417-5', '강릉 구정면, 영동 지방 천주교 신앙의 모태가 된 산골 공소. 1866년 병인박해 이후 이곳과 내곡동 일대로 옮겨온 신자들은 옹기를 굽고 농사를 지으며 신앙을 이어갔다. 배를 타고 원산과 안변에서 사제들이 찾아와 성사를 주었고, 1887년 공소로 자리 잡았다. 1921년 잠시 본당이 되었다가 1923년 접근이 좋은 주문진으로 옮겨가며 다시 공소로 남았다. 오늘날에는 노암동성당 관할 공소로 신앙의 자리를 지키고 있다.', '1887년 설립된 영동 지방 천주교의 모태 공소. 병인박해 이후 형성된 신앙 공동체.', '금광리 공소 - 영동 신앙의 모태', '강원 강릉 금광리공소, 병인박해 이후 형성된 영동 지방 천주교의 모태. 옹기 굽던 신자들의 신앙 공동체.', '평온', NULL, NULL),
  ('라 파트리치오 신부 순교 터', '순교성지', '춘천', '강원', '강원도 강릉시 구정면 어단리 (금광리 공소 인근)', '강릉 금광리 공소 인근, 아일랜드 출신 선교사가 이 땅에서 순교한 자리. 성 골롬반 외방선교회 소속 라 파트리치오(패트릭 라일리) 신부는 6·25전쟁이 터지던 해 이 지역에서 사목하다 공산군에게 붙잡혀 세상을 떠났다. 그의 유해는 춘천교구 죽림동 순교성지에 안장되어 있으며, 현재 홍용호 프란치스코 보르지아 주교와 동료 80위 시복 안건의 일부로 시복 절차가 진행되고 있다. 전쟁의 혼란 속에서도 사목지를 지킨 외국인 선교사의 헌신이 이 자리에 깃들어 있다.', '성 골롬반 외방선교회 라 파트리치오(패트릭 라일리) 신부가 1950년 한국전쟁 때 순교한 자리. 홍용호 주교와 동료 80위 시복 추진 중.', '라 파트리치오 신부 순교 터 - 아일랜드 신부의 마지막 사목지', '강원 강릉 라파트리치오 신부 순교터, 6·25전쟁 때 순교한 아일랜드 선교사의 자취. 홍용호 주교와 동료 80위 시복 추진 중.', '위로', NULL, NULL),
  ('묵호 성당', '성당', '춘천', '강원', '강원도 동해시 묵호진동 일대', '동해 묵호항, 바다의 별 마리아를 주보로 삼은 옛 항구의 성당. 1948년 6월 춘천교구 첫 본당으로 승격된 이곳에 이듬해 성 골롬반 외방선교회 소속 패트릭 라일리 신부가 2대 주임으로 부임했다. 사목을 시작한 지 채 일 년도 되지 않아 6·25전쟁이 터졌지만, 신자들이 피난을 권했음에도 라일리 신부는 양 떼를 두고 목자만 떠날 수 없다며 묵호에 남았다가 공산군에게 순교했다. 1954년 삼척본당 관할 공소로 격하되었다가 7년 만에 다시 본당으로 복귀했고, 1974년 성당 마당에 라 파트리치오 신부 순교비가 세워졌다.', '1948년 승격된 춘천교구 첫 본당. 2대 주임 라 파트리치오(패트릭 라일리) 신부가 1950년 한국전쟁 때 순교. 1974년 순교비 건립.', '묵호 성당 - 양 떼를 지킨 목자의 순교', '강원 동해 묵호성당, 춘천교구 첫 본당이자 라 파트리치오 신부가 순교한 옛 항구의 성당. 1974년 순교비 건립.', '위로', NULL, NULL),
  ('소양로 성당', '성당', '춘천', '강원', '강원도 춘천시 소양로 2가 78-1', '춘천 소양로, 부채꼴로 둘러앉아 제대를 가까이서 바라볼 수 있는 독특한 구조의 성당. 1950년 1월 5일 중림동본당에서 분리되어 설립된 이 본당의 초대 주임 콜리어 안토니오 신부는 6·25전쟁이 터지자 성체를 안전한 곳으로 옮기고 신자들에게 피난을 권한 뒤, 정작 자신은 주교좌성당으로 이동하던 중 6월 27일 복사 김가브리엘과 함께 공산군에게 붙잡혀 순교했다. 성 골롬반 외방선교회 소속으로는 한국전쟁 최초의 순교자였다. 전쟁으로 지연되었던 성당 건축은 1956년 90평 규모로 완공되어 2005년 국가등록문화재 제161호로 지정되었다.', '콜리어 안토니오 신부가 1950년 한국전쟁 때 순교한 성당. 성 골롬반 외방선교회 한국전쟁 첫 순교자. 국가등록문화재 제161호.', '소양로 성당 - 부채꼴 성전과 콜리어 신부의 순교', '강원 춘천 소양로성당, 콜리어 안토니오 신부가 한국전쟁 때 순교한 성당. 부채꼴 구조의 국가등록문화재 제161호.', '치유', NULL, NULL),
  ('양양 성지', '순교성지', '춘천', '강원', '강원도 양양군 양양읍 성내리 8-1', '양양읍, 1921년 공소에서 본당으로 승격된 이 성당은 병인박해 때 피신해 온 신자들의 정착에서 신앙이 시작되었다. 6·25전쟁 때 이광재 티모테오 신부는 수많은 성직자와 수도자, 신자들이 남쪽으로 안전하게 피신하도록 도왔으나, 정작 자신은 1950년 6월 24일 공산군에게 붙잡혀 그해 10월 9일 순교했다. 양떼를 위해 목숨을 내놓은 선한 목자의 삶이었다. 1983년 순교 기념비가 세워졌고 2017년 성지로 선포되었으며, 그는 홍용호 주교와 동료 80위 시복 안건에 포함되어 있다.', '이광재 티모테오 신부가 1950년 한국전쟁 때 순교한 성당. 2017년 성지 선포, 홍용호 주교와 동료 80위 시복 추진 중.', '양양 성지 - 선한 목자 이광재 신부의 순교', '강원 양양성지, 이광재 티모테오 신부가 한국전쟁 때 순교한 성당. 2017년 성지로 선포.', '위로', NULL, NULL),
  ('죽림동 순교 성지', '주교좌성당', '춘천', '강원', '강원도 춘천시 죽림동 38', '춘천 죽림동, 춘천교구 주교좌성당이자 순교자들의 안식처. 1920년 곰실 공소가 본당으로 승격되며 시작된 이 성당은 1949년 퀸란 주교 재임 때 착공되었으나 한국전쟁으로 공사가 중단되고 유엔군 반격 작전 중 건물이 훼손되는 아픔을 겪었다. 미군과 교황청의 지원으로 1953년 대부분의 공사를 마쳤다. 1998~1999년 대대적으로 개보수했고, 2013~2014년 성역화 사업을 거쳐 2017년 한국전쟁 때 희생된 이들이 잠든 교구 순교자 묘역이 성지로 선포되었다.', '1920년 곰실 공소가 승격된 춘천교구 주교좌성당. 한국전쟁으로 훼손·재건. 2017년 교구 순교자 묘역이 성지로 선포.', '죽림동 순교 성지 - 춘천교구의 심장이자 순교자 묘역', '강원 춘천 죽림동순교성지, 춘천교구 주교좌성당이자 한국전쟁 순교자들이 잠든 교구 묘역. 2017년 성지 선포.', '치유', NULL, NULL),
  ('춘천교구 주교관과 교육원', '역사사적지', '춘천', '강원', '강원도 춘천시 죽림동 (주교좌성당 인근)', '춘천 원도심, 아일랜드풍 건축이 이국적인 정취를 자아내는 두 건물. 강원도 선교를 담당하던 성 골롬반 외방선교회가 1958년 세운 주교관은 햇빛이 아쉬운 아일랜드의 풍습대로 유별나게 서향으로 지어졌다. 이듬해 완공된 교육원 건물은 본래 영원한 도움의 성모수도회 수련소로 지어져 강원 지역 선교를 도울 수녀들을 길러냈고, 이후 여대생 기숙사를 거쳐 1977년부터 춘천교구 신앙교육의 산실인 가톨릭교육원으로 이름을 바꾸었다. 두 건물 모두 2019년 국가등록문화재로 등록되어 그 건축사적 가치를 인정받았다.', '성 골롬반 외방선교회가 1958~1959년 세운 아일랜드풍 건물. 주교 거처와 수녀 양성소로 쓰이다 2019년 국가등록문화재 등록.', '춘천교구 주교관과 교육원 - 아일랜드풍 건축의 유산', '강원 춘천 주교관과 교육원, 성 골롬반 외방선교회가 세운 아일랜드풍 건물. 2019년 국가등록문화재로 등록된 신앙교육의 산실.', '감사', NULL, NULL),
  ('포천 순교 성지', '순교성지', '춘천', '경기', '경기도 포천시 군내면 구읍리 723-3', '포천, 1801년 신유박해 때 순교한 복자 홍교만 프란치스코 하비에르와 그 아들 홍인 레오의 신앙이 이어진 자리. 아들이라는 이유로 죽음을 면하고 포천으로 옮겨졌던 홍인 레오는 결국 1802년 1월 30일 포천 장터에서 순교했다. 1900년 해룡마을에 첫 공소가 세워졌고, 6·25전쟁 참전 장군이자 독실한 신자였던 이한림 가브리엘 장군의 뜻으로 1955년 화강암 석조 성당이 지어져 퀸란 주교의 축성을 받았다. 1990년 방화로 불탄 옛 성당은 2006년 국가등록문화재 제271호로 지정되었고, 2014년 부자가 함께 시복되며 그해 9월 순교터가 성지로 선포되었다.', '복자 홍교만·홍인 레오 부자의 순교 연고지. 1955년 이한림 장군 뜻으로 지어진 석조 성당(국가등록문화재 제271호). 2014년 성지 선포.', '포천 순교 성지 - 부자가 함께 지킨 신앙', '경기 포천 순교성지, 복자 홍교만·홍인 레오 부자의 순교 연고지. 1955년 지어진 석조 성당, 2014년 성지 선포.', '위로', NULL, NULL),
  ('홍천 성당', '성당', '춘천', '강원', '강원도 홍천군 홍천읍 희망리 105', '홍천, 돌과 돌 사이 홈을 깎아 맞물리게 짠 독특한 공법으로 지어진 1950년대 석조 성당. 1902~1903년 무렵 송정 공소로 처음 기록에 등장한 이 지역 신앙은 1923년 정식 본당으로 출발해 1936년 지금 자리로 옮겨왔다. 한국전쟁으로 목조 성당이 무너지자 최동오 신부가 1953년 재건을 시작했고, 억류와 송환을 겪은 크로스비 필립 신부가 1954년 부임해 이듬해 미군 공병대와 신자들의 도움으로 석조 성당과 사제관을 완성했다. 마루 밑에 습기를 막는 새끼줄 뭉치를 깔아두는 등 세심한 설계로 오늘날까지 원형이 잘 보존되어 2005년 국가등록문화재 제162호로 지정되었다.', '1923년 설립, 1955년 완공된 석조 성당. 크로스비 필립 신부가 재건을 주도. 국가등록문화재 제162호.', '홍천 성당 - 돌과 돌을 짜맞춘 1950년대 성전', '강원 홍천성당, 한국전쟁 후 1955년 완공된 석조 성당. 정교한 돌 공법이 남은 국가등록문화재 제162호.', '감사', NULL, NULL)
insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('가톨릭 대학교 성신 교정', '역사사적지', '서울대', '서울', '서울시 종로구 창경궁로 296-12 (혜화동 90-1)', '대학로 뒤편 혜화동, 미래의 사제들이 기도하는 성당 지하에 한국 최초의 사제 김대건 안드레아 신부의 유해가 모셔져 있다. 1855년 제천 배론에 세운 성 요셉 신학교가 병인박해로 문을 닫은 뒤, 1885년 여주 부엉골에서 다시 문을 연 예수성심신학교가 1887년 서울 용산으로, 이후 이곳 혜화동으로 자리를 옮기며 지금에 이르렀다. 사제 성소의 못자리라 불리는 이곳에서 백 년 넘게 한국천주교회를 이끌 사제들이 길러지고 있다.', '1855년 배론 신학교에서 이어진 한국 사제 양성의 역사가 집약된 성당. 김대건 안드레아 신부의 유해 봉안.', '가톨릭대학교 성신교정 성당 - 사제 성소의 못자리', '서울 혜화동 가톨릭대학교 성신교정 성당, 김대건 신부의 유해가 모셔진 한국 사제 양성의 산실.', '감사', NULL, NULL),
  ('가회동 성당', '성당', '서울대', '서울', '서울시 종로구 가회동 30-3', '북촌 한옥마을 한편, 한옥과 서양식이 어우러진 성당에 한국천주교회 최초의 미사가 봉헌된 자리가 숨어 있다. 1795년 부활 대축일, 조선에 몰래 들어온 첫 외국인 사제 주문모 야고보 신부가 최인길의 집에서 한국 땅 첫 미사를 봉헌했고, 이후에는 초기 여성 지도자 강완숙의 집에서 은밀히 사목 활동을 이어갔다. 1949년 설립된 본당은 2013년 완공, 2014년 부활절에 축성된 새 성당에서 그날의 역사를 1층 전시실로 만나볼 수 있다.', '1795년 주문모 신부가 한국 최초의 미사를 봉헌한 자리. 1949년 본당 설립, 2014년 새 성당 봉헌.', '가회동 성당 - 한국 첫 미사가 봉헌된 자리', '서울 북촌 가회동성당, 1795년 주문모 신부가 한국 최초의 미사를 봉헌한 자리. 한옥과 서양식이 어우러진 성전.', '새출발', NULL, NULL),
  ('경기 감영 터', '순교성지', '서울대', '서울', '서울시 서대문구 미근동 (강북삼성병원 일대)', '서대문 인근, 지금은 병원 건물이 들어선 이 자리에 한때 경기도 행정을 총괄하던 감영이 있었다. 조선시대 한양 인근에서 체포된 천주교 신자들이 이곳으로 압송되어 문초와 형벌을 받았다. 서울 순례길 생명의 길 코스가 지나는 이 자리는 형조 터, 우포도청 터와 더불어 순교자들이 마지막 신앙을 증거한 도심 속 순례지로 꼽힌다.', '조선시대 경기도 행정 중심지, 체포된 천주교 신자들의 문초·형벌지. 서울 순례길 생명의 길 코스에 포함.', '경기 감영 터 - 서울 도심에 남은 순교의 자리', '서울 서대문 경기감영터, 조선시대 경기도 행정 중심지이자 천주교 순교자들의 문초지. 서울 순례길 생명의 길 코스.', '위로', NULL, NULL),
  ('광화문 124위 시복 터', '역사사적지', '서울대', '서울', '서울시 종로구 세종로 (광화문광장)', '광화문광장, 조선 왕조 첫 궁궐인 경복궁을 마주한 이 넓은 광장에서 2014년 8월 16일 프란치스코 교황이 집전한 124위 순교자 시복식이 열렸다. 1925년 로마에서 79위, 1968년 24위가 시복된 데 이은 세 번째 시복식이자, 교황이 직접 방한해 집전한 최초의 사례였다. 조선시대 의금부와 포도청, 형조 등 순교자들이 갇히고 처형되던 관아 터를 마주한 이 광장에서 시복식을 연 것은 그들의 명예를 되찾는다는 의미를 담고 있었다. 약 20만 명의 신자가 함께한 이날, 대한민국은 순교자의 땅으로 다시 한번 세계에 알려졌다.', '2014년 8월 16일 프란치스코 교황이 집전한 124위 순교자 시복식 장소. 교황이 직접 집전한 최초의 방한 시복식.', '광화문 124위 시복 터 - 교황이 직접 집전한 시복식', '서울 광화문광장, 2014년 프란치스코 교황이 124위 순교자를 시복한 자리. 약 20만 명이 함께한 역사적 미사.', '감사', NULL, NULL),
  ('광희문 성지', '순교성지', '서울대', '서울', '서울특별시 중구 신당동 228-17', '중구와 성동구 경계, 도성 안 시신을 밖으로 내보내던 수구문이자 시구문이었던 작은 문. 박해 시대 이곳을 통해 나간 순교자들의 시신은 제대로 묻히지도 못한 채 문밖에 버려지곤 했다. 1801년부터 1879년까지 이곳에서 시신이 유기되거나 묻힌 순교자만 794명, 그중 740명이 1866년 병인박해 이후에 집중되어 있다. 서울 309명, 충청 213명, 경기 158명 등 전국 각지 출신이 뒤섞인 이 자리는 산 자와 죽은 자가 함께 머무는 카타콤바로 불린다. 성 최경환 프란치스코, 복자 송백돌 베드로 등이 이곳과 인연이 깊다.', '1801~1879년 794명의 순교자 시신이 유기·안장된 시구문. 성 최경환 프란치스코 등이 연고. 병인박해 이후 순교자가 대다수.', '광희문 성지 - 시신이 버려진 시구문의 카타콤바', '서울 중구 광희문성지, 794명의 순교자 시신이 유기된 옛 시구문. 산 자와 죽은 자가 함께 머무는 카타콤바.', '치유', NULL, NULL),
  ('김범우의 집터', '역사사적지', '서울대', '서울', '서울시 중구 명동1가 일대 (명례방 터)', '명동 번화가 한복판, 지금은 흔적조차 없는 이 자리에 한국천주교회 최초의 신앙 모임이 있었다. 역관이었던 김범우 토마스는 자신의 집을 이승훈, 정약전·정약용 형제, 권일신 등이 모이는 장소로 내주었다. 1785년 봄, 형조의 관리들이 도박 단속을 나왔다가 우연히 이 모임을 발견하며 을사추조적발사건이 벌어졌고, 김범우는 유배형에 처해져 이듬해 세상을 떠났다. 그의 집이 있던 명례방은 이후 한국천주교회 첫 신앙 공동체의 이름으로 남았다.', '김범우 토마스의 집터, 1785년 을사추조적발사건이 벌어진 명례방 공동체의 중심지.', '김범우의 집터 - 명례방 신앙 공동체의 중심', '서울 명동 김범우의 집터, 한국천주교회 초기 명례방 공동체가 모이던 자리. 1785년 을사추조적발사건의 현장.', '새출발', NULL, NULL),
  ('노고산 성지', '순교성지', '서울대', '서울', '서울시 마포구 신수동 1 (서강대학교 가브리엘관 앞)', '마포 서강대학교 가브리엘관 앞, 순교자들이 잠시 몸을 뉘었던 언덕. 1839년 기해박해 때 새남터에서 순교한 앵베르 주교와 모방·샤스탕 신부의 유해를 신자들이 몰래 거두어 이곳 노고산에 숨겨 묻었다. 이후 수십 년에 걸쳐 여러 순교자들의 유해가 이 일대에서 발견되고 이장되기를 거듭하다 1967년 절두산순교성지로 옮겨졌다. 예수회가 운영하는 서강대학교가 이 자리에 들어서며, 2009년 세 성직자를 기리는 기념석이 세워졌다.', '1839년 기해박해 순교자 앵베르 주교 등의 유해가 4년간 숨겨져 있던 자리. 2009년 서강대학교가 기념석 건립.', '노고산 성지 - 순교자들이 숨겨진 언덕', '서울 마포 노고산성지, 앵베르 주교 등 기해박해 순교자들의 유해가 숨겨졌던 자리. 서강대 교정의 기념석.', '위로', NULL, NULL),
  ('삼성산 성지', '순교성지', '서울대', '서울', '서울시 관악구 신림동 산54-14', '관악산 자락, 세 명의 성인이 묻혔던 산이라 하여 삼성산이라는 이름을 얻었다. 1839년 기해박해 때 새남터에서 순교한 앵베르 주교, 모방 신부, 샤스탕 신부의 유해를 평신도 박 바오로가 몰래 거두어 이곳에 안장했고, 그의 아들 박순집이 훗날 그 자리를 증언하며 1901년 명동대성당 지하로의 이장이 이루어졌다. 조선에서 활동한 지 채 일 년 만에 신자 수를 9천 명까지 늘렸던 세 사람의 헌신을 기려 1970년과 1981년 기념비가 세워졌고, 1984년 한국천주교 200주년에 이들은 성인으로 시성되었다.', '1839년 기해박해 순교자 앵베르 주교·모방·샤스탕 신부의 유해가 1843~1901년 안장되었던 산. 1984년 시성.', '삼성산 성지 - 세 성인이 잠들었던 산', '서울 관악구 삼성산성지, 기해박해 순교자 앵베르 주교 등 세 성인의 유해가 1901년까지 안장된 산.', '치유', NULL, NULL),
  ('석정 보름 우물', '역사사적지', '서울대', '서울', '서울시 종로구 계동 (가회동성당 인근)', '북촌 계동, 15일은 맑고 15일은 흐려진다 하여 보름우물이라는 이름을 얻은 옛 우물이 있다. 서울에 상수도가 놓이기 전 계동 주민들의 중요한 식수원이었던 이곳에서, 1794년 압록강을 건너 조선에 잠입한 첫 외국인 사제 주문모 야고보 신부는 최인길의 집에 숨어 지내며 이 우물물로 몰래 세례를 주었다. 강완숙의 도움으로 신자들에게 세례성사가 이어졌고, 김대건 안드레아 신부도 한때 북촌에 숨어 지내며 이 물을 성수로 썼다고 전해진다.', '주문모 신부가 신자들에게 몰래 세례를 준 우물. 김대건 신부도 성수로 사용했다고 전해짐.', '석정 보름 우물 - 몰래 세례를 준 북촌의 우물', '서울 북촌 계동 석정보름우물, 주문모 신부가 신자들에게 세례를 준 옛 우물. 김대건 신부도 성수로 썼다는 이야기가 전해진다.', '평온', NULL, NULL),
  ('용산 성직자 묘역', '순교성지', '서울대', '서울', '서울시 용산구 원효로4가 (용산신학교 인근)', '용산 신학교 인근, 조선을 위해 순교한 외국인 성직자들의 유해가 한때 안식했던 자리. 1839년 기해박해 때 새남터에서 순교한 앵베르 주교와 모방·샤스탕 신부의 유해는 삼성산에 임시로 묻혔다가, 1885~1887년 포아넬 신부의 조사를 거쳐 1901년 이곳 용산 예수성심신학교 성직자 묘역으로 옮겨졌다. 그해 11월 다시 명동대성당 지하로 이장되기까지, 신학교의 교수와 학생들이 해마다 이곳을 찾아 무덤을 돌보았다고 전해진다.', '1901년 삼성산에서 옮겨온 순교 성직자들의 유해가 잠시 안장되었던 용산신학교 묘역. 같은 해 명동대성당 지하로 재이장.', '용산 성직자 묘역 - 순교자들이 잠시 머문 신학교 묘역', '서울 용산 성직자 묘역, 1901년 삼성산에서 옮겨온 순교 성직자들의 유해가 잠시 안장되었던 용산신학교 묘역.', '위로', NULL, NULL),
  ('용산 예수 성심 신학교', '역사사적지', '서울대', '서울', '서울시 용산구 원효로 4가 1-1', '용산 원효로, 순교자들의 유해를 모셨던 한국 최초의 근대식 신학교 성당. 1855년 제천 배론에 세워진 성 요셉 신학교가 병인박해로 문을 닫은 뒤, 1885년 여주 부엉골에서 예수성심신학교로 다시 문을 열고 1887년 이곳 용산으로 옮겨와 1902년 성당을 지었다. 한국 첫 사제 김대건 안드레아 신부를 비롯해 여덟 명의 조선대목구장 주교들의 유해가 한때 이곳에 모셔졌고, 일제에 의해 1942년 문을 닫기까지 백여 명의 사제를 길러냈다. 1982년 사적 제255호로 지정되어 2010~2011년 복원되었다.', '1887년 이전, 1902년 성당 완공된 한국 근대 신학교. 김대건 신부와 역대 주교들의 유해가 한때 봉안. 사적 제255호.', '용산 예수 성심 신학교 - 순교자들이 잠시 머문 근대 신학교', '서울 용산 예수성심신학교, 김대건 신부 등 순교자들의 유해가 봉안되었던 한국 근대 신학교. 사적 제255호.', '감사', NULL, NULL),
  ('우포도청 터', '순교성지', '서울대', '서울', '서울시 종로구 청진동 (광화문우체국~일민미술관 사이)', '광화문우체국에서 일민미술관 사이 청진동, 한양 서·북부를 관할하던 우포도청이 있던 자리. 1784년 한국천주교회가 창립된 뒤 신자를 색출하는 일은 좌·우포도청의 주요 임무가 되었다. 수많은 순교자가 이곳에서 체포되어 취조받고 고문당했으며, 오늘날 이 자리는 형조 터, 경기감영 터와 함께 서울 순례길 생명의 길 코스의 주요 지점으로 이어진다.', '조선시대 한양 서·북부를 관할한 포도청, 천주교 신자 색출·체포·고문의 중심지. 서울 순례길 생명의 길 코스.', '우포도청 터 - 신자를 색출하던 포도청의 자리', '서울 종로 우포도청터, 조선시대 천주교 신자 체포·고문의 중심지. 서울 순례길 생명의 길 코스에 포함.', '위로', NULL, NULL),
  ('의금부 터', '순교성지', '서울대', '서울', '서울시 종로구 종로1가 (종각역 1번 출구 앞)', '종각역 1번 출구 앞, 조선시대 국왕 직속의 중죄인 심문 기관이 있던 자리. 1839년 기해박해 때 앵베르 주교와 모방·샤스탕 신부, 1866년 병인박해 때 베르뇌 주교와 브르트니에르 신부 등 조선에서 활동하던 외국인 성직자들이 바로 이곳에서 사형을 선고받았다. 왕권의 이름으로 신앙이 단죄되던 그 순간이, 오늘날 사람들이 무심히 오가는 종로 한복판에 조용히 새겨져 있다.', '앵베르 주교 등 기해박해·병인박해 순교 성직자들이 사형을 선고받은 조선시대 의금부 터.', '의금부 터 - 사형이 선고된 자리', '서울 종로 의금부터, 앵베르 주교·베르뇌 주교 등 순교 성직자들이 사형선고를 받은 조선시대 최고 사법기관 터.', '치유', NULL, NULL),
  ('전옥서 터', '순교성지', '서울대', '서울', '서울시 종로구 서린동', '광화문 사거리 동쪽 서린동, 형조에 속해 죄인을 가두던 옥이 있던 자리. 형조에서 문초받은 천주교 신자들은 형이 집행되기 전까지 이곳에 갇혀 지내야 했다. 103위 성인 중 이호영 베드로와 김 바르바라는 혹독한 옥살이 끝에 이곳에서 순교했고, 1801년 전주에서 압송된 유항검과 윤지헌도 이곳에 갇혔다가 의금부로 끌려가 국문을 받았다. 처형장이 아닌 감옥에서 죽어간 이들의 조용한 순교가 이 자리에 새겨져 있다.', '이호영 베드로·김 바르바라가 옥살이 끝에 순교한 조선시대 감옥 터. 유항검·윤지헌도 이곳에 투옥.', '전옥서 터 - 옥살이로 순교한 이들의 자리', '서울 서린동 전옥서터, 이호영 베드로·김 바르바라가 옥살이 끝에 순교한 조선시대 감옥 터.', '치유', NULL, NULL),
  ('종로 성당', '성당', '서울대', '서울', '서울시 종로구 인의동 167', '종로 한복판, 좌·우포도청이 있던 자리 가까이에 세워진 포도청 순례지 성당. 좌포도청은 지금의 옛 단성사 인근에서 한양 동·중·남부를, 우포도청은 광화문우체국과 일민미술관 사이에서 서·북부를 관할하며 임금의 호위와 도성 순찰을 맡았다. 1784년 한국천주교회가 창립된 뒤로 신자를 색출하는 일이 두 포도청의 주요 임무가 되면서, 수많은 신자가 이곳에서 체포되고 취조받았다. 오늘날 종로성당은 그 아픈 역사를 기억하며 순례객들을 맞고 있다.', '좌·우포도청 인근에 세워진 순례지 성당. 조선시대 포도청은 천주교 신자 색출·체포의 주요 기관이었다.', '종로 성당 - 포도청 순례지의 기억', '서울 종로성당, 좌·우포도청 인근에 세워진 포도청 순례지 성당. 조선시대 천주교 신자 체포의 역사를 기억하는 곳.', '위로', NULL, NULL),
  ('좌포도청 터', '순교성지', '서울대', '서울', '서울시 종로구 묘동 (옛 단성사 인근)', '종로 묘동, 옛 단성사 극장 인근에 한양 동·중·남부를 관할하던 좌포도청이 있었다. 우포도청과 함께 천주교 신자 색출의 두 축을 이루었던 이곳에서도 수많은 신자가 체포되어 취조받았다. 지금은 극장가와 상가가 들어선 번화한 거리 속에, 신앙을 지키려던 이들이 마지막으로 자유를 잃은 자리라는 사실이 조용히 묻혀 있다.', '조선시대 한양 동·중·남부를 관할한 포도청, 천주교 신자 체포·취조의 중심지.', '좌포도청 터 - 번화가에 묻힌 순교의 기억', '서울 종로 좌포도청터, 조선시대 천주교 신자 체포·취조가 이뤄진 포도청 자리. 우포도청과 함께 순교사의 한 장면.', '위로', NULL, NULL),
  ('한국 순교자 103위 시성 터', '역사사적지', '서울대', '서울', '서울시 영등포구 여의도동 (여의도공원)', '여의도공원 잔디마당, 1984년 5월 6일 요한 바오로 2세 교황이 방한해 집전한 한국천주교회 200주년 기념 신앙대회와 103위 시성식이 열린 자리. 백 년 넘게 이어진 박해 속에 만 명 넘는 신자가 순교한 가운데, 1925년 79위, 1968년 24위가 먼저 시복되었고 이날 마침내 103위 모두가 성인으로 선포되었다. 로마가 아닌 현지에서 거행된 사상 최대 규모의 시성식이었다. 2009년 시성 25주년을 맞아 한국순교자현양위원회가 이 자리에 기념 표석을 세웠다.', '1984년 5월 6일 요한 바오로 2세 교황이 103위 순교자를 시성한 자리. 로마 밖에서 거행된 최대 규모 시성식.', '한국 순교자 103위 시성 터 - 여의도의 시성식', '서울 여의도공원, 1984년 요한 바오로 2세 교황이 103위 순교자를 시성한 자리. 2009년 세워진 기념 표석.', '감사', NULL, NULL),
  ('한국 천주교회 창립 터', '역사사적지', '서울대', '서울', '서울시 중구 명동1가 일대', '명동 번화가, 지금은 흔적 없이 사라졌지만 한국천주교회가 공식적으로 시작된 자리가 있다. 명례방이라 불리던 이곳 김범우의 집에서 이벽의 주도로 1784년 겨울부터 정약용 형제와 이승훈, 권일신 등이 정기적으로 모여 신앙 모임인 취회를 열었다. 사제 없이 평신도들 스스로 신앙 공동체를 시작한 이 명례방 모임이야말로 한국천주교회의 공식적인 출발점으로 꼽힌다.', '1784년 이벽 주도로 정기적인 신앙 모임(취회)이 시작된 명례방 공동체 터. 한국천주교회의 공식 출발점.', '한국 천주교회 창립 터 - 명례방 신앙 공동체의 시작', '서울 명동 한국천주교회창립터, 1784년 이벽 주도로 시작된 명례방 신앙 공동체. 사제 없이 평신도가 세운 교회의 출발점.', '새출발', NULL, NULL),
  ('형조 터', '순교성지', '서울대', '서울', '서울시 종로구 세종대로 일대', '세종대로 인근, 조선시대 사법 행정을 총괄하던 형조가 있던 자리. 1785년 을사추조적발사건 당시 이벽, 김범우, 정약전·정약용 형제, 이승훈, 권일신 등 초기 신앙 공동체 구성원들이 이곳으로 압송되어 문초를 받았다. 이후에도 수많은 천주교 신자들이 이 자리에서 고문받고 신앙을 증거했으며, 오늘날 우포도청 터, 경기감영 터와 함께 서울 순례길 생명의 길 코스로 이어져 도심 속에서 이들의 자취를 되짚어볼 수 있다.', '1785년 을사추조적발사건 때 이벽·김범우 등이 문초받은 조선시대 형조 터. 서울 순례길 생명의 길 코스 포함.', '형조 터 - 을사추조적발사건의 현장', '서울 세종대로 형조터, 1785년 을사추조적발사건 때 초기 신앙 공동체가 문초받은 조선시대 형조 자리.', '위로', NULL, NULL)
